/// I riti propiziatori e le loro fonti, per raccolta e chiave
/// (`<raccolta>|<chiave>|<chiave>...`). Si leggono da
/// `IRitiPropiziatori`.
abstract final class IRitiPropiziatoriDati {
  static const Map<String, String> riti = {
    'contemplazione_dei_tarocchi|Asso di Bastoni|dritta': 'Tieni la carta davanti agli occhi e accendi quattro respiri vivi, rapidi all\'entrata e lenti all\'uscita. Guarda il bastone che spunta dalla mano fra le nuvole, con le sue foglie nuove. Ripeti tre volte: «Afferro la scintilla finché è viva». Poi apri le dita.',
    'contemplazione_dei_tarocchi|Asso di Bastoni|rovesciata': 'Respira sei volte con la carta davanti, lasciando che il fiato scaldi il petto. Osserva le foglie che spuntano dal legno, anche se il bastone è uno soltanto. Ripeti cinque volte, piano: «Ritrovo il desiderio prima di accendere». Lascia che la voce prenda calore a poco a poco.',
    'contemplazione_dei_tarocchi|Asso di Coppe|dritta': 'Lascia che la carta ti stia davanti per sette respiri fluidi, come acqua che scorre. Guarda la coppa traboccante che la mano offre dalle nuvole. Ripeti tre volte, con voce morbida: «Apro il cuore e lascio scorrere». Poi posa una mano sul petto e resta così.',
    'contemplazione_dei_tarocchi|Asso di Coppe|rovesciata': 'Per cinque respiri guarda lo schermo, lasciando che l\'aria arrivi sotto lo sterno. Segui con gli occhi il bordo della coppa, dove l\'acqua vorrebbe uscire. Ripeti sette volte, sottovoce: «Mi concedo di sentire». Ogni volta lascia andare un\'espirazione più lunga, come acqua che trabocca.',
    'contemplazione_dei_tarocchi|Asso di Denari|dritta': 'Con i piedi posati a terra, contempla la carta per quattro respiri pieni. Osserva il grande disco d\'oro offerto dalla mano, solido come un seme maturo. Ripeti sette volte: «Pianto il seme in terra buona». Poi senti il pavimento sotto di te, fermo e paziente come la terra.',
    'contemplazione_dei_tarocchi|Asso di Denari|rovesciata': 'Per sei respiri tieni gli occhi sulla carta, senza lasciarli andare altrove. Segui il bordo del disco d\'oro tutto intorno, finché lo vedi intero. Ripeti tre volte: «Guardo bene ciò che ho davanti». Poi alza gli occhi intorno a te, come per un primo sguardo.',
    'contemplazione_dei_tarocchi|Asso di Spade|dritta': 'Guarda la carta per quattro respiri limpidi, con la schiena eretta. Segui la spada che sale dalla mano verso la corona, diritta e sottile. Ripeti sette volte, con voce chiara: «Dico il vero con parole limpide». Poi lascia che lo sguardo resti netto, come la lama.',
    'contemplazione_dei_tarocchi|Asso di Spade|rovesciata': 'Per sei respiri guarda lo schermo, lasciando che la mente si posi come polvere. Fermati sulla punta della spada, il punto più sottile della figura. Ripeti cinque volte: «Rischiaro la mente prima di parlare». Poi lascia passare qualche istante di silenzio.',
    'contemplazione_dei_tarocchi|Cavaliere di Bastoni|dritta': 'Lascia scorrere cinque respiri ardenti davanti alla carta. Guarda il cavallo lanciato in avanti e il bastone tenuto alto dal cavaliere. Ripeti tre volte, con slancio: «Oso, con gli occhi sulla meta». Poi raccogli l\'ardore in un respiro lento, lungo, che scende fino ai piedi.',
    'contemplazione_dei_tarocchi|Cavaliere di Bastoni|rovesciata': 'Tieni la carta sullo schermo e conta sette respiri, ognuno un poco più calmo. Guarda le redini nella mano del cavaliere: sono loro a dare una rotta alla corsa. Ripeti cinque volte: «Do una meta al mio ardore». Lascia che il fiato rallenti come un cavallo al passo.',
    'contemplazione_dei_tarocchi|Cavaliere di Coppe|dritta': 'Tieni lo schermo davanti a te e lascia scorrere cinque respiri lenti, al passo di un cavallo. Guarda il cavaliere che porge la coppa davanti a sé. Ripeti tre volte: «Offro il mio cuore con grazia». Poi lascia che il gesto della figura resti negli occhi.',
    'contemplazione_dei_tarocchi|Cavaliere di Coppe|rovesciata': 'Concediti sette respiri davanti alla carta, lasciando che si facciano regolari. Guarda la coppa tesa del cavaliere e chiediti che cosa contiene davvero. Ripeti cinque volte: «Guardo se alle parole seguono i gesti». Poi respira ancora, con lo sguardo sulla coppa e sulla mano.',
    'contemplazione_dei_tarocchi|Cavaliere di Denari|dritta': 'Al passo di un cavallo da lavoro, conta nove respiri lenti e uguali davanti alla carta. Osserva il cavaliere che regge il disco con calma, senza correre. Ripeti cinque volte: «Avanzo con costanza, senza fermarmi». Poi lascia il respiro al suo ritmo di sempre.',
    'contemplazione_dei_tarocchi|Cavaliere di Denari|rovesciata': 'Per sei respiri tieni gli occhi sullo schermo, poi muovi appena le dita. Guarda il cavallo e immagina che sollevi uno zoccolo, il primo. Ripeti sette volte: «Muovo qualcosa, anche di piccolo». Lascia che quel piccolo movimento basti per oggi, senza chiedergli di più.',
    'contemplazione_dei_tarocchi|Cavaliere di Spade|dritta': 'Tieni lo schermo davanti a te e lascia scorrere cinque respiri rapidi, poi uno lento. Guarda il cavaliere lanciato in avanti con la spada levata. Ripeti sette volte: «Vado allo scopo senza travolgere nessuno». Poi lascia che il ritmo rallenti, come zoccoli che si posano.',
    'contemplazione_dei_tarocchi|Cavaliere di Spade|rovesciata': 'Respira sette volte davanti alla carta, allungando ogni pausa fra un respiro e l\'altro. Osserva le zampe del cavallo e immagina che si posino a terra. Ripeti cinque volte: «Un istante di pausa vale più della velocità». Poi resta in quiete ancora un poco.',
    'contemplazione_dei_tarocchi|Cinque di Bastoni|dritta': 'Accogli l\'energia della figura per sei respiri vivaci, senza trattenerla. Segui i cinque bastoni che si incrociano in ogni direzione, come in una gara di idee. Ripeti sette volte: «Uso la sfida per crescere, non per ferire». Poi lascia ricadere le braccia lungo i fianchi.',
    'contemplazione_dei_tarocchi|Cinque di Bastoni|rovesciata': 'Rallenta con quattro respiri davanti alla carta, uno per ogni pensiero di troppo. Cerca, fra i bastoni incrociati, quello che puoi lasciare cadere. Ripeti tre volte, sottovoce: «Scelgo le battaglie che contano». Lascia scivolare via le altre insieme all\'aria che esce.',
    'contemplazione_dei_tarocchi|Cinque di Coppe|dritta': 'Lascia scendere sei respiri lenti davanti alla carta, senza fretta di stare meglio. Guarda le coppe versate, poi cerca quelle ancora in piedi. Ripeti sette volte, a voce bassa: «Il dolore è vero ma non è tutto». Poi fermati sulle coppe intere, ancora un respiro.',
    'contemplazione_dei_tarocchi|Cinque di Coppe|rovesciata': 'Per cinque respiri guarda la carta, lasciando che il volto si sollevi appena. Porta gli occhi dalle coppe rovesciate alle coppe che restano. Ripeti tre volte: «Mi volto verso ciò che c\'è ancora». Lascia che la voce si apra un poco a ogni ripetizione, come una finestra.',
    'contemplazione_dei_tarocchi|Cinque di Denari|dritta': 'Guarda la carta per sei respiri caldi, come se scaldassi le mani a un fuoco. Fra i cinque dischi cerca quello più luminoso, come una finestra accesa nella notte. Ripeti cinque volte, piano: «Chiedo aiuto senza vergogna». Poi pensa a una porta a cui bussare.',
    'contemplazione_dei_tarocchi|Cinque di Denari|rovesciata': 'Respira sette volte davanti allo schermo, lasciando che ogni respiro scaldi un poco di più. Segui i cinque dischi dal più scuro al più chiaro. Ripeti tre volte: «Riaccolgo la fiducia, passo dopo passo». Poi lascia che il tepore resti, mentre torni alla tua giornata.',
    'contemplazione_dei_tarocchi|Cinque di Spade|dritta': 'Resta davanti alla figura per sei respiri, senza alzare la voce dentro di te. Guarda le cinque spade e chiediti quante ne servono davvero. Ripeti sette volte: «Mi chiedo se questa vittoria vale ciò che perdo». Poi lascia la domanda aperta.',
    'contemplazione_dei_tarocchi|Cinque di Spade|rovesciata': 'Respira cinque volte guardando lo schermo, lasciando scendere le spalle. Immagina di posare a terra una spada alla volta, fino all\'ultima. Ripeti tre volte: «Faccio il primo passo verso la pace». Poi lascia che il respiro si allarghi nello spazio delle armi posate.',
    'contemplazione_dei_tarocchi|Dieci di Bastoni|dritta': 'Raddrizza la schiena davanti allo schermo e respira sei volte, sentendo il peso sulle spalle. Guarda i dieci bastoni stretti tutti insieme in un fascio. Ripeti sette volte: «Porto ciò che è mio e poso il resto». A ogni ripetizione immagina di posarne uno, con delicatezza, a terra.',
    'contemplazione_dei_tarocchi|Dieci di Bastoni|rovesciata': 'Per cinque respiri guarda lo schermo, espirando come chi posa un carico. Conta i bastoni del fascio e scegline uno che non ti appartiene. Ripeti tre volte: «Alleggerirmi non tradisce nessuno». Poi respira a fondo, con le spalle sciolte e le mani vuote.',
    'contemplazione_dei_tarocchi|Dieci di Coppe|dritta': 'Lascia scorrere sei respiri ampi davanti alla carta. Segui l\'arco delle dieci coppe, come un arcobaleno sopra una casa abitata. Ripeti sette volte, con voce calda: «Ringrazio per i legami che ho». Poi pensa alle persone che ami, una alla volta, con il loro nome.',
    'contemplazione_dei_tarocchi|Dieci di Coppe|rovesciata': 'Per cinque respiri guarda lo schermo, lasciando le mani aperte sulle ginocchia. Cerca nell\'arco delle coppe il punto in cui sembra incrinarsi. Ripeti tre volte: «Ricucio con parole pazienti». Poi lascia che la frase prepari un gesto verso chi ti è vicino, una parola gentile.',
    'contemplazione_dei_tarocchi|Dieci di Denari|dritta': 'Lascia scorrere sei respiri profondi davanti alla carta, lenti come radici che crescono. Segui i dieci dischi disposti come i rami di un albero antico. Ripeti tre volte: «Pianto qualcosa che dura oltre me». Poi pensa alle tue radici, a chi c\'era prima di te.',
    'contemplazione_dei_tarocchi|Dieci di Denari|rovesciata': 'Guarda lo schermo per quattro respiri, sentendo il pavimento sotto i piedi. Fermati sul disco più in basso, quello che regge gli altri. Ripeti cinque volte: «Curo ciò che dura davvero». Poi lascia che lo sguardo risalga piano tutta la figura, disco dopo disco.',
    'contemplazione_dei_tarocchi|Dieci di Spade|dritta': 'Metti la figura al centro dello sguardo per sei respiri profondi, fino in fondo. Guarda le dieci spade, poi cerca nella figura il punto più chiaro. Ripeti sette volte: «Da qui si può soltanto risalire». Poi solleva piano lo sguardo verso quel punto chiaro.',
    'contemplazione_dei_tarocchi|Dieci di Spade|rovesciata': 'Lascia salire cinque respiri, uno sopra l\'altro, come gradini. Guarda le spade dall\'alto verso il basso, poi risali con lo sguardo fino al bordo superiore. Ripeti tre volte: «Mi rialzo con dolcezza e senza fretta». Poi lascia che lo sguardo resti in alto.',
    'contemplazione_dei_tarocchi|Due di Bastoni|dritta': 'Allarga lo sguardo sulla carta e lascia scorrere cinque respiri ampi. Guarda i due bastoni e lo spazio che lasciano aperto fra loro, come una via verso il largo. Ripeti sette volte: «Scelgo la rotta e guardo lontano». Poi chiudi gli occhi un istante.',
    'contemplazione_dei_tarocchi|Due di Bastoni|rovesciata': 'Prima di ogni altra cosa, tre respiri lenti con gli occhi sulla carta. Poi guarda il vuoto fra i due bastoni, come una porta da attraversare. Ripeti cinque volte, sottovoce: «Chiarisco ciò che voglio, poi faccio un passo». Respira ancora due volte prima di alzare lo sguardo.',
    'contemplazione_dei_tarocchi|Due di Coppe|dritta': 'Distendi il viso e concedi alla carta sei respiri tranquilli. Osserva le due coppe che si avvicinano, una di fronte all\'altra, come due mani che si cercano. Ripeti tre volte: «Coltivo con cura questo legame». Poi resta ancora un respiro sulla figura.',
    'contemplazione_dei_tarocchi|Due di Coppe|rovesciata': 'Respira quattro volte davanti alla carta, lentamente, con le mani aperte. Guarda lo spazio fra le due coppe e immagina che si accorci a ogni respiro. Ripeti cinque volte, piano: «Ascolto davvero prima di rispondere». Lascia che la frase prepari la prossima parola che dici.',
    'contemplazione_dei_tarocchi|Due di Denari|dritta': 'Lascia andare cinque respiri leggeri, quasi danzati, davanti alla carta. Guarda i due dischi e il nastro che li avvolge in un unico movimento. Ripeti sette volte, con leggerezza: «Tengo il ritmo senza irrigidirmi». Poi lascia oscillare piano le spalle, come un giocoliere.',
    'contemplazione_dei_tarocchi|Due di Denari|rovesciata': 'Respira quattro volte con gli occhi sullo schermo, lasciando cadere un pensiero a ogni uscita. Guarda il nastro che lega i due dischi e scegli quale tenere per primo. Ripeti cinque volte: «Scelgo le priorità e tengo bene poche cose». Poi riposa lo sguardo.',
    'contemplazione_dei_tarocchi|Due di Spade|dritta': 'Distendi le braccia e respira cinque volte, lentamente, guardando la carta. Guarda le due spade incrociate e il punto in cui si toccano. Ripeti tre volte: «Guardo ciò che sto evitando». Poi apri bene gli occhi sulla carta, senza abbassarli.',
    'contemplazione_dei_tarocchi|Due di Spade|rovesciata': 'Respira sette volte davanti alla carta, sciogliendo le braccia a ogni uscita. Guarda le spade incrociate e immagina di separarle con calma, una a destra e una a sinistra. Ripeti cinque volte: «Affronto adesso la scelta che rimandavo». Lascia l\'ultima parola nell\'aria.',
    'contemplazione_dei_tarocchi|Fante di Bastoni|dritta': 'Guarda la carta per quattro respiri curiosi, come chi apre una lettera. Osserva il giovane che tiene il bastone e lo guarda con meraviglia, come una cosa appena trovata. Ripeti sette volte, con voce viva: «Seguo l\'idea nuova che bussa». Poi sorridi alla figura.',
    'contemplazione_dei_tarocchi|Fante di Bastoni|rovesciata': 'Respira sei volte con gli occhi sulla carta, lasciando che l\'impazienza si posi. Fermati sulle mani del giovane intorno al bastone: tengono, non lanciano. Ripeti cinque volte: «Do forma al mio slancio prima che svanisca». Poi scegli un gesto, uno soltanto, da compiere oggi.',
    'contemplazione_dei_tarocchi|Fante di Coppe|dritta': 'Guarda la carta per quattro respiri leggeri, come si guarda l\'acqua in un bicchiere. Osserva il giovane che tiene la coppa e la osserva con stupore. Ripeti sette volte, piano: «Do spazio all\'emozione che nasce». Poi accogli ciò che senti, senza dargli subito un nome.',
    'contemplazione_dei_tarocchi|Fante di Coppe|rovesciata': 'Respira sei volte davanti alla carta, con le spalle morbide. Fermati sulle mani del giovane che tengono la coppa con delicatezza, senza stringerla. Ripeti cinque volte: «Custodisco la mia sensibilità senza murarla». Lascia che l\'ultima volta sia la più tenera, quasi una carezza.',
    'contemplazione_dei_tarocchi|Fante di Denari|dritta': 'Tieni la carta davanti e lascia andare cinque respiri attenti, come chi studia. Guarda il giovane che regge il disco e lo osserva con cura, senza fretta. Ripeti sette volte: «Coltivo l\'idea nuova con pazienza». Poi scegli il primo passo da studiare oggi.',
    'contemplazione_dei_tarocchi|Fante di Denari|rovesciata': 'Respira sei volte con gli occhi sulla carta, riportando lo sguardo ogni volta che scappa. Osserva le mani del giovane intorno al disco, ancora immobili. Ripeti tre volte: «Riprendo il lavoro con un piccolo gesto». Poi muovi le mani, come per cominciare adesso.',
    'contemplazione_dei_tarocchi|Fante di Spade|dritta': 'Come chi osserva il vento, resta sulla carta per quattro respiri attenti. Osserva il giovane con la spada levata e lo sguardo rivolto lontano. Ripeti cinque volte: «Osservo con cura e scelgo le parole». Poi resta un istante in ascolto dei suoni intorno.',
    'contemplazione_dei_tarocchi|Fante di Spade|rovesciata': 'Per sei respiri tieni gli occhi sullo schermo, con le labbra chiuse. Fermati sulla lama del giovane e immagina di abbassarla piano. Ripeti tre volte, sottovoce: «Verifico prima di parlare». Poi lascia passare un respiro intero prima di ogni parola che dici oggi.',
    'contemplazione_dei_tarocchi|Gli Amanti|dritta': 'Lascia la carta davanti agli occhi per sette respiri tranquilli. Guarda le due figure sotto la presenza alata che le sovrasta, poi lo spazio che le separa e insieme le unisce. Ripeti tre volte, con voce calda: «Scelgo con la testa e col cuore insieme». Respira ancora.',
    'contemplazione_dei_tarocchi|Gli Amanti|rovesciata': 'Volgi lo sguardo allo schermo e respira cinque volte, lentamente. Cerca il punto della figura in cui il desiderio chiede verità, là dove gli sguardi non si incontrano. Ripeti sette volte, a mezza voce: «Prima di scegliere, mi dico la verità». Poi lascia riposare il respiro.',
    'contemplazione_dei_tarocchi|Il Carro|dritta': 'Tieni lo schermo ben fermo e lascia scorrere sei respiri decisi. Guarda le due creature del traino, diverse fra loro, che tirano verso la stessa meta. Pronuncia sette volte, con voce salda: «Tengo la direzione, le forze mi seguono». Poi lascia riposare lo sguardo sul conducente.',
    'contemplazione_dei_tarocchi|Il Carro|rovesciata': 'Per quattro respiri resta sulla figura, lasciando che il fiato si allunghi. Guarda il conducente al centro del carro: la sua forza viene dallo stare nel mezzo, senza strattoni. Ripeti cinque volte: «Torno al centro, poi riprendo la strada». Senti il peso posarsi sul sedile.',
    'contemplazione_dei_tarocchi|Il Diavolo|dritta': 'Mettiti di fronte alla figura dipinta per sei respiri, senza distogliere lo sguardo. Guarda i legami al collo delle due piccole figure: sono larghi, potrebbero sfilarsi. Ripeti tre volte, con voce chiara: «Nomino ciò che mi lega e lo guardo». Poi espira lentamente, fino in fondo.',
    'contemplazione_dei_tarocchi|Il Diavolo|rovesciata': 'Concedi cinque respiri alla carta sullo schermo, lasciando che il petto si apra. Cerca il punto in cui il legame passa intorno al collo e immagina di allentarlo con due dita. Ripeti sette volte: «Sciolgo con dolcezza il nodo che vedo». Lascia scendere le spalle.',
    'contemplazione_dei_tarocchi|Il Giudizio|dritta': 'Porta la figura all\'altezza degli occhi e lascia salire sette respiri, uno dopo l\'altro. Guarda l\'angelo con la tromba e le figure che si alzano a rispondere. Ripeti tre volte, con voce limpida: «Rispondo alla chiamata di una vita più vera». Poi lascia risuonare il silenzio.',
    'contemplazione_dei_tarocchi|Il Giudizio|rovesciata': 'Guarda lo schermo per cinque respiri, senza giudicare nemmeno il respiro. Fermati sulle braccia aperte delle figure che ascoltano il suono della tromba. Ripeti sette volte, con voce bassa e lenta: «Mi ascolto prima di giudicarmi». Lascia che la voce si addolcisca a ogni ripetizione.',
    'contemplazione_dei_tarocchi|Il Mago|dritta': 'Fissa la carta sullo schermo e respira sei volte, lasciando che l\'aria arrivi fino in fondo. Segui la mano alzata verso il cielo, poi l\'altra che indica la terra sopra gli strumenti del tavolo. Ripeti sette volte, con voce piena: «Ciò che penso diventa gesto adesso».',
    'contemplazione_dei_tarocchi|Il Mago|rovesciata': 'Resta con gli occhi sulla figura per cinque respiri lunghi. Guarda gli strumenti posati sul tavolo, uno per uno, come attrezzi che aspettano una mano. Poi, a voce bassa, ripeti tre volte: «Le mie parole e le mie mani vanno insieme». Chiudi con un respiro più lento.',
    'contemplazione_dei_tarocchi|Il Matto|dritta': 'Tieni la carta davanti agli occhi sullo schermo e lascia scendere cinque respiri lenti. Guarda il fagotto sulla spalla, poi il piede sospeso sull\'orlo del dirupo. Quando lo sguardo si fa quieto, ripeti tre volte a voce bassa: «Faccio il primo passo con fiducia».',
    'contemplazione_dei_tarocchi|Il Matto|rovesciata': 'Porta lo schermo all\'altezza dello sguardo e conta quattro respiri, senza fretta. Osserva il cane che abbaia accanto ai piedi: è il richiamo che avverte prima del salto. Pronuncia cinque volte, piano: «Guardo dove metto il piede, poi scelgo». Lascia che la frase rallenti il passo.',
    'contemplazione_dei_tarocchi|Il Mondo|dritta': 'Lascia che la carta ti riempia lo sguardo per nove respiri ampi. Segui la ghirlanda che racchiude la figura danzante, poi le quattro creature agli angoli. Ripeti tre volte: «Accolgo ciò che si è compiuto». Poi resta un momento dentro quel cerchio, senza uscirne subito.',
    'contemplazione_dei_tarocchi|Il Mondo|rovesciata': 'Per sei respiri tieni gli occhi sulla carta, lentamente. Cerca il punto in cui la ghirlanda si chiude: lì manca soltanto un nodo da stringere. Ripeti cinque volte, con voce calma: «Porto a termine l\'ultimo tratto». Lascia che l\'ultima volta suoni come un punto fermo.',
    'contemplazione_dei_tarocchi|Il Papa|dritta': 'Con la carta davanti agli occhi, conta quattro respiri come si contano i grani di una corona. Guarda la mano alzata a benedire e le due figure raccolte ai piedi del trono. Ripeti tre volte, piano: «Accolgo la guida che viene da lontano». Poi resta in ascolto.',
    'contemplazione_dei_tarocchi|Il Papa|rovesciata': 'Prenditi sei respiri davanti allo schermo, senza cercare risposte. Guarda le due figure inginocchiate e chiediti quale insegnamento ricevuto senti ancora tuo. Mormora cinque volte: «Tengo ciò che mi fa respirare, il resto lo rivedo». Lascia che l\'ultima volta sia la più lenta.',
    'contemplazione_dei_tarocchi|Il Sole|dritta': 'Lascia entrare quattro respiri ampi davanti alla carta, come aria in una mattina d\'estate. Guarda i raggi che scendono sulla figura giovane e la scaldano tutta. Ripeti tre volte, sorridendo se ti viene: «Lascio splendere ciò che sono». Poi resta un momento in quella luce.',
    'contemplazione_dei_tarocchi|Il Sole|rovesciata': 'Concediti sei respiri davanti allo schermo, con il viso rilassato. Guarda il muro basso dietro la figura giovane: copre poco, la luce lo supera. Ripeti cinque volte, piano: «Lascio cadere la nube e sento il calore». Lascia che la frase scaldi la voce mentre la pronunci.',
    'contemplazione_dei_tarocchi|L\'Appeso|dritta': 'Rimani con gli occhi sulla figura capovolta per sette respiri lenti. Osserva il volto quieto nonostante la posizione, le gambe incrociate, le mani dietro la schiena. Ripeti tre volte, quasi in un soffio: «Fermarmi mi mostra ciò che prima non vedevo». Poi lascia la carta ancora un momento.',
    'contemplazione_dei_tarocchi|L\'Appeso|rovesciata': 'Guarda lo schermo per quattro respiri, sentendo i piedi ben posati a terra. Poi segui la corda che lega la figura al legno e chiediti se quell\'attesa ti insegna ancora qualcosa. Ripeti cinque volte: «Scelgo se aspettare ancora o tornare ad agire». Respira con calma.',
    'contemplazione_dei_tarocchi|L\'Eremita|dritta': 'Abbassa le luci se puoi e tieni la carta davanti agli occhi per nove respiri. Segui la lanterna alzata e la piccola luce che brilla dentro. Ripeti tre volte, a voce bassissima: «Un passo alla volta, la mia luce basta». Poi resta ancora nel silenzio.',
    'contemplazione_dei_tarocchi|L\'Eremita|rovesciata': 'Guarda lo schermo per sei respiri, lasciando che l\'aria entri piano. Osserva il bastone a cui la figura si appoggia: aiuta a camminare, anche verso gli altri. Pronuncia cinque volte: «La mia lanterna illumina anche la strada del ritorno». Chiudi aprendo lo sguardo intorno a te.',
    'contemplazione_dei_tarocchi|L\'Imperatore|dritta': 'Siedi con la schiena eretta e guarda la carta per sei respiri pieni. Osserva il trono di pietra squadrata, le teste d\'ariete scolpite, il globo nella mano. Pronuncia tre volte, con voce ferma: «Do forma salda a ciò che costruisco». Poi lascia andare le spalle.',
    'contemplazione_dei_tarocchi|L\'Imperatore|rovesciata': 'Davanti allo schermo lascia passare cinque respiri, più lunghi nell\'uscita che nell\'entrata. Fermati sull\'armatura sotto il mantello: chiediti dove l\'ordine ti tiene in piedi e dove ti stringe. Ripeti sette volte: «Scelgo l\'ordine che protegge, non quello che chiude». Poi lascia andare la stretta.',
    'contemplazione_dei_tarocchi|L\'Imperatrice|dritta': 'Accomoda lo schermo davanti a te e concediti cinque respiri morbidi. Lascia scorrere gli occhi sul grano maturo ai piedi del trono, poi sullo scettro che la figura regge con calma. Ripeti sette volte, con voce piana: «Nutro ciò che cresce e rispetto i suoi tempi».',
    'contemplazione_dei_tarocchi|L\'Imperatrice|rovesciata': 'Per quattro respiri tieni gli occhi sulla figura, lasciando che le spalle si abbassino. Guarda lo scudo appoggiato accanto al trono, col suo segno inciso. Poi, a voce bassa, ripeti cinque volte: «Anche io ricevo la cura che do». Senti la frase tornare verso di te, come un\'onda.',
    'contemplazione_dei_tarocchi|La Forza|dritta': 'Davanti alla carta, prenditi sei respiri dolci e profondi. Posa lo sguardo sulle mani della figura che chiudono piano le fauci del leone, senza stringere. Ripeti sette volte, con tenerezza: «Tengo l\'istinto con mano gentile e ferma». Senti le tue mani ammorbidirsi in grembo.',
    'contemplazione_dei_tarocchi|La Forza|rovesciata': 'Senza alcuno sforzo, lascia la carta davanti a te per cinque respiri lunghi. Guarda la curva dell\'infinito sopra il capo della figura, poi il muso del leone che si placa. Ripeti cinque volte: «Torno a trattarmi con mitezza». Lascia andare ogni stretta.',
    'contemplazione_dei_tarocchi|La Giustizia|dritta': 'Porta gli occhi sulla carta e misura cinque respiri uguali, come due piatti in pari. Guarda la bilancia in una mano e la spada diritta nell\'altra. Ripeti tre volte, chiaramente: «Agisco con onestà e accolgo ciò che ho seminato». Poi lascia il respiro in equilibrio.',
    'contemplazione_dei_tarocchi|La Giustizia|rovesciata': 'Respira sette volte davanti allo schermo, con calma, finché il fiato si fa regolare. Fermati sullo sguardo diritto della figura: non accusa, guarda. Poi ripeti cinque volte, sottovoce: «Guardo in faccia ciò che rimando». Lascia che la frase trovi il suo peso dentro di te.',
    'contemplazione_dei_tarocchi|La Luna|dritta': 'Abbassa la luce intorno a te e guarda la carta per sei respiri lenti. Segui il sentiero che sale dall\'acqua fra le due torri, sotto il volto pallido nel cielo. Ripeti tre volte, in un sussurro: «Procedo con intuito anche dove non vedo». Poi lascia che gli occhi si abituino.',
    'contemplazione_dei_tarocchi|La Luna|rovesciata': 'Tieni gli occhi sullo schermo per cinque respiri, lasciandoli allungare. Guarda la creatura che esce dall\'acqua e i due cani che ululano: alla luce sono più piccoli di quanto sembrano. Ripeti sette volte: «Guardo con occhi nuovi ciò che temevo». Poi apri piano lo sguardo.',
    'contemplazione_dei_tarocchi|La Morte|dritta': 'Posa gli occhi sulla figura dipinta e lascia andare sei respiri, uno dopo l\'altro. Osserva il passo lento della figura scura: avanza senza voltarsi indietro. Ripeti sette volte, lentamente: «Lascio finire ciò che ha finito, accolgo il nuovo». Poi lascia uscire un respiro lungo.',
    'contemplazione_dei_tarocchi|La Morte|rovesciata': 'Per cinque respiri tieni gli occhi sullo schermo, aprendo piano le mani in grembo. Guarda ciò che sta ai piedi della figura: tutto quello che cade fa spazio. Ripeti tre volte, con voce quieta: «Apro la mano e lascio passare il cambiamento». Lascia che la mano resti aperta.',
    'contemplazione_dei_tarocchi|La Papessa|dritta': 'Fai silenzio intorno e lascia la carta davanti agli occhi per sette respiri. Posa lo sguardo sul rotolo stretto in grembo, poi sul velo teso fra le due colonne. Senza muovere quasi le labbra, ripeti tre volte: «Ascolto nel silenzio ciò che so già». Lascia il resto fuori.',
    'contemplazione_dei_tarocchi|La Papessa|rovesciata': 'Abbassa il rumore che hai intorno, poi guarda lo schermo per sei respiri quieti. Cerca la falce di luna ai piedi della figura, quasi nascosta dal mantello. Sussurra cinque volte: «Do spazio alla voce che sa». Ogni ripetizione più lenta della precedente, finché la voce diventa un soffio.',
    'contemplazione_dei_tarocchi|La Ruota della Fortuna|dritta': 'Lascia girare cinque respiri, come giri lenti di una ruota, davanti alla carta. Segui il cerchio da una figura all\'altra, senza fermarti su nessuna. Ripeti sette volte, con voce leggera: «Mi muovo con la ruota, non contro». L\'ultima volta lascia che la voce si spenga.',
    'contemplazione_dei_tarocchi|La Ruota della Fortuna|rovesciata': 'Lascia la carta sullo schermo e conta quattro respiri, sostando un istante dopo ognuno. Guarda il mozzo della ruota, l\'unico punto che resta immobile mentre tutto gira. Ripeti tre volte: «Nella sosta raccolgo le forze per il prossimo giro». Poi riprendi a respirare come viene.',
    'contemplazione_dei_tarocchi|La Stella|dritta': 'Lascia che la carta ti stia davanti per nove respiri morbidi, come in una notte limpida. Guarda l\'acqua che scorre dalle due brocche e la grande stella sopra il capo. Ripeti sette volte, con voce lieve: «Mi affido a questa luce quieta». Poi resta a guardarla.',
    'contemplazione_dei_tarocchi|La Stella|rovesciata': 'Per sette respiri guarda lo schermo, lasciando che l\'aria scenda piano. Conta le piccole stelle intorno alla grande, una per una, fino all\'ultima. Ripeti cinque volte: «La luce c\'è anche quando è velata». Lascia che ogni volta la voce si faccia un poco più chiara.',
    'contemplazione_dei_tarocchi|La Temperanza|dritta': 'Davanti alla carta, fai scorrere sette respiri regolari, come acqua da un vaso all\'altro. Guarda il getto sottile fra le due coppe, che non si interrompe mai. Ripeti tre volte: «Unisco con pazienza ciò che sembrava diviso». Poi resta nella misura del respiro, senza contarlo.',
    'contemplazione_dei_tarocchi|La Temperanza|rovesciata': 'Rallenta prima di tutto, poi guarda lo schermo per cinque respiri. Fermati sulle due coppe tenute ad altezze diverse e sul filo d\'acqua che le lega. Ripeti sette volte, piano: «Rallento e ritrovo la mia misura». Fra una ripetizione e l\'altra lascia passare un respiro intero.',
    'contemplazione_dei_tarocchi|La Torre|dritta': 'Davanti alla carta, concediti quattro respiri profondi, restando con i piedi a terra. Segui il lampo che colpisce la cima, poi le pietre che cadono nell\'aria. Ripeti cinque volte: «Ciò che è vero resta in piedi». Ascolta il silenzio che viene dopo l\'ultima ripetizione, senza riempirlo.',
    'contemplazione_dei_tarocchi|La Torre|rovesciata': 'Tieni lo schermo davanti agli occhi e concediti sei respiri, uno per ogni pensiero che lasci cadere. Guarda la costruzione ancora in piedi sotto il fulmine. Ripeti tre volte, sottovoce: «Lascio cadere ciò che regge soltanto in apparenza». Poi respira ancora, adagio, guardando la base.',
    'contemplazione_dei_tarocchi|Nove di Bastoni|dritta': 'Raccogli le forze a ogni entrata, per sei respiri, con gli occhi sulla carta. Osserva i nove bastoni allineati come una palizzata che regge ancora. Ripeti tre volte, con voce salda: «Manca l\'ultimo tratto, lo percorro». Poi lascia riposare le mani, aperte sulle ginocchia.',
    'contemplazione_dei_tarocchi|Nove di Bastoni|rovesciata': 'Lascia che quattro respiri lenti ti portino davanti alla carta. Cerca fra i nove bastoni uno spiraglio da cui passa la luce. Ripeti cinque volte, piano: «Abbasso lo scudo per chi vuole avvicinarsi». A ogni ripetizione allarga un poco le spalle, come una porta che si socchiude.',
    'contemplazione_dei_tarocchi|Nove di Coppe|dritta': 'Volgi gli occhi alla figura dipinta e lascia andare quattro respiri contenti. Guarda le nove coppe disposte in ordine, come sopra una mensola in festa. Ripeti tre volte, con gratitudine: «Mi concedo di godere ciò che ho ottenuto». Poi lascia distendere il volto in un sorriso.',
    'contemplazione_dei_tarocchi|Nove di Coppe|rovesciata': 'Respira sette volte con gli occhi sulla carta, lasciando scendere l\'aria fino in fondo. Conta le coppe e chiediti quali sono piene davvero. Ripeti cinque volte: «Cerco la gioia che tocca il profondo». Lascia che la domanda resti aperta anche dopo l\'ultima volta.',
    'contemplazione_dei_tarocchi|Nove di Denari|dritta': 'Accogli la figura dentro lo sguardo per sette respiri ampi, come in un giardino. Guarda i nove dischi raccolti fra i tralci, frutti del tuo lavoro. Ripeti tre volte, con gioia quieta: «Abito con piacere lo spazio che ho costruito». Poi lascia lo sguardo disteso sulla figura.',
    'contemplazione_dei_tarocchi|Nove di Denari|rovesciata': 'Per cinque respiri guarda lo schermo, con una mano posata sul petto. Osserva i dischi, poi distogli lo sguardo e portalo dentro di te. Ripeti sette volte: «Valgo più di ciò che possiedo». Lascia che la frase resti con te mentre respiri ancora, adagio.',
    'contemplazione_dei_tarocchi|Nove di Spade|dritta': 'Se è buio accendi una luce e guarda la carta per sette respiri lunghi. Osserva le nove spade una sopra l\'altra, sul fondo scuro. Ripeti tre volte, piano: «Alla luce del giorno guardo i miei pensieri». Poi lascia uscire un respiro più lungo degli altri.',
    'contemplazione_dei_tarocchi|Nove di Spade|rovesciata': 'Respira quattro volte davanti allo schermo, lasciando che il petto si allenti. Guarda le spade e immagina di raccontarne una a voce, a qualcuno di caro. Ripeti cinque volte: «Ciò che dico a voce pesa meno». Poi pensa a chi potresti chiamare, anche soltanto per parlare.',
    'contemplazione_dei_tarocchi|Otto di Bastoni|dritta': 'Tieni lo schermo davanti e lascia passare cinque respiri svelti e puliti. Segui gli otto bastoni che volano paralleli nella stessa direzione. Ripeti sette volte, con ritmo: «Mi muovo con ciò che accelera». Poi rallenta il respiro fino a quietarlo, come una freccia che arriva.',
    'contemplazione_dei_tarocchi|Otto di Bastoni|rovesciata': 'Respira sette volte con gli occhi sulla carta, ciascuna più lunga della precedente. Guarda i bastoni in volo e immagina di metterli in fila, uno alla volta. Ripeti cinque volte: «Rallento quanto basta per ritrovare l\'ordine». Poi riprendi con calma ciò che stavi facendo.',
    'contemplazione_dei_tarocchi|Otto di Coppe|dritta': 'Concediti sei respiri silenziosi davanti alla carta. Guarda le otto coppe in fila e lo spazio che resta sopra di loro, come una strada che sale. Ripeti tre volte, sussurrando: «Lascio ciò che non mi nutre più». Poi resta in silenzio ancora un poco, guardando quella strada.',
    'contemplazione_dei_tarocchi|Otto di Coppe|rovesciata': 'Guarda lo schermo per cinque respiri, ascoltando dove il respiro vuole andare. Osserva la fila delle coppe e il vuoto che la interrompe: è la soglia fra restare e partire. Ripeti sette volte: «Mi ascolto con sincerità prima di scegliere». Poi lascia la soglia aperta.',
    'contemplazione_dei_tarocchi|Otto di Denari|dritta': 'Concediti sei respiri attenti davanti alla carta, uno per ogni dettaglio. Segui gli otto dischi uno dopo l\'altro, come opere finite su un banco di lavoro. Ripeti cinque volte: «Affino con cura, un dettaglio alla volta». Poi guarda le tue mani, con rispetto.',
    'contemplazione_dei_tarocchi|Otto di Denari|rovesciata': 'Respira quattro volte con gli occhi sulla carta, lasciando cadere l\'abitudine. Guarda i dischi in fila e chiediti quale hai fatto con amore. Ripeti tre volte: «Ritrovo il senso di ciò che faccio». Poi resta un respiro in più sulla domanda, prima di tornare al lavoro.',
    'contemplazione_dei_tarocchi|Otto di Spade|dritta': 'Con respiri lenti e larghi, cinque in tutto, resta davanti alla carta. Guarda le otto spade intorno alla figura e lo spazio che lasciano aperto. Ripeti sette volte: «Le corde sono più larghe di quanto credo». Poi muovi le braccia, piano, nello spazio intorno.',
    'contemplazione_dei_tarocchi|Otto di Spade|rovesciata': 'Per sei respiri guarda la carta, aprendo un poco di più il petto a ogni entrata. Cerca il varco fra le spade, quello da cui si passa. Ripeti cinque volte: «Riconosco la mia forza e faccio un passo fuori». Poi lascia lo sguardo oltre il varco.',
    'contemplazione_dei_tarocchi|Quattro di Bastoni|dritta': 'Concediti quattro respiri gioiosi davanti alla carta, con le spalle aperte. Guarda i quattro bastoni, uno per ogni lato di una casa che regge. Ripeti tre volte, con un sorriso nella voce: «Riconosco il bello che ho costruito». Lascia che la gioia resti un momento, senza correre oltre.',
    'contemplazione_dei_tarocchi|Quattro di Bastoni|rovesciata': 'Respira cinque volte guardando lo schermo, sentendo il peso posarsi sul sedile. Segui ogni bastone fino alla base, là dove tocca terra. Ripeti cinque volte: «Curo le fondamenta prima di festeggiare». Ogni volta lascia che la voce scenda un poco più in basso, verso le radici.',
    'contemplazione_dei_tarocchi|Quattro di Coppe|dritta': 'Tieni la carta davanti agli occhi per quattro respiri, poi solleva piano lo sguardo. Guarda le quattro coppe e cerca quella che prima non avevi notato. Ripeti cinque volte: «Alzo lo sguardo verso ciò che mi viene offerto». Poi lascia gli occhi aperti su ciò che hai intorno.',
    'contemplazione_dei_tarocchi|Quattro di Coppe|rovesciata': 'Respira sette volte con gli occhi sullo schermo, lasciando che lo sguardo si ridesti. Segui le coppe da sinistra a destra, come chi si accorge di qualcosa per la prima volta. Ripeti tre volte: «Seguo la curiosità che si risveglia». Poi lascia che lo sguardo si apra.',
    'contemplazione_dei_tarocchi|Quattro di Denari|dritta': 'Concediti cinque respiri solidi davanti alla carta, con le mani in grembo. Guarda i quattro dischi saldi ai quattro angoli, come le mura di una casa. Ripeti sette volte: «Proteggo ciò che ho e lascio la mano aperta». Poi apri le dita, una per una.',
    'contemplazione_dei_tarocchi|Quattro di Denari|rovesciata': 'Per quattro respiri guarda la carta, stringendo piano i pugni e poi lasciandoli andare. Osserva i dischi e immagina di allentare la presa su uno di loro. Ripeti tre volte, sottovoce: «Allento la presa e lascio scorrere». Lascia le mani aperte sulle ginocchia.',
    'contemplazione_dei_tarocchi|Quattro di Spade|dritta': 'Abbassa le palpebre a metà e guarda la carta per nove respiri lentissimi. Osserva le quattro spade posate, senza nessuna mano a stringerle. Ripeti tre volte, quasi in silenzio: «Mi fermo e lascio tornare le forze». Poi resta immobile ancora un poco.',
    'contemplazione_dei_tarocchi|Quattro di Spade|rovesciata': 'Guarda la carta per quattro respiri, ognuno un poco più vivo. Fermati sulle quattro spade e immagina la prima che si alza dal suo riposo. Ripeti cinque volte: «Torno all\'azione con passo calmo». Poi muovi piano le spalle e il collo, come al risveglio.',
    'contemplazione_dei_tarocchi|Re di Bastoni|dritta': 'Apri lo sguardo sulla figura dipinta e lascia salire cinque respiri profondi. Guarda il re che stringe il bastone e volge lo sguardo lontano, oltre il bordo. Ripeti sette volte, con voce piena di calore: «Guido con l\'esempio, con generosità». Poi resta un istante in quel silenzio.',
    'contemplazione_dei_tarocchi|Re di Bastoni|rovesciata': 'Respira sei volte davanti alla carta, lasciando parlare prima l\'uscita del fiato. Osserva il re seduto: anche chi guida si siede, a volte, per ascoltare. Ripeti cinque volte: «Ascolto prima di spingere». Lascia che la frase ammorbidisca il passo che stavi per fare.',
    'contemplazione_dei_tarocchi|Re di Coppe|dritta': 'Tieni la carta davanti agli occhi e respira cinque volte, profondo come il mare. Guarda il re che tiene la coppa con mano calma, mentre tutto intorno si muove. Ripeti sette volte: «Guido le mie emozioni con calma profonda». Poi lascia il respiro tornare al suo passo.',
    'contemplazione_dei_tarocchi|Re di Coppe|rovesciata': 'Respira sei volte davanti alla carta, lasciando che l\'onda del fiato salga e scenda. Osserva la coppa nella mano del re, tenuta senza stringere. Ripeti cinque volte, a voce chiara: «Do voce a ciò che sento». Lascia che la voce trovi il suo volume, né troppo né poco.',
    'contemplazione_dei_tarocchi|Re di Denari|dritta': 'Con lo schermo davanti agli occhi, concediti sei respiri larghi. Guarda il re che tiene il disco con mano aperta, seduto fra ciò che ha fatto crescere. Ripeti sette volte: «Condivido con misura ciò che ho costruito». Poi lascia il respiro tornare lento.',
    'contemplazione_dei_tarocchi|Re di Denari|rovesciata': 'Per sette respiri resta sulla carta, sciogliendo la mascella a ogni uscita. Guarda la mano del re sul disco e immagina che si apra. Ripeti tre volte: «Ciò che possiedo non mi possiede». Poi apri le tue mani e lasciale aperte per un respiro intero.',
    'contemplazione_dei_tarocchi|Re di Spade|dritta': 'Tieni la carta davanti agli occhi per cinque respiri pieni e misurati. Guarda il re seduto con la spada in mano, lo sguardo dritto verso di te. Ripeti sette volte: «Metto la ragione al servizio del cuore». Poi lascia riposare la mente, come una lama nel fodero.',
    'contemplazione_dei_tarocchi|Re di Spade|rovesciata': 'Respira sei volte con gli occhi sulla carta, sentendo il respiro arrivare fino al petto. Osserva il volto del re e cerca, dietro la fermezza, un segno di calore. Ripeti tre volte: «Unisco alla logica la compassione». Poi lascia la mano aperta sul cuore.',
    'contemplazione_dei_tarocchi|Regina di Bastoni|dritta': 'Solleva appena il mento e guarda la figura per sei respiri caldi. Osserva la regina sul trono col bastone fiorito in mano, presente senza sforzo. Ripeti sette volte: «Brillo così come sono, senza togliere spazio a nessuno». Poi lascia che il calore resti nel petto.',
    'contemplazione_dei_tarocchi|Regina di Bastoni|rovesciata': 'Per quattro respiri resta sulla carta, portando l\'attenzione al centro del petto. Guarda il bastone che la regina tiene vicino a sé, diritto e saldo. Ripeti tre volte: «La mia fiamma non ha rivali da temere». Respira ancora, finché senti di nuovo il tuo centro.',
    'contemplazione_dei_tarocchi|Regina di Coppe|dritta': 'Lascia che la carta ti stia davanti per sei respiri profondi e quieti. Guarda la regina che fissa la coppa chiusa fra le mani, raccolta in ascolto. Ripeti sette volte, con voce tenera: «Accolgo gli altri e accolgo anche me». Poi lascia la mano sul cuore.',
    'contemplazione_dei_tarocchi|Regina di Coppe|rovesciata': 'Per quattro respiri guarda lo schermo, sentendo dove finisci tu e dove comincia l\'aria intorno. Osserva il bordo della coppa che la regina tiene: separa e contiene. Ripeti tre volte: «Posso amare senza annegare». Poi riporta l\'attenzione al tuo respiro, soltanto al tuo.',
    'contemplazione_dei_tarocchi|Regina di Denari|dritta': 'Lascia che la carta ti stia davanti per cinque respiri caldi e pieni. Guarda la regina che tiene il disco in grembo, con tutte e due le mani. Ripeti tre volte: «Unisco il cuore e la concretezza». Poi lascia le mani in grembo come le sue, raccolte.',
    'contemplazione_dei_tarocchi|Regina di Denari|rovesciata': 'Respira quattro volte guardando la carta, ricevendo l\'aria come un dono. Osserva il disco nel grembo della regina e immagina che sia per te. Ripeti cinque volte: «Annaffio anche il mio giardino». Poi lascia che la frase ti ricordi di te, in mezzo a tutto il resto.',
    'contemplazione_dei_tarocchi|Regina di Spade|dritta': 'Lascia che la carta ti stia davanti per sei respiri limpidi e regolari. Guarda la regina con la spada diritta e la mano tesa in avanti. Ripeti tre volte, con voce netta: «Penso con chiarezza e dico ciò che è». Poi lascia lo sguardo nitido sulla carta.',
    'contemplazione_dei_tarocchi|Regina di Spade|rovesciata': 'Per quattro respiri guarda lo schermo, ammorbidendo il viso a ogni uscita. Fermati sulla lama della regina: è rivolta verso l\'alto, non contro chi la porta. Ripeti cinque volte: «Ammorbidisco il giudizio, a partire da me». Poi lascia distendere la fronte.',
    'contemplazione_dei_tarocchi|Sei di Bastoni|dritta': 'Avvicina lo schermo al viso e lascia salire cinque respiri ampi. Guarda i sei bastoni levati insieme, come in un corteo che attraversa la piazza. Ripeti tre volte: «Accolgo il riconoscimento con misura». Poi respira ancora, con la testa alta e lo sguardo morbido.',
    'contemplazione_dei_tarocchi|Sei di Bastoni|rovesciata': 'Per sette respiri resta davanti allo schermo, in silenzio. Guarda i bastoni levati e chiediti chi li regge quando nessuno applaude. Ripeti cinque volte: «Il mio valore resta anche senza applauso». Lascia che l\'ultima ripetizione sia la più piana, quasi detta a un amico.',
    'contemplazione_dei_tarocchi|Sei di Coppe|dritta': 'Con la figura davanti, lascia scorrere quattro respiri dolci. Guarda le sei coppe come un piccolo giardino di ricordi, una accanto all\'altra. Ripeti sette volte: «Lascio che la tenerezza del passato mi nutra». Poi torna con lo sguardo al presente, alla stanza dove sei.',
    'contemplazione_dei_tarocchi|Sei di Coppe|rovesciata': 'Respira sei volte con la carta davanti agli occhi, sentendo i piedi qui e adesso. Guarda le coppe e scegline una da lasciare al passato. Ripeti cinque volte, con dolcezza: «Onoro ciò che è stato e torno a oggi». Poi muovi piano le dita, come per salutare.',
    'contemplazione_dei_tarocchi|Sei di Denari|dritta': 'Tieni la carta davanti agli occhi e lascia scorrere cinque respiri uguali, uno per dare e uno per ricevere. Guarda i sei dischi e cerca il loro equilibrio, metà da una parte e metà dall\'altra. Ripeti sette volte: «Do e ricevo nella giusta misura».',
    'contemplazione_dei_tarocchi|Sei di Denari|rovesciata': 'Per sei respiri resta con gli occhi sulla carta, contando l\'entrata e l\'uscita. Guarda i dischi e chiediti da che parte pende lo scambio. Ripeti cinque volte: «Verifico che il dare torni in entrambe le direzioni». Poi lascia riposare la domanda, senza forzare la risposta.',
    'contemplazione_dei_tarocchi|Sei di Spade|dritta': 'Lascia scorrere sette respiri regolari, come remi nell\'acqua, davanti alla carta. Guarda le sei spade allineate come i remi di una barca. Ripeti cinque volte: «Vado un passo alla volta verso la riva quieta». Poi resta un respiro sull\'acqua, a guardare avanti.',
    'contemplazione_dei_tarocchi|Sei di Spade|rovesciata': 'Per quattro respiri guarda la carta, sentendo il peso di ciò che porti con te. Osserva le spade come un bagaglio che si può portare anche così, un poco pesante. Ripeti tre volte: «Parto anche col cuore un po\' indietro». Lascia che la frase ti accompagni.',
    'contemplazione_dei_tarocchi|Sette di Bastoni|dritta': 'Guarda la carta per quattro respiri decisi, con i piedi ben piantati. Osserva il bastone che sta più in alto, mentre gli altri salgono a incontrarlo. Ripeti sette volte, con voce ferma: «Tengo il punto su ciò in cui credo». Poi espira a lungo, lasciando la guardia.',
    'contemplazione_dei_tarocchi|Sette di Bastoni|rovesciata': 'Concediti sei respiri davanti alla carta, abbassando le spalle a ogni uscita. Conta i bastoni uno per uno e chiediti quali vale la pena fronteggiare. Ripeti tre volte: «Non devo difendere ogni collina». Lascia che la frase sciolga la guardia, una ripetizione dopo l\'altra.',
    'contemplazione_dei_tarocchi|Sette di Coppe|dritta': 'Guarda la carta per sette respiri, lasciando che l\'immaginazione si muova come vuole. Osserva le sette coppe una per una, come porte diverse. Ripeti tre volte: «Sogno in grande, poi scelgo con i piedi a terra». Infine posa bene i piedi sul pavimento.',
    'contemplazione_dei_tarocchi|Sette di Coppe|rovesciata': 'Per quattro respiri resta sullo schermo, lasciando che la vista si schiarisca. Fra le sette coppe fermati su una soltanto e tienila nello sguardo. Ripeti cinque volte: «Metto a fuoco ciò che desidero davvero». Lascia sfumare le altre al bordo degli occhi, senza rimpianto.',
    'contemplazione_dei_tarocchi|Sette di Denari|dritta': 'Lascia che la carta ti stia davanti per nove respiri lenti, come stagioni che passano. Osserva i sette dischi fra le foglie, come frutti ancora sul ramo. Ripeti tre volte: «Aspetto il tempo giusto del raccolto». Poi lascia andare la fretta con l\'ultimo respiro.',
    'contemplazione_dei_tarocchi|Sette di Denari|rovesciata': 'Guarda lo schermo per cinque respiri, senza chiedere niente al tempo. Fermati su un disco per volta e chiediti dove metti la tua energia. Ripeti sette volte: «Rivedo con calma dove semino». Poi lascia ricadere le mani, come chi ha finito di zappare.',
    'contemplazione_dei_tarocchi|Sette di Spade|dritta': 'Fissa la figura dipinta sullo schermo e respira sei volte, in silenzio, come chi pensa. Osserva le sette spade e la loro disposizione, come una mossa studiata. Ripeti cinque volte: «Uso l\'ingegno e resto nella verità». Poi lascia che la mente torni chiara.',
    'contemplazione_dei_tarocchi|Sette di Spade|rovesciata': 'Lascia uscire tutta l\'aria, fino in fondo, per sette respiri davanti allo schermo. Fermati su una spada e immagina di posarla alla luce. Ripeti tre volte: «Torno alla trasparenza, libero la coscienza». Poi respira con più leggerezza, sentendo il petto alleggerirsi.',
    'contemplazione_dei_tarocchi|Tre di Bastoni|dritta': 'Tieni lo schermo davanti a te e lascia andare sei respiri, lunghi come onde. Guarda i tre bastoni piantati a terra, saldi come alberi di una nave. Ripeti tre volte, con fiducia: «Ciò che ho avviato è in viaggio». Poi lascia lo sguardo all\'orizzonte della figura.',
    'contemplazione_dei_tarocchi|Tre di Bastoni|rovesciata': 'Per cinque respiri guarda la carta, lasciando che ogni uscita duri un poco di più. Fermati sul bastone che sta nel mezzo, quello che regge gli altri due. Ripeti sette volte: «Un ritardo è un tempo diverso, non un no». Poi decidi se aspettare o correggere la rotta.',
    'contemplazione_dei_tarocchi|Tre di Coppe|dritta': 'Concediti cinque respiri allegri con la carta davanti agli occhi. Guarda le tre coppe sollevate insieme, come in un brindisi fra amici. Ripeti sette volte, con voce lieta: «Festeggio con chi mi vuole bene». Poi pensa a un volto caro e sorridigli, anche da lontano.',
    'contemplazione_dei_tarocchi|Tre di Coppe|rovesciata': 'Guarda lo schermo per sei respiri, lasciando quietare il brusio intorno. Fermati su una coppa delle tre, quella che senti più vicina. Ripeti tre volte: «Scelgo i legami sinceri che mi nutrono». Lascia sfumare il resto nel respiro, come voci di una festa che si allontana.',
    'contemplazione_dei_tarocchi|Tre di Denari|dritta': 'Concentra lo sguardo sulla figura per sei respiri regolari, come colpi di scalpello. Osserva i tre dischi disposti come le pietre di un arco ben costruito. Ripeti tre volte: «Costruisco insieme agli altri, con cura». Poi pensa a chi lavora accanto a te, ogni giorno.',
    'contemplazione_dei_tarocchi|Tre di Denari|rovesciata': 'Per sette respiri resta sullo schermo, lasciando che si accordino fra loro. Fermati sullo spazio fra un disco e l\'altro: ognuno ha il suo posto. Ripeti cinque volte: «Chiarisco i compiti e l\'opera riparte». Lascia che la frase metta ordine, una ripetizione alla volta.',
    'contemplazione_dei_tarocchi|Tre di Spade|dritta': 'Anche se pesano, concediti sei respiri lenti con la carta davanti agli occhi. Guarda le tre spade dipinte, senza distogliere gli occhi. Ripeti tre volte, a voce bassa: «Lascio scorrere il dolore perché passi». Poi lascia uscire un sospiro, lungo quanto serve.',
    'contemplazione_dei_tarocchi|Tre di Spade|rovesciata': 'Per cinque respiri guarda lo schermo, lasciando l\'aria più a lungo nel petto. Segui le tre spade e cerca lo spazio fra una lama e l\'altra. Ripeti sette volte: «Il cuore torna a respirare». Poi lascia la mano sul petto un momento, a sentire il ritmo.',
    'galdr_delle_rune|Algiz|dritta': 'Alza le braccia aperte verso l\'alto, come i rami della runa: tienile così per un respiro. Canta sottovoce «Algiz, algiz, algiz» per tre giri, poi abbassa le braccia lentamente. Il pensiero va allo scudo del sacro, al riparo che c\'è e al legame con l\'alto.',
    'galdr_delle_rune|Algiz|in ombra': 'Porta le mani accanto alle orecchie senza coprirle, come per ascoltare meglio. Sussurra «Algiz, algiz, algiz» tre volte, sentendo il suono vicino a te nella stanza silenziosa. Il canto sostiene l\'attenzione verso una difesa allentata o un istinto ignorato, da riascoltare con calma, senza fretta.',
    'galdr_delle_rune|Ansuz|dritta': 'Siedi in un luogo silenzioso, porta due dita alle labbra e poi abbassale piano. Canta a voce bassa «Ansuz, ansuz, ansuz» per tre giri, ascoltando come il suono vibra nella bocca. Rivolgi il pensiero al soffio della parola, al messaggio che arriva e chiede ascolto.',
    'galdr_delle_rune|Ansuz|in ombra': 'Spegni ciò che fa rumore intorno a te e chiudi gli occhi per qualche respiro. Mormora «Ansuz, ansuz, ansuz» tre volte, sempre più piano, fino a sentirne solo il fiato. Lascia che il canto accompagni l\'attenzione a una parola fraintesa, da ascoltare meglio prima di darle peso.',
    'galdr_delle_rune|Berkano|dritta': 'Posa le mani sul ventre, una sopra l\'altra: senti il respiro sotto i palmi. Poi intona a voce bassa «Berkano, berkano, berkano» tre volte, dolcemente. Tieni il pensiero sulla betulla che genera, su ciò che di nuovo germoglia e chiede la tua cura paziente.',
    'galdr_delle_rune|Berkano|in ombra': 'Tocca la terra di un vaso o il pavimento con la punta delle dita. Sussurra «Berkano, berkano, berkano» tre volte, lentamente, come se parlassi a una radice. Il canto accompagna l\'attenzione a un germoglio che stenta e a una cura da riprendere con costanza, giorno per giorno.',
    'galdr_delle_rune|Dagaz|dritta': 'Al mattino o in un momento di luce, apri le braccia lentamente come un\'alba che si allarga. Dagli voce piano, «Dagaz, dagaz, dagaz», per tre volte, allargando il respiro a ogni ripetizione. Rivolgi il pensiero alla svolta luminosa, al nuovo giorno che risveglia.',
    'galdr_delle_rune|Ehwaz|dritta': 'Pensa a una persona di cui ti fidi e immagina di camminare al suo fianco. Pronuncia sottovoce «Ehwaz, ehwaz, ehwaz» in tre giri, accordando il respiro a un passo immaginato in due. Rivolgi il pensiero ai due cavalli, alla fiducia che porta lontano in armonia.',
    'galdr_delle_rune|Ehwaz|in ombra': 'Batti piano un ritmo regolare con la mano sul tavolo, sempre uguale. Mormora «Ehwaz, ehwaz, ehwaz» tre volte, seguendo quel battito senza anticiparlo. Con il canto guarda un\'alleanza che ha perso il passo, per ritrovare il ritmo comune prima di riprendere la corsa.',
    'galdr_delle_rune|Eihwaz|dritta': 'Appoggia la schiena a un muro o a un albero e senti che ti sostiene. Canta piano «Eihwaz, eihwaz, eihwaz» per tre giri, con la voce che sale dal petto e poi ridiscende. Tieni il pensiero sull\'asse tra i mondi, sul tasso che regge le tempeste senza spezzarsi.',
    'galdr_delle_rune|Fehu|dritta': 'Siedi vicino a una finestra aperta, con le mani sulle ginocchia e i palmi rivolti verso l\'alto. Canta a voce bassa «Fehu, fehu, fehu» per tre respiri lenti, lasciando uscire l\'aria piano. Pensa a ciò che hai e che può circolare, come un bene che scorre e porta frutto.',
    'galdr_delle_rune|Fehu|in ombra': 'Prendi in mano un piccolo oggetto a cui tieni e stringilo nel pugno. Mormora «Fehu, fehu, fehu» tre volte, poi apri lentamente le dita mentre espiri. Lascia che il canto accompagni lo sguardo su ciò che trattieni troppo, quello che chiede di tornare a muoversi.',
    'galdr_delle_rune|Gebo|dritta': 'Porta le mani davanti al petto e incrociale ai polsi, come il segno della runa. Canta piano «Gebo, gebo, gebo» per tre giri, inspirando a fondo e restituendo l\'aria lentamente. Rivolgi il pensiero al dono e al patto, all\'equilibrio fra ciò che dai e ciò che ricevi.',
    'galdr_delle_rune|Hagalaz|dritta': 'Apri una finestra e ascolta per un momento i suoni di fuori, il vento o la pioggia. Intona a voce bassa «Hagalaz, hagalaz, hagalaz», tre volte di seguito, lasciando scendere il respiro fino al ventre. Il pensiero va alla grandine che scuote: ciò che crolla lascia spazio al nuovo.',
    'galdr_delle_rune|Ingwaz|dritta': 'Chiudi le mani una dentro l\'altra, come per custodire un seme. Canta sottovoce «Ingwaz, ingwaz, ingwaz» per tre volte, a voce bassissima, quasi solo dentro di te. Tieni il pensiero sul seme in attesa, sul lavoro interiore che si compie prima di mostrarsi.',
    'galdr_delle_rune|Isa|dritta': 'Resta immobile per qualche respiro, le mani aperte sulle cosce e lo sguardo basso. Lascia uscire piano «Isa, isa, isa» tre volte, tenendo il suono lungo e uniforme, quasi una nota sola. Il pensiero va al ghiaccio che ferma: tempo di attesa e di chiarezza.',
    'galdr_delle_rune|Jera|dritta': 'Disegna con un dito un cerchio sul tavolo o sul palmo. Canta sottovoce «Jera, jera, jera» per tre volte, un giro di canto per ogni giro del dito. Rivolgi il pensiero al raccolto del tempo, a ciò che hai seminato con pazienza e matura a suo tempo.',
    'galdr_delle_rune|Kenaz|dritta': 'Accendi una candela, se puoi, oppure guarda una luce accesa nella stanza. Canta con voce bassa «Kenaz, kenaz, kenaz» per tre volte, a ogni giro tenendo lo sguardo sulla fiamma. Pensa alla torcia che rivela, alla luce che si accende dove prima era buio.',
    'galdr_delle_rune|Kenaz|in ombra': 'Siedi in penombra e copri gli occhi con il palmo delle mani per un momento. Sussurra «Kenaz, kenaz, kenaz» tre volte, poi scopri gli occhi con calma. Il canto accompagna lo sguardo su un\'idea ancora al buio: la fiamma c\'è, ha solo bisogno di tempo per prendere.',
    'galdr_delle_rune|Laguz|dritta': 'Versa dell\'acqua in un bicchiere e guardala finché la superficie torna quieta. Canta piano «Laguz, laguz, laguz» per tre giri, con una voce fluida, senza spezzare il suono. Il pensiero va all\'acqua che intuisce, alla corrente e a ciò che senti sotto la superficie.',
    'galdr_delle_rune|Laguz|in ombra': 'Agita appena un bicchiere d\'acqua e posalo sul tavolo davanti a te. Mormora «Laguz, laguz, laguz» tre volte, mentre l\'acqua si posa. Con il canto guarda un\'emozione confusa e un intuito da schiarire: lascia posare la corrente finché il fondo si vede.',
    'galdr_delle_rune|Mannaz|dritta': 'Guardati in uno specchio, oppure osserva le tue mani aperte davanti agli occhi. Sostenendo lo sguardo, ripeti a voce bassa «Mannaz, mannaz, mannaz» in tre giri lenti. Pensa all\'essere umano in mezzo agli altri, al sé e alla comunità: ti conosci meglio attraverso chi ti sta accanto.',
    'galdr_delle_rune|Mannaz|in ombra': 'Appanna con il fiato uno specchio o un vetro e osserva l\'alone che svanisce piano. Sussurra «Mannaz, mannaz, mannaz» tre volte, appannando di nuovo il vetro prima di ogni giro. Mentre canti, considera con pazienza una distanza dagli altri o un giudizio severo verso di te.',
    'galdr_delle_rune|Nauthiz|dritta': 'Strofina lentamente i palmi delle mani finché senti il calore dell\'attrito. Canta piano «Nauthiz, nauthiz, nauthiz» per tre volte, senza fretta, lasciando che ogni giro finisca prima del successivo. Pensa al bisogno che insegna, all\'attrito che accende il fuoco: qui la pazienza diventa forza.',
    'galdr_delle_rune|Nauthiz|in ombra': 'Siedi e intreccia le dita in grembo, senza stringerle troppo forte. Sussurra «Nauthiz, nauthiz, nauthiz» tre volte, allungando a poco a poco l\'espirazione a ogni ripetizione. Lascia che il canto accompagni l\'attenzione al vincolo che pesa e all\'impazienza davanti alla prova, dove la chiave resta la pazienza.',
    'galdr_delle_rune|Othala|dritta': 'Tieni in mano un oggetto che viene dalla tua famiglia o dalla tua storia. Canta piano «Othala, othala, othala» per tre volte, con una voce raccolta e grave. Pensa all\'eredità e alla casa, alle radici e al valore che viene da lontano e ti sostiene.',
    'galdr_delle_rune|Othala|in ombra': 'Tieni davanti a te un ricordo di casa e respira lentamente per qualche istante. Sussurra «Othala, othala, othala» tre volte, poi posa il ricordo con delicatezza. Il canto accompagna l\'attenzione a un legame col passato: tieni ciò che sostiene e lascia ciò che trattiene.',
    'galdr_delle_rune|Perthro|dritta': 'Unisci le mani a coppa davanti a te, come per raccogliere qualcosa. Mentre guardi dentro le mani vuote, canta piano «Perthro, perthro, perthro» per tre volte. Pensa al mistero della coppa, alla sorte ancora nascosta, a ciò che si muove sotto e non è ancora visibile.',
    'galdr_delle_rune|Perthro|in ombra': 'Rovescia le mani a coppa, con i palmi verso il basso e lasciale ricadere sulle ginocchia. Mormora «Perthro, perthro, perthro» tre volte, senza cercare un ritmo preciso. Con il canto guarda il mistero che resiste e non si svela: non forzare la sorte, lasciala maturare.',
    'galdr_delle_rune|Raidho|dritta': 'Cammina lentamente nella stanza o lungo un corridoio, un passo per ogni sillaba. Canta sottovoce «Raidho, raidho, raidho» per tre giri, accordando il passo al respiro. Il pensiero va al cammino giusto e alla cadenza che ti è propria, dentro e fuori di te.',
    'galdr_delle_rune|Raidho|in ombra': 'Fermati dove sei e senti il peso che passa da un piede all\'altro. Poi canta piano «Raidho, raidho, raidho» tre volte, più lentamente di quanto ti verrebbe spontaneo. Con il canto guarda il ritmo che si è perso a scatti, per ritrovare la tua cadenza e la strada piana.',
    'galdr_delle_rune|Sowilo|dritta': 'Volgi il viso verso la luce del giorno o verso la finestra più luminosa. Canta a voce bassa «Sowilo, sowilo, sowilo» per tre volte, con un respiro ampio che apre il petto. Rivolgi il pensiero al sole che guida, alla volontà che tiene la rotta che hai scelto.',
    'galdr_delle_rune|Thurisaz|dritta': 'Siedi con la schiena dritta e posa una mano sul petto, l\'altra sul ginocchio. Canta con voce bassa e ferma «Thurisaz, thurisaz, thurisaz» per tre volte, ogni volta su un\'unica espirazione. Tieni il pensiero sulla spina che difende: una forza aspra da dirigere con misura.',
    'galdr_delle_rune|Thurisaz|in ombra': 'Prima di cantare fermati un istante e lascia scendere le spalle. Poi sussurra «Thurisaz, thurisaz, thurisaz» tre volte, con una pausa lunga tra un giro e l\'altro. Con il canto guarda la reazione impulsiva che finisce per pungere te e lascia che la fretta si sciolga.',
    'galdr_delle_rune|Tiwaz|dritta': 'Stai in piedi con la schiena eretta e il braccio destro teso in avanti, come una lancia. Canta piano «Tiwaz, tiwaz, tiwaz» per tre giri, con voce bassa e decisa. Il pensiero va alla lancia della giustizia, al coraggio che cerca l\'esito meritato e non quello strappato.',
    'galdr_delle_rune|Tiwaz|in ombra': 'Fissa un punto lontano davanti a te e tienilo con lo sguardo per qualche respiro. Mormora «Tiwaz, tiwaz, tiwaz» tre volte, riportando gli occhi su quel punto a ogni ripetizione. Con il canto guarda un coraggio incerto, per ritrovare il tuo giusto finché la mira torna ferma.',
    'galdr_delle_rune|Uruz|dritta': 'Alzati in piedi con i piedi ben piantati a terra, alla larghezza delle spalle. Inspira dal ventre e canta piano «Uruz, uruz, uruz», sentendo la voce partire dal basso. Ripeti per tre giri, con il pensiero rivolto alla forza grezza che ti rimette in piedi.',
    'galdr_delle_rune|Uruz|in ombra': 'Resta in piedi senza muoverti e conta quattro respiri prima di cominciare. Poi canta sottovoce «Uruz, uruz, uruz» tre volte, con un ritmo lento e regolare. Il canto ti aiuta a guardare dove la tua forza si è spesa di slancio e a ritrovare la cadenza giusta.',
    'galdr_delle_rune|Wunjo|dritta': 'Siedi in un posto che ti è caro e lascia che il volto si distenda. Canta sottovoce «Wunjo, wunjo, wunjo» per tre volte, con un tono morbido e quasi cullato. Tieni il pensiero sulla gioia che corona uno sforzo, su un momento di pienezza vera da accogliere.',
    'galdr_delle_rune|Wunjo|in ombra': 'Pensa a una persona con cui il legame si è incrinato e tieni a mente il suo nome. Mormora «Wunjo, wunjo, wunjo» tre volte, lasciando tra un giro e l\'altro un respiro intero. Con il canto guarda il legame che chiede cura, perché l\'armonia possa ricomporsi.',
    'gesti_tong_shu|Bi|Amore|anno': 'Chiudere con cura è il gesto che Bi, sotto cui è nato a Capodanno il tuo anno cinese, chiede agli affetti. Raccogli adesso in una busta le lettere e i biglietti di un legame finito, chiudila bene e riponila in alto, lontano dagli occhi. Il cuore ritrova spazio.',
    'gesti_tong_shu|Bi|Amore|giorno': 'Oggi governa Bi, il giorno raccolto, poco adatto alle promesse nuove secondo l\'almanacco. In amore proteggi invece di cercare: se hai un legame, passa la sera con chi ami, telefoni spenti e porta chiusa; se sei senza legame, concediti una sera quieta, senza rincorrere nessuno.',
    'gesti_tong_shu|Bi|Amore|mese': 'Con Bi, che pone confini, partono oggi trenta giorni per difendere la quiete degli affetti. Fissa un confine: dopo una certa ora non rispondi ai messaggi che ti agitano. Rispettalo ogni sera e dedica quel tempo a chi ami o, se sei senza legame, a te.',
    'gesti_tong_shu|Bi|Amore|settimana': 'Bi, che chiude con dolcezza, dà oggi agli affetti sette giorni per sanare una questione in sospeso. Una scusa mai detta, un chiarimento promesso, con chi ami, in famiglia o con chi frequenti: dillo adesso a voce, con calma, così la settimana riparte leggera.',
    'gesti_tong_shu|Bi|Carriera|anno': 'Sotto Bi, che raccoglie le forze dentro un recinto, il tuo anno cinese è nato a Capodanno. Nel lavoro chiudi adesso un fronte secondario che disperde le energie: comunica con chiarezza che lo lasci e a chi passa ciò che resta. Le forze tornano così al compito principale.',
    'gesti_tong_shu|Bi|Carriera|giorno': 'Oggi l\'almanacco indica Bi, il giorno della chiusura, sfavorevole all\'avvio di attività. Al lavoro completa invece di aprire: chiudi le pratiche finite, archivia le cartelle, lascia la scrivania sgombra prima di andare via. Ciò che è riposto bene prepara il prossimo lavoro.',
    'gesti_tong_shu|Bi|Carriera|mese': 'Il lavoro e lo studio dei trenta giorni che cominciano oggi seguono Bi, che chiude i varchi. Metti in sicurezza ciò che hai: ogni settimana cambia una password debole, chiudi un accesso che non usi, fai una copia protetta dei file importanti. Comincia adesso dalla password più vecchia.',
    'gesti_tong_shu|Bi|Carriera|settimana': 'Bi, che tiene chiuso e che la tradizione lega anche agli argini, segna oggi la tua settimana di lavoro. Individua l\'ora del giorno in cui si disperde più tempo e mettici un argine: spegni la posta per due ore ogni mattina dei sette giorni. Comincia adesso.',
    'gesti_tong_shu|Bi|Fortuna|anno': 'Il segno di Bi, sotto cui l\'anno cinese è nato a Capodanno, è quello delle cose messe al riparo. Per le occasioni sigilla adesso ciò che hai ottenuto: metti al sicuro un documento importante, conferma per iscritto un impegno preso, salva il recapito di una persona preziosa.',
    'gesti_tong_shu|Bi|Fortuna|giorno': 'Oggi è Bi, il giorno che mette il suggello, in cui l\'almanacco sconsiglia di inseguire novità. Per le occasioni conserva ciò che hai: rileggi una proposta già accettata e porta a termine l\'ultimo passaggio che manca. Un affare concluso lascia libere le mani.',
    'gesti_tong_shu|Bi|Fortuna|mese': 'Le occasioni del mese che si apre oggi con Bi, che chiude a chiave, chiedono di tenere stretto ciò che hai. Ogni sera dei trenta giorni chiudi con calma la porta di casa e, girando la chiave, pensa a una cosa buona da conservare. Comincia stasera.',
    'gesti_tong_shu|Bi|Fortuna|settimana': 'Bi, che mette il punto finale, regge oggi una settimana per chiudere un capitolo. Per le occasioni saluta un progetto finito e ringrazia, di persona o per iscritto, chi ha fatto la strada con te. Così prepari spazio a ciò che viene dopo.',
    'gesti_tong_shu|Bi|Generale|anno': 'Sotto Bi, che serra, il tuo anno cinese ha preso vita a Capodanno. Il suo gesto è chiudere bene: manda adesso il messaggio che conclude una faccenda trascinata da tempo, con parole chiare e senza rancore. Ciò che è chiuso con garbo smette di chiedere attenzione.',
    'gesti_tong_shu|Bi|Generale|giorno': 'Oggi è il giorno di Bi, l\'ufficiale che chiude: l\'almanacco lo sconsiglia per aprire o partire e lo lascia al sigillare. Chiudi bene ciò che è rimasto aperto in casa, barattoli, cassetti, ante, la finestra che sbatte. Poi riponi ogni oggetto che hai usato.',
    'gesti_tong_shu|Bi|Generale|mese': 'Bi, che conclude la serie dei dodici ed è buono per tappare le falle, governa il mese che parte oggi. Ogni settimana ripara una piccola perdita di casa: il rubinetto che gocciola, lo spiffero sotto la porta, la guarnizione consumata. Comincia adesso da quella che senti di più.',
    'gesti_tong_shu|Bi|Generale|settimana': 'Bi, che racchiude, regge oggi la tua settimana: la tradizione dice che solo chi sa chiudere torna a stabilire. Fai la lista delle questioni aperte e chiudine una adesso, con un gesto definitivo. Le altre trovano posto nei sette giorni, una alla volta.',
    'gesti_tong_shu|Cheng|Amore|anno': 'Cheng, l\'ufficiale che corona le cose ed è amico delle unioni, ha segnato a Capodanno il tuo anno cinese. Celebra adesso un legame che dura: una ricorrenza lasciata passare con chi ami o, se sei senza legame, un\'amicizia di lunga data, con un brindisi o un biglietto.',
    'gesti_tong_shu|Cheng|Amore|giorno': 'Oggi governa Cheng, il giorno del traguardo, che la tradizione lega anche alle unioni. Negli affetti realizza adesso la sorpresa progettata e mai fatta, piccola o grande, per chi ami o per chi desideri avvicinare. Non aspettare un\'occasione speciale: l\'occasione è oggi.',
    'gesti_tong_shu|Cheng|Amore|mese': 'Gli affetti dei trenta giorni che cominciano oggi seguono Cheng, che porta a frutto ed è propizio alle unioni. Scegli un chiarimento rimasto a metà con chi ami o, se sei senza legame, un incontro che rimandi da tempo: fissane adesso la data e preparane le prime parole.',
    'gesti_tong_shu|Cheng|Amore|settimana': 'Cheng, che chiude il cerchio, segna oggi la settimana degli affetti. Se vivi una relazione, realizzate nei sette giorni un progetto di cui parlate da tempo, anche minimo: una gita, una cena in un posto nuovo; se sei senza legame, porta a termine un passo che rimandi.',
    'gesti_tong_shu|Cheng|Carriera|anno': 'Nel lavoro e nello studio conta il segno di Cheng, l\'ufficiale delle opere finite: sotto di lui, a Capodanno, ha preso vita il tuo anno cinese. Riprendi adesso un corso o un percorso di studio lasciato a metà e completa la lezione successiva.',
    'gesti_tong_shu|Cheng|Carriera|giorno': 'Oggi l\'almanacco segna Cheng, il giorno buono per le consegne. Al lavoro porta a termine il compito più vicino alla fine e consegnalo prima di sera, anche se non è perfetto. Vedere una cosa completata dà slancio a quelle che seguono.',
    'gesti_tong_shu|Cheng|Carriera|mese': 'Cheng, che dopo la vigilanza porta a compimento, governa il primo dei tuoi trenta giorni di lavoro. Fai l\'elenco dei compiti vicini alla fine e assegna a ciascuno una data di consegna dentro il mese. Chiudi adesso il primo e cancellalo con un tratto.',
    'gesti_tong_shu|Cheng|Carriera|settimana': 'Sotto Cheng, che perfeziona, la settimana di lavoro chiede arrivi più che partenze. Scegli il progetto più maturo e coinvolgi adesso chi deve approvarlo: fissa con quella persona un incontro entro i sette giorni per l\'ultimo via libera. Così il compimento non resta in sospeso.',
    'gesti_tong_shu|Cheng|Fortuna|anno': 'Nato a Capodanno sotto Cheng, che non lascia le cose a metà, il tuo anno cinese chiede di portare fino in fondo le occasioni: la candidatura rimasta in bozza, la domanda mai inviata, la richiesta tenuta nel cassetto. Inviala adesso, così com\'è.',
    'gesti_tong_shu|Cheng|Fortuna|giorno': 'Oggi è Cheng, il giorno che compie e che l\'almanacco dà buono anche per mettersi in viaggio. Per le occasioni muoviti: vai di persona dove finora hai solo scritto, a un incontro, da qualcuno che stimi. Le cose si compiono spesso quando ci si mette in strada.',
    'gesti_tong_shu|Cheng|Fortuna|mese': 'Il mese che parte oggi segue Cheng, che dà compimento e accompagna, secondo la tradizione, anche chi parte. Per le occasioni organizza nei trenta giorni una gita di un giorno verso un luogo che ti chiama da tempo: scegli adesso la meta e il mezzo.',
    'gesti_tong_shu|Cheng|Fortuna|settimana': 'Cheng, che fa arrivare in fondo, regge oggi una settimana in cui le occasioni chiedono di essere completate. Riprendi una possibilità lasciata cadere a metà strada e fai adesso il passaggio che mancava: una risposta, una richiesta, un documento allegato. Ciò che manca è spesso poco.',
    'gesti_tong_shu|Cheng|Generale|anno': 'Il segno che Cheng ha posto a Capodanno sul tuo anno cinese è quello delle cose finite. Il gesto vale in qualunque punto dell\'anno: riprendi adesso una lettera scritta a metà e mai spedita, poi finiscila, firmala e spediscila, anche se è passato del tempo.',
    'gesti_tong_shu|Cheng|Generale|giorno': 'Oggi è il giorno di Cheng, l\'ufficiale del compimento: l\'almanacco lo considera fra i più propizi. Prendi il libro lasciato a metà e leggilo fino all\'ultima pagina, oppure fino al capitolo che chiude una parte. Rimetterlo sullo scaffale, finito, è il gesto di questo giorno.',
    'gesti_tong_shu|Cheng|Generale|mese': 'Sotto Cheng, che conclude, si apre oggi il tuo mese. Ogni settimana dei trenta giorni chiudi una piccola pratica di casa rimasta in sospeso: un documento da rinnovare, una lampadina da cambiare, un orlo da cucire. Comincia adesso dalla più semplice, prima di sera.',
    'gesti_tong_shu|Cheng|Generale|settimana': 'Cheng, che fa giungere al termine, regge oggi il primo dei sette giorni. Riprendi un lavoro manuale rimasto a metà, un maglione, un disegno, un mobile da verniciare: completalo entro il settimo giorno, un poco ogni sera. Comincia adesso con il primo tratto.',
    'gesti_tong_shu|Chu|Amore|anno': 'Il cuore, in quest\'anno cinese nato a Capodanno sotto Chu, chiede spazio libero più che cose nuove: Chu è l\'ufficiale che svuota per preparare. Scegli adesso una pretesa che pesa sugli affetti, verso chi ami o verso chi cerchi: dilla ad alta voce un\'ultima volta per lasciarla andare.',
    'gesti_tong_shu|Chu|Amore|giorno': 'Oggi l\'almanacco indica Chu, il giorno che fa pulizia. Negli affetti lascia andare un piccolo rancore che porti da tempo, verso chi ami o chi hai amato, oppure in famiglia: scrivilo su un foglio, rileggilo una volta e poi strappalo. Resta più spazio per ciò che conta.',
    'gesti_tong_shu|Chu|Amore|mese': 'Con Chu, che fa largo, cominciano oggi trenta giorni per alleggerire il cuore. Ogni settimana rileggi una conversazione che ancora pesa, di un amore finito o di una lite recente: cancella i messaggi che non vuoi più portare con te. Comincia adesso dalla più vecchia.',
    'gesti_tong_shu|Chu|Amore|settimana': 'La settimana degli affetti che oggi Chu inaugura, l\'ufficiale che sfronda, chiede di abbandonare le abitudini che allontanano. Se hai un legame, lascia fuori dalla tavola i telefoni per sette giorni; se sei senza legame, smetti di controllare il profilo di chi ti ha ferito. Comincia stasera.',
    'gesti_tong_shu|Chu|Carriera|anno': 'Sotto Chu, che elimina l\'inutile, è nato a Capodanno il tuo anno cinese. Nel lavoro e nello studio il suo gesto vale in qualsiasi giorno: apri adesso la memoria del computer, cancella le cartelle doppie e i file superati, poi svuota il cestino digitale.',
    'gesti_tong_shu|Chu|Carriera|giorno': 'Oggi governa Chu, il giorno che rimuove. Al lavoro libera il piano della scrivania: butta le carte inutili, i fogli doppi, le penne che non scrivono più. Tieni a portata di mano soltanto ciò che serve al compito di oggi. Uno spazio vuoto aiuta a vedere le priorità.',
    'gesti_tong_shu|Chu|Carriera|mese': 'Il mese di lavoro e di studio che si apre oggi porta il segno di Chu, che sfoltisce. Ogni settimana togli dal tuo metodo un passaggio inutile: una copia di troppo, un controllo doppio, una riunione che non decide nulla. Adesso scegli il primo e annota come farne a meno.',
    'gesti_tong_shu|Chu|Carriera|settimana': 'Con Chu, l\'ufficiale che leva ciò che è superato, la settimana di lavoro comincia togliendo invece di aggiungere. Scegli un impegno che non ha più senso portare avanti e chiudilo adesso con garbo, per iscritto, a chi di dovere. Così i sette giorni respirano.',
    'gesti_tong_shu|Chu|Fortuna|anno': 'A Capodanno l\'anno cinese è nato sotto Chu, l\'ufficiale che fa posto. Per le occasioni il gesto vale in qualunque giorno: libera adesso un angolo della casa da ciò che non usi, puliscilo e lascialo vuoto. Quel posto libero lascia spazio a ciò che deve venire.',
    'gesti_tong_shu|Chu|Fortuna|giorno': 'Oggi è Chu, il giorno del ricambio. Per le occasioni spalanca le finestre di tutte le stanze per qualche minuto e lascia uscire l\'aria ferma. Intanto togli dal davanzale e dal tavolo ciò che si è accumulato senza motivo. Un luogo arioso accoglie meglio.',
    'gesti_tong_shu|Chu|Fortuna|mese': 'Le occasioni dei trenta giorni che partono oggi con Chu, l\'ufficiale che porta via, chiedono posto. Metti accanto alla porta una borsa vuota e ogni sera aggiungi un oggetto che non usi, da regalare. Quando è piena, consegnala a chi ne ha bisogno. Comincia adesso con il primo.',
    'gesti_tong_shu|Chu|Fortuna|settimana': 'In questa settimana di Chu, che scarta ciò che non serve, le occasioni chiedono tempo libero prima ancora di cose nuove. Togli dall\'agenda dei sette giorni un impegno che non ti somiglia più e lascia vuota quell\'ora: usala per una passeggiata senza meta.',
    'gesti_tong_shu|Chu|Generale|anno': 'Quest\'anno cinese ha visto la luce a Capodanno sotto Chu, che spazza via il superfluo. Il suo gesto vale in ogni momento: rileggi adesso i propositi che ti porti dietro da tempo e depenna con un tratto deciso quello che non ti appartiene più. Non sostituirlo subito.',
    'gesti_tong_shu|Chu|Generale|giorno': 'Oggi è il giorno di Chu, l\'ufficiale che toglie il vecchio per fare spazio al nuovo. Apri la dispensa o il frigorifero e porta via adesso ciò che è scaduto o dimenticato da tempo. Lascia sul ripiano soltanto quello che usi davvero.',
    'gesti_tong_shu|Chu|Generale|mese': 'Trenta giorni sotto il segno di Chu, che libera, partono oggi. Ogni settimana scegli un\'abitudine che consuma tempo senza restituire nulla, come scorrere notizie a vuoto: sospendila per sette giorni. Comincia adesso dalla più ingombrante e osserva che cosa entra nello spazio liberato.',
    'gesti_tong_shu|Chu|Generale|settimana': 'Chu, che sgombra, regge la settimana che nasce oggi. Passa un panno umido sulla soglia di casa e sul pavimento dell\'ingresso, poi togli le scarpe e le borse accumulate lì vicino. Nei sette giorni che seguono tieni libero quel passaggio: è la porta da cui entra il nuovo.',
    'gesti_tong_shu|Ding|Amore|anno': 'Il segno di Ding, che dà radici, accompagna gli affetti del tuo anno cinese, nato sotto di lui a Capodanno. Metti adesso accanto al letto un oggetto che ricordi un impegno preso, verso chi ami o, se sei senza legame, verso la tua vita affettiva. Guardalo ogni sera.',
    'gesti_tong_shu|Ding|Amore|giorno': 'Oggi governa Ding, il giorno che rende saldo ciò che è incerto. Negli affetti trasforma un\'intenzione in un orario: fissa per stasera una telefonata a chi ami o, se sei senza legame, a una persona che vorresti conoscere meglio. Poi mantienila, qualunque cosa accada.',
    'gesti_tong_shu|Ding|Amore|mese': 'Ding, che assesta, segna l\'avvio di trenta giorni in cui l\'almanacco sconsiglia le liti. Negli affetti fissa una regola semplice, con chi ami o con chi frequenti: quando il tono sale, una pausa di dieci minuti prima di rispondere. Stabiliscila adesso e rispettala ogni volta.',
    'gesti_tong_shu|Ding|Amore|settimana': 'Con Ding, l\'ufficiale che stabilizza, oggi parte una settimana di promesse piccole e mantenibili. Concorda con chi ami un saluto fisso alla stessa ora ogni sera dei sette giorni oppure, se sei senza legame, promettiti un\'uscita in cui incontrare persone nuove. Decidilo adesso.',
    'gesti_tong_shu|Ding|Carriera|anno': 'Per il lavoro e lo studio, l\'anno cinese nato sotto Ding a Capodanno chiede scelte ferme. Prendi adesso la decisione che lasci in sospeso da troppo, fra due strade, due metodi, due offerte: scegline una e comunicala a chi deve saperlo. Ciò che è deciso smette di pesare.',
    'gesti_tong_shu|Ding|Carriera|giorno': 'Oggi l\'almanacco segna Ding, il giorno fermo, adatto a chi deve pianificare. Al lavoro prendi un progetto confuso e scrivine la scaletta: le fasi, chi fa cosa, quando finisce ciascun passaggio. Un piano nero su bianco libera la mente per il resto della giornata.',
    'gesti_tong_shu|Ding|Carriera|mese': 'Ding, ufficiale del calcolo e della fermezza, governa il primo dei tuoi trenta giorni di lavoro e di studio. Misura per una settimana quanto tempo ti chiede davvero ogni compito ricorrente e annotalo: poi fissa le stime per il resto del mese. Comincia adesso dal primo compito.',
    'gesti_tong_shu|Ding|Carriera|settimana': 'In questa settimana di lavoro, aperta oggi da Ding, l\'ufficiale che mette paletti, stabilisci subito le regole: orari, priorità, momenti senza interruzioni. Scrivile in un posto visibile e condividile con chi lavora accanto a te, così i sette giorni partono con chiarezza.',
    'gesti_tong_shu|Ding|Fortuna|anno': 'Ding, che mette ogni cosa al suo posto, ha fissato a Capodanno il segno del tuo anno cinese. Per le occasioni scegli adesso un luogo del quartiere dove tornare con regolarità, un mercato, un caffè, finché le persone imparano a riconoscerti. Le occasioni passano da chi si trova sempre lì.',
    'gesti_tong_shu|Ding|Fortuna|giorno': 'Oggi è Ding, il giorno che dà contorni netti. Per le occasioni prepara ciò che serve a coglierle: un curriculum aggiornato, i recapiti giusti, una presentazione di poche righe. Raccogli tutto adesso in un\'unica cartella, così niente resta incerto o disperso.',
    'gesti_tong_shu|Ding|Fortuna|mese': 'Le occasioni del mese che comincia oggi con Ding, che dà ancoraggio, chiedono appuntamenti fissati, non attese. Scegli tre persone che possono aprirti una porta e fissa con ciascuna un incontro nei trenta giorni. Scrivi adesso la prima data, con l\'ora e il luogo.',
    'gesti_tong_shu|Ding|Fortuna|settimana': 'Ding, l\'ufficiale dei progetti ben fondati, regge oggi una settimana in cui le occasioni si riconoscono meglio con una mappa. Apri sul telefono una nota con ciò che speri e, sotto, i nomi di tre persone che potrebbero aiutarti. Rileggila ogni mattina dei sette giorni.',
    'gesti_tong_shu|Ding|Generale|anno': 'A Capodanno Ding, l\'ufficiale che ferma ciò che oscilla, ha dato il suo segno al tuo anno cinese. Il gesto vale in qualsiasi momento: fissa adesso ciò che traballa in casa, una mensola, una sedia, un\'anta; stringi le viti. Ciò che è saldo regge meglio ogni giorno.',
    'gesti_tong_shu|Ding|Generale|giorno': 'Oggi è il giorno di Ding, l\'ufficiale che fissa: l\'almanacco antico lo indica per i piani e per i calcoli. Siediti dieci minuti con un foglio e disegna il piano della giornata, ora per ora. Scegli una priorità sola e scrivila in alto, ben chiara.',
    'gesti_tong_shu|Ding|Generale|mese': 'Sotto Ding, che consolida, comincia oggi il tuo mese. Appendi al muro un calendario dei trenta giorni e segna in ciascuna settimana una sola cosa da rendere salda, con un colore diverso. Fallo adesso, poi guardalo ogni mattina prima di uscire.',
    'gesti_tong_shu|Ding|Generale|settimana': 'Ding, che rende stabili le cose, governa oggi l\'avvio della settimana. Fissa un orario per svegliarti e uno per coricarti, uguali per tutti i sette giorni: regola adesso la sveglia. Un ritmo fermo dà forza a ogni altro proposito. Rimanda le partenze che non servono.',
    'gesti_tong_shu|Jian|Amore|anno': 'Negli affetti conta il segno di Jian, l\'ufficiale che dà stabilità: sotto di lui è nato a Capodanno il tuo anno cinese. Scegli adesso un luogo dove tornare con costanza, insieme a chi ami o, se sei senza legame, per conoscere persone nuove: un circolo, un coro, un\'associazione di quartiere.',
    'gesti_tong_shu|Jian|Amore|giorno': 'Oggi l\'almanacco segna Jian, il giorno che dà fondamento agli affetti. Tocca a te il primo passo: manda il messaggio che aspetti di ricevere, a chi ami o, se sei senza legame, a una persona che desideri conoscere meglio. Bastano poche parole, semplici e vere.',
    'gesti_tong_shu|Jian|Amore|mese': 'Per trenta giorni, da oggi, gli affetti seguono Jian, l\'ufficiale che edifica. Costruisci un piccolo rito di tavola: una cena preparata insieme ogni settimana con chi ami oppure, se sei senza legame, un pranzo fisso con persone care e qualcuno di nuovo. Fissa adesso la prima data.',
    'gesti_tong_shu|Jian|Amore|settimana': 'Con Jian, che mette le basi, si apre oggi una settimana adatta a fondare un\'abitudine degli affetti. Se hai un legame, proponi a chi ami dieci minuti di dialogo ogni sera, senza telefoni; se sei senza legame, scegli una sera fissa per uscire con gli amici e rispettala.',
    'gesti_tong_shu|Jian|Carriera|anno': 'Il lavoro di quest\'anno cinese segue Jian, che guida la serie dei dodici: l\'anno è nato sotto di lui a Capodanno. Prepara adesso il terreno a un compito che nessuno ha ancora avviato: raccogli in una cartella ciò che serve, dalle un nome e mettila in cima alla scrivania.',
    'gesti_tong_shu|Jian|Carriera|giorno': 'Oggi governa Jian, che istituisce: la tradizione lo dà buono anche a chi assume un incarico. Al lavoro apri il compito che continui a spostare e completa soltanto il primo passaggio. Prima di chiudere annota il punto preciso da cui riprendere.',
    'gesti_tong_shu|Jian|Carriera|mese': 'Al lavoro e nello studio questi trenta giorni partono da Jian, che avvia le cose ed è propizio, dice l\'almanacco, anche a chi entra in una scuola. Iscriviti adesso al corso che rimandi, oppure scegli un manuale della tua materia e fissa un\'ora alla settimana per studiarlo.',
    'gesti_tong_shu|Jian|Carriera|settimana': 'Sotto Jian, che fonda, comincia oggi la tua settimana di lavoro e di studio. Proponi a chi coordina il tuo lavoro un compito nuovo da prendere in carico e parlane di persona entro questi sette giorni. Prepara adesso la frase con cui chiederlo, breve e chiara.',
    'gesti_tong_shu|Jian|Fortuna|anno': 'Le occasioni del tuo anno cinese, nato a Capodanno sotto Jian, passano anche dal mettersi in cammino, che l\'almanacco affianca allo stabilire. Rendi adesso pronti gli strumenti dell\'uscita: riordina la borsa, sistema le scarpe, gonfia le ruote della bicicletta. Ciò che è pronto invita a partire.',
    'gesti_tong_shu|Jian|Fortuna|giorno': 'Oggi è Jian, il giorno che rende solido ciò che nasce e che l\'almanacco dà buono anche per mettersi in cammino. Per le occasioni prendi una strada mai percorsa per andare dove devi: guarda le vetrine, le insegne, i volti. Un percorso nuovo mostra ciò che l\'abitudine nasconde.',
    'gesti_tong_shu|Jian|Fortuna|mese': 'Per le occasioni dei trenta giorni che partono oggi con Jian, che mette in piedi le cose ed è buono anche per chi parte, scegli una meta vicina mai visitata: un borgo, un museo, un sentiero. Decidi adesso con chi andarci e come arrivarci.',
    'gesti_tong_shu|Jian|Fortuna|settimana': 'Nei sette giorni che Jian, l\'ufficiale che costruisce, governa da oggi, le occasioni chiedono un primo contatto. Telefona a una persona che fa già ciò che vorresti fare tu e chiedile come ha mosso i primi passi. Ascolta con attenzione, prendi nota, ringrazia.',
    'gesti_tong_shu|Jian|Generale|anno': 'Sotto Jian, che dà forma stabile alle cose, il tuo anno cinese è venuto al mondo a Capodanno. Il suo gesto vale in qualunque giorno: prendi una decisione sospesa da tempo e rendila concreta con un atto preciso, una prenotazione, una domanda inviata, un sì detto a voce.',
    'gesti_tong_shu|Jian|Generale|giorno': 'Oggi è il giorno di Jian, l\'ufficiale che stabilisce. Scegli una cosa rimandata da tempo e compi adesso il primo passo concreto: scrivi la prima riga, apri il quaderno nuovo, metti la data in cima alla pagina. Il resto può aspettare: conta che la cosa sia avviata.',
    'gesti_tong_shu|Jian|Generale|mese': 'Jian, primo dei dodici ufficiali, governa il giorno da cui partono questi trenta giorni. Scegli un progetto che vuoi vedere in piedi entro il mese e segna nell\'agenda quattro date, una per settimana, ciascuna col passo da compiere. Compi il primo subito, prima di sera.',
    'gesti_tong_shu|Jian|Generale|settimana': 'La settimana che nasce oggi appartiene a Jian, che pone le fondamenta. Metti sul tavolo un oggetto che rappresenti ciò che vuoi far crescere nei sette giorni (una chiave, un sasso, una matita) e lascialo in vista. Ogni volta che lo incontri, fai un passo in quella direzione.',
    'gesti_tong_shu|Kai|Amore|anno': 'Sotto Kai, che accoglie e festeggia, il tuo anno cinese è venuto al mondo a Capodanno. Organizza adesso un piccolo brindisi per chi ami o, se sei senza legame, per gli amici più cari: invita anche una persona nuova al tavolo. Una tavola allargata scalda gli affetti.',
    'gesti_tong_shu|Kai|Amore|giorno': 'Oggi governa Kai, il giorno che schiude, buono anche per le unioni secondo l\'almanacco antico. Negli affetti pronuncia una frase sincera che di solito tieni per te: dilla a chi ami o a chi desideri conoscere, guardando la persona negli occhi.',
    'gesti_tong_shu|Kai|Amore|mese': 'Sotto Kai, l\'ufficiale dei varchi, cominciano oggi trenta giorni aperti agli incontri del cuore. Ogni settimana rivolgi una domanda nuova a chi ami oppure, se sei senza legame, a chi frequenti: un sogno, un ricordo, una paura. Ascolta la risposta. Ponila adesso per la prima volta.',
    'gesti_tong_shu|Kai|Amore|settimana': 'Allargare il cerchio degli affetti è il gesto della settimana che Kai governa da oggi. Se hai un legame, proponi a chi ami un\'attività nuova da provare insieme nei sette giorni, un ballo, un laboratorio; se sei senza legame, iscriviti a un\'attività di gruppo dove conoscere persone.',
    'gesti_tong_shu|Kai|Carriera|anno': 'Nel lavoro conta il soffio di Kai, l\'ufficiale che dischiude: il tuo anno cinese è nato sotto di lui a Capodanno. Proponi adesso in riunione, o per iscritto a chi decide, l\'idea che tieni nel cassetto da troppo tempo. Un\'idea detta circola.',
    'gesti_tong_shu|Kai|Carriera|giorno': 'Oggi l\'almanacco segna Kai, il giorno propizio ad aprire un\'attività. Al lavoro apri un canale nuovo: scrivi a una persona che stimi e che non conosci ancora, con due righe sincere su ciò che apprezzi del suo lavoro. Un\'apertura piccola basta.',
    'gesti_tong_shu|Kai|Carriera|mese': 'Kai, che spalanca le porte alle attività nuove, segna l\'avvio del tuo mese di lavoro e di studio. Ogni settimana partecipa a un incontro del tuo settore, una conferenza, un gruppo di studio, una serata aperta: presentati ad almeno una persona. Scegli adesso il primo appuntamento.',
    'gesti_tong_shu|Kai|Carriera|settimana': 'Sotto Kai, che inaugura, la settimana di lavoro e di studio comincia con una presentazione. Racconta a chi lavora con te il progetto che vuoi far nascere e chiedi chi vuole partecipare nei sette giorni. Fallo adesso, finché lo slancio è fresco.',
    'gesti_tong_shu|Kai|Fortuna|anno': 'Kai, sotto cui l\'anno cinese è nato a Capodanno, porta il segno dell\'uscio spalancato. Per le occasioni il gesto è uscire incontro agli altri: entra adesso in un luogo del quartiere dove non hai mai messo piede, una bottega, una sala, un cortile: presentati a chi trovi.',
    'gesti_tong_shu|Kai|Fortuna|giorno': 'Oggi è Kai, fra i giorni più graditi alla tradizione, quello che apre. Per le occasioni saluta per primo qualcuno che vedi spesso senza mai salutarlo: il vicino, il negoziante, chi fa la tua stessa strada. Un saluto può aprire una porta.',
    'gesti_tong_shu|Kai|Fortuna|mese': 'Esci e incontra persone: il mese che comincia oggi è di Kai, che l\'almanacco conta fra i più fausti. Per le occasioni accetta ogni settimana almeno un invito che di solito declini. Comincia adesso rispondendo sì al primo che hai davanti.',
    'gesti_tong_shu|Kai|Fortuna|settimana': 'Kai, che fa circolare l\'aria nuova, segna oggi una settimana in cui le occasioni passano dagli incontri. Scegli un gruppo, un coro o un\'associazione da frequentare nei sette giorni e fai adesso la prima telefonata per entrarci. Entrare in un cerchio nuovo è il gesto.',
    'gesti_tong_shu|Kai|Generale|anno': 'Kai, l\'ufficiale dell\'apertura, ha visto nascere a Capodanno il tuo anno cinese. Il gesto vale oggi come in ogni altro giorno: riprendi adesso un\'amicizia interrotta senza motivo, con una telefonata o una visita. Ciò che era chiuso torna a respirare.',
    'gesti_tong_shu|Kai|Generale|giorno': 'Oggi è il giorno di Kai, l\'ufficiale che apre: l\'almanacco antico lo chiama il soffio vitale che comincia. Spalanca porte e finestre per qualche minuto e lascia entrare luce e aria in ogni stanza. Respira a fondo davanti alla finestra più ampia.',
    'gesti_tong_shu|Kai|Generale|mese': 'Kai, che mette in moto, segna il mese che parte oggi. Nei trenta giorni prova ogni settimana una cosa mai fatta: un piatto nuovo, un genere di musica sconosciuto, uno sport, un museo. Scegli adesso la prima e falla oggi stesso, anche se è piccola.',
    'gesti_tong_shu|Kai|Generale|settimana': 'Kai, l\'ufficiale delle porte aperte, buono anche per i conviti secondo la tradizione, regge oggi la tua settimana. Invita a pranzo i vicini o gli amici nei sette giorni, con un piatto semplice. Scegli adesso la data e bussa alla prima porta.',
    'gesti_tong_shu|Man|Amore|anno': 'Nato a Capodanno sotto Man, il pieno, propizio ai voti per tradizione, il tuo anno cinese affida gli affetti alla famiglia. Prepara adesso un piccolo dono fatto a mano per un parente o per chi ami, o per un\'amicizia se sei senza legame: consegnalo con un augurio.',
    'gesti_tong_shu|Man|Amore|giorno': 'Oggi l\'almanacco segna Man, il giorno pieno, buono anche per stringere i legami di famiglia. Telefona a un parente che non senti da tempo e ascolta le sue notizie senza fretta. Se hai un legame, fallo insieme a chi ami; se sei senza legame, chiama anche un\'amicizia cara.',
    'gesti_tong_shu|Man|Amore|mese': 'Gli affetti seguono Man, l\'ufficiale che riempie, per trenta giorni da oggi. Scegli una persona cara, chi ami o chi ti piacerebbe conoscere meglio: dedicale ogni settimana un gesto di cura, cominciando adesso con un messaggio affettuoso. La cura ripetuta riempie un legame più di un grande gesto.',
    'gesti_tong_shu|Man|Amore|settimana': 'Sotto Man, che la tradizione lega alle famiglie unite, la settimana degli affetti chiede una tavola condivisa. Nei sette giorni invita a casa le persone care, la famiglia o gli amici più stretti, per un caffè e qualcosa di dolce. Manda adesso il primo invito.',
    'gesti_tong_shu|Man|Carriera|anno': 'Nel lavoro di quest\'anno cinese, venuto al mondo sotto Man a Capodanno, vale l\'avvertenza dell\'almanacco: quel che si colma oltre misura si versa. Prima di accettare un nuovo incarico, lascia adesso un impegno a chi può prenderlo con più respiro, spiegando con chiarezza come si svolge.',
    'gesti_tong_shu|Man|Carriera|giorno': 'Oggi governa Man, il giorno che chiede misura a ciò che è carico. Al lavoro ringrazia di persona chi ti ha dato una mano in questi giorni, con parole precise su ciò che ha fatto. Un grazie detto bene riempie la giornata di chi lo riceve.',
    'gesti_tong_shu|Man|Carriera|mese': 'I tuoi trenta giorni di lavoro e di studio partono da Man, il giorno che porta le cose al colmo. Raccogli in una cartella i lavori riusciti dell\'ultimo tratto e mostrali a una persona di fiducia: chiedile che cosa vede di buono. Fallo adesso, prima di aggiungere altro.',
    'gesti_tong_shu|Man|Carriera|settimana': 'Con Man, che trabocca se lo si carica troppo, si apre una settimana in cui al lavoro conviene non aggiungere impegni. Per sette giorni, a ogni nuova richiesta, rispondi che ci pensi e decidi soltanto a mente fredda, dopo aver guardato quanto porti già.',
    'gesti_tong_shu|Man|Fortuna|anno': 'Le occasioni di quest\'anno cinese, sorto a Capodanno sotto Man, passano dalle offerte che l\'almanacco lega al pieno. Riempi adesso una ciotola di frutta e mettila al centro della tavola come augurio: offrine a chiunque passi da casa, finché dura.',
    'gesti_tong_shu|Man|Fortuna|giorno': 'Oggi è Man, il giorno della misura colma, legato dalla tradizione ai desideri espressi. Per le occasioni dai forma a ciò che speri: dillo in una frase chiara, a voce alta, davanti alla finestra aperta. Un desiderio detto con precisione è più facile da riconoscere quando passa.',
    'gesti_tong_shu|Man|Fortuna|mese': 'Nel mese che parte oggi con Man, ufficiale del colmo e dei voti, le occasioni chiedono gratitudine. Metti in casa un fiore fresco e rinnovalo ogni settimana dei trenta giorni: ogni volta che lo sostituisci, ringrazia per un\'occasione ricevuta. Comincia adesso con il primo fiore.',
    'gesti_tong_shu|Man|Fortuna|settimana': 'Una settimana sotto Man, il recipiente colmo, comincia oggi: le occasioni amano chi sa ricevere. Prepara un angolo della casa con un oggetto che per te significa gioia, una conchiglia, un disegno, un ricordo di viaggio. Guardalo ogni mattina come un augurio.',
    'gesti_tong_shu|Man|Generale|anno': 'Man, l\'ufficiale della pienezza, ha accolto a Capodanno la nascita del tuo anno cinese. Il gesto vale adesso come in ogni altro giorno: riempi un bicchiere d\'acqua fino all\'orlo, guardalo un istante e bevine un sorso. Ciò che è pieno chiede misura, dice la tradizione.',
    'gesti_tong_shu|Man|Generale|giorno': 'Oggi è il giorno di Man, l\'ufficiale del pieno, che l\'almanacco dedica anche alle offerte e ai desideri espressi. Accendi una candela sul tavolo e pronuncia a voce bassa un augurio per chi ti è caro. Poi ringrazia per una cosa che oggi c\'è già.',
    'gesti_tong_shu|Man|Generale|mese': 'Il mese che comincia oggi appartiene a Man: l\'almanacco antico avverte che il troppo pieno trabocca. Per i trenta giorni scegli una misura semplice: una sera libera alla settimana, senza impegni né schermi. Fissala adesso sul calendario e difendila da ogni richiesta.',
    'gesti_tong_shu|Man|Generale|settimana': 'Man, il giorno colmo, governa oggi il primo dei sette giorni: la tradizione lo lega ai voti e ai ringraziamenti. Scrivi su un foglio tre doni ricevuti di recente e un desiderio solo. Piegalo, tienilo in tasca e rileggilo quando la settimana si chiude.',
    'gesti_tong_shu|Ping|Amore|anno': 'Ping, che pareggia, segna gli affetti del tuo anno cinese, nato sotto di lui a Capodanno. Correggi adesso una piccola disparità: se hai un legame, prendi tu un compito che di solito spetta a chi ami; se sei senza legame, ricambia un\'amicizia che dà più di quanto riceve.',
    'gesti_tong_shu|Ping|Amore|giorno': 'Oggi governa Ping, il giorno piano. In amore appiana un piccolo attrito: se hai un legame, ascolta fino in fondo la versione di chi ami prima di rispondere; se sei senza legame, chiarisci con garbo un malinteso nato in una conoscenza recente.',
    'gesti_tong_shu|Ping|Amore|mese': 'I trenta giorni che cominciano oggi con Ping, l\'ufficiale delle cose messe in pari, chiedono agli affetti riconoscimento reciproco. Ogni settimana riconosci a voce, a chi ami o a un\'amicizia se sei senza legame, un gesto che compie per te e che di solito dai per scontato. Comincia adesso.',
    'gesti_tong_shu|Ping|Amore|settimana': 'Ping, che rimette in equilibrio, dà oggi il tono a sette giorni di parità negli affetti. Se hai un legame, lascia ogni sera a chi ami la scelta di qualcosa, il film, la cena, la passeggiata; se sei senza legame, lascia scegliere a un\'amicizia il programma della serata.',
    'gesti_tong_shu|Ping|Carriera|anno': 'Ping, sotto cui è nato a Capodanno il tuo anno cinese, chiede al lavoro un piano ben in bolla. Regola adesso la tua postazione: lo schermo all\'altezza degli occhi, la sedia alla giusta misura, il piano sgombro e dritto. Un luogo in pari aiuta il lavoro di ogni giorno.',
    'gesti_tong_shu|Ping|Carriera|giorno': 'Oggi l\'almanacco indica Ping, il giorno che rende uniforme, adatto ai lavori di rifinitura. Al lavoro correggi un documento pieno di imprecisioni: rileggilo ad alta voce, sistema le cifre e i nomi, uniforma i caratteri. Rifinire vale quanto creare, a volte di più.',
    'gesti_tong_shu|Ping|Carriera|mese': 'Trenta giorni di lavoro e di studio partono oggi da Ping, che aggiusta ciò che zoppica. Scegli lo strumento che usi di più, un programma, un modello di documento, un\'abitudine di metodo: miglioralo un poco ogni settimana. Adesso correggi il primo difetto che noti.',
    'gesti_tong_shu|Ping|Carriera|settimana': 'Nel lavoro, la settimana che nasce oggi sotto Ping, che smussa i picchi, chiede un carico distribuito. Apri l\'agenda dei sette giorni e sposta gli impegni dai giorni troppo fitti a quelli più leggeri. Fallo adesso, prima di ogni altra cosa.',
    'gesti_tong_shu|Ping|Fortuna|anno': 'Quest\'anno cinese è nato a Capodanno sotto Ping, che rende scorrevole il passaggio: per le occasioni il gesto è togliere un intralcio. Fallo adesso in casa: sposta il mobile in cui urti sempre, fissa il tappeto che si arriccia, libera il corridoio. Dove si passa bene, si passa più spesso.',
    'gesti_tong_shu|Ping|Fortuna|giorno': 'Oggi è Ping, il giorno che leviga, legato dalla tradizione ai lavori di abbellimento. Per le occasioni abbellisci il luogo dove passi più tempo: un fiore in un bicchiere, un panno sulla superficie opaca, una luce meglio orientata. Un ambiente curato prepara l\'accoglienza.',
    'gesti_tong_shu|Ping|Fortuna|mese': 'Il mese di Ping, ufficiale delle superfici lisce, comincia oggi: per le occasioni prepara l\'accoglienza. Nei trenta giorni rinnova l\'ingresso di casa, il luogo dove si arriva: una soglia pulita, uno zerbino nuovo, una luce calda accanto alla porta. Comincia adesso con un solo dettaglio.',
    'gesti_tong_shu|Ping|Fortuna|settimana': 'Le occasioni dei sette giorni che oggi apre Ping, che rende piana la strada, passano più volentieri dove non si inciampa. Individua un ostacolo pratico che ti frena, una pratica in sospeso, un documento da rinnovare: toglilo di mezzo adesso, senza rimandare.',
    'gesti_tong_shu|Ping|Generale|anno': 'Ping, che rende pari ciò che pende, ha dato a Capodanno il suo segno al tuo anno cinese. Il gesto vale in qualunque momento: restituisci adesso una cosa ricevuta in prestito, un libro, oppure ricambia un favore rimasto senza risposta. I conti di cortesia tornano in pari.',
    'gesti_tong_shu|Ping|Generale|giorno': 'Oggi è il giorno di Ping, l\'ufficiale che livella: l\'almanacco lo trova adatto anche ad aggiustare. Ripara adesso una piccola cosa rimasta guasta, un bottone che pende, una maniglia che cigola, una lampadina spenta. Rimettere in pari le piccole cose dà ordine all\'intera giornata.',
    'gesti_tong_shu|Ping|Generale|mese': 'Ping, che spiana ogni dislivello, segna l\'avvio del tuo mese. Per i trenta giorni cerca un ritmo pari: dopo ogni ora di impegno intenso concediti qualche minuto di pausa, in piedi, lontano dagli schermi. Comincia adesso con la prima pausa e respira a fondo.',
    'gesti_tong_shu|Ping|Generale|settimana': 'La settimana che oggi apre Ping, che porta le cose al pari, chiede occhi attenti alle linee storte. Raddrizza i quadri, allinea i libri sullo scaffale, metti in squadra il tappeto. Ogni giorno dei sette sistema una linea che pende: è il gesto dell\'ufficiale.',
    'gesti_tong_shu|Po|Amore|anno': 'Sotto Po, nemico delle forme irrigidite, il tuo anno cinese è nato a Capodanno. Negli affetti scegli adesso una pretesa rigida, verso chi ami o verso chi cerchi: rompila con un gesto contrario, cedi il passo, cambia programma, lascia scegliere all\'altra persona.',
    'gesti_tong_shu|Po|Amore|giorno': 'Oggi governa Po, il giorno della frattura, poco adatto agli affetti nuovi secondo l\'almanacco. Non forzare dichiarazioni né decisioni importanti. Rompi piuttosto un\'abitudine che riapre ferite: archivia la conversazione che continui a rileggere e non tornarci per tutta la giornata.',
    'gesti_tong_shu|Po|Amore|mese': 'Po, che manda in frantumi il vecchio, governa il giorno da cui partono trenta giorni di pulizia negli affetti. Non progettare dichiarazioni: prendi una lettera mai spedita, un biglietto di un amore finito o di una lite: strappalo a pezzi piccoli e gettalo. Ogni settimana lascia andare un peso così.',
    'gesti_tong_shu|Po|Amore|settimana': 'Con Po, che infrange, comincia oggi una settimana degli affetti che non è fatta per le grandi svolte. Rompi invece un copione che si ripete, la stessa discussione con chi ami o la stessa scelta sbagliata se sei senza legame: cambia adesso la prima battuta.',
    'gesti_tong_shu|Po|Carriera|anno': 'Po, che fa crollare ciò che non regge, ha segnato a Capodanno la nascita del tuo anno cinese. Nel lavoro il suo gesto è lasciare un metodo che ti rallenta: abbandonalo adesso e scrivi con che cosa lo sostituisci. Un metodo caduto fa posto a uno migliore.',
    'gesti_tong_shu|Po|Carriera|giorno': 'Oggi l\'almanacco segna Po, il giorno della demolizione, sfavorevole agli inizi e alle intese. Al lavoro non lanciare progetti nuovi: apri piuttosto il cassetto delle bozze e getta le carte che non servono più, appunti superati, stampe doppie. Togliere il guasto è il compito di questo giorno.',
    'gesti_tong_shu|Po|Carriera|mese': 'Nel lavoro e nello studio, il mese che oggi apre Po è adatto a smantellare, non a lanciare. Scegli una riunione che non decide nulla o un passaggio doppio: scrivi adesso a chi ne decide una proposta chiara per toglierlo di mezzo nei trenta giorni.',
    'gesti_tong_shu|Po|Carriera|settimana': 'Sotto Po, che abbatte, la settimana di lavoro comincia togliendo. Spezza le interruzioni: per sette giorni spegni le notifiche per un\'ora ogni mattina e lavora a una cosa sola. Comincia adesso, con la prima ora. I progetti nuovi possono attendere i giorni seguenti.',
    'gesti_tong_shu|Po|Fortuna|anno': 'Per le occasioni, l\'anno cinese nato sotto Po a Capodanno chiede di demolire una scusa prima di cercare. Smetti adesso di ripetere la frase con cui rifiuti in partenza ciò che non conosci: ogni volta che ti sale alle labbra, sostituiscila con una domanda.',
    'gesti_tong_shu|Po|Fortuna|giorno': 'Oggi è Po, il giorno che recide, in cui l\'almanacco consiglia di non intraprendere nulla di propizio. Per le occasioni il gesto è tagliare un vincolo inutile: cancella un\'iscrizione automatica che ti riempie la casella di posta o il telefono. Così la strada resta più libera.',
    'gesti_tong_shu|Po|Fortuna|mese': 'Strada sgombra: è ciò che chiedono le occasioni dei trenta giorni che partono oggi con Po, che scioglie i nodi stretti. Individua l\'abitudine che ti blocca più spesso, come dire di sì a tutto: spezzala adesso con un no gentile, poi ripeti quel no una volta a settimana.',
    'gesti_tong_shu|Po|Fortuna|settimana': 'Po, l\'ufficiale che separa, apre oggi una settimana in cui le occasioni non si inseguono: la tradizione lo lascia al disfare. Elimina adesso un impegno che ti pesa senza portarti nulla e rimanda ai giorni seguenti ogni passo nuovo. Prima si libera la strada.',
    'gesti_tong_shu|Po|Generale|anno': 'L\'anno cinese ha ricevuto a Capodanno il segno di Po, l\'ufficiale che spezza. Il suo gesto è rompere la consuetudine: cambia adesso un gesto quotidiano, la strada abituale, il posto a tavola, la tazza del mattino. Ciò che si rompe con leggerezza lascia passare aria nuova.',
    'gesti_tong_shu|Po|Generale|giorno': 'Oggi è il giorno di Po, l\'ufficiale che rompe: l\'almanacco lo sconsiglia per quasi ogni impresa e lo lascia soltanto al demolire. Non cominciare nulla di importante. Butta via invece un oggetto rotto che conservi senza motivo e lascia quel vuoto com\'è.',
    'gesti_tong_shu|Po|Generale|mese': 'Il primo dei trenta giorni appartiene a Po, che sta all\'opposto di Jian e rompe. Usa il mese per smontare: scegli un mobile o un oggetto ingombrante che non usi più e smontalo pezzo per pezzo nelle settimane, portando via le parti. Comincia oggi dalla prima vite.',
    'gesti_tong_shu|Po|Generale|settimana': 'Po, il giorno della rottura, regge oggi l\'avvio della tua settimana: la tradizione lo trova adatto solo a smontare. Non avviare nulla oggi: individua una cattiva abitudine e spezzala con un gesto preciso, come togliere il telefono dal comodino la sera. Rimanda le partenze ai giorni seguenti.',
    'gesti_tong_shu|Shou|Amore|anno': 'Dal Capodanno lunare il tuo anno cinese porta il segno di Shou, che serba i frutti. Negli affetti raccogli ciò che c\'è già: prepara adesso una cena con quello che hai in casa, senza comprare nulla, per chi ami o, se sei senza legame, per un\'amicizia cara.',
    'gesti_tong_shu|Shou|Amore|giorno': 'Oggi governa Shou, il giorno della mietitura. Negli affetti raccogli i momenti belli: racconta a voce a chi ami, o a chi ti vuole bene se sei senza legame, un ricordo felice vissuto insieme, con tutti i dettagli che ricordi.',
    'gesti_tong_shu|Shou|Amore|mese': 'Trenta giorni per gli affetti partono oggi con Shou, che accoglie il frutto maturo. Ogni settimana scegli una foto di un momento bello, con chi ami o con chi ti è caro: stampala e mettila in un album dedicato. Comincia adesso dalla più recente.',
    'gesti_tong_shu|Shou|Amore|settimana': 'Shou, l\'ufficiale che fa il bilancio dei frutti, invita oggi gli affetti a riconoscere ciò che hanno già dato. Ogni sera dei sette giorni, prima di dormire, richiama alla mente una cosa bella ricevuta da chi ami o, se sei senza legame, da un\'amicizia cara. Comincia stasera, senza fretta.',
    'gesti_tong_shu|Shou|Carriera|anno': 'Il tuo anno cinese, venuto al mondo a Capodanno sotto Shou, lega il lavoro ai frutti raccolti. Metti adesso in ordine i lavori riusciti in una raccolta da mostrare: progetti, testi, immagini, risultati, ciascuno con una riga di spiegazione. Ciò che hai raccolto parla per te.',
    'gesti_tong_shu|Shou|Carriera|giorno': 'Oggi l\'almanacco indica Shou, il giorno che tira le somme, propizio anche a chi studia. Al lavoro annota in una pagina le lezioni dell\'ultimo progetto: che cosa ha funzionato, gli errori, le soluzioni trovate. Tienila a portata di mano per il prossimo lavoro.',
    'gesti_tong_shu|Shou|Carriera|mese': 'Lo studio e il lavoro dei trenta giorni che cominciano oggi seguono Shou, l\'ufficiale delle messi. Raccogli i riscontri: chiedi a due persone con cui lavori che cosa funziona nel tuo modo di fare e che cosa cambierebbero. Fai adesso la prima domanda e ascolta senza difenderti.',
    'gesti_tong_shu|Shou|Carriera|settimana': 'Shou, che la tradizione lega anche allo studio oltre che al raccolto, segna oggi la tua settimana di lavoro e di studio. Scegli una competenza da coltivare nei sette giorni e dedica adesso mezz\'ora alla prima lezione. Studiare è raccogliere per il tempo che viene.',
    'gesti_tong_shu|Shou|Fortuna|anno': 'Nel tuo anno cinese, nato sotto Shou a Capodanno, le occasioni passano spesso per mani già vicine. Accetta adesso un\'offerta di aiuto che di solito rifiuti: un passaggio, un consiglio, una mano in un lavoro. Ricevere con un sì pieno è il gesto di Shou.',
    'gesti_tong_shu|Shou|Fortuna|giorno': 'Oggi è Shou, il giorno che porta dentro il raccolto, sconsigliato dall\'almanacco per i viaggi lunghi. Per le occasioni resta nei paraggi: rispondi adesso alle proposte arrivate, rileggi gli inviti ricevuti, segna quali meritano un sì. Spesso l\'occasione è già sulla soglia.',
    'gesti_tong_shu|Shou|Fortuna|mese': 'Il mese che oggi apre Shou, l\'ufficiale che riempie il granaio, invita a cercare le occasioni vicine, senza lunghi viaggi. Ogni settimana esplora a piedi una via vicina a casa che non conosci, entra in una bottega, saluta chi incontri. Comincia adesso con la prima.',
    'gesti_tong_shu|Shou|Fortuna|settimana': 'In questa settimana aperta oggi da Shou, che vede maturare il seminato, le occasioni nascono dagli incontri recenti. Ripercorri le persone conosciute di recente e scegli l\'incontro da far crescere: riprendilo adesso con un invito vicino a casa, perché la tradizione sconsiglia i viaggi lunghi.',
    'gesti_tong_shu|Shou|Generale|anno': 'L\'anno cinese che stai vivendo è nato a Capodanno sotto Shou, che ritira ciò che è maturo. Il gesto vale in ogni momento dell\'anno: fai adesso il giro della casa con un cesto e raccogli ciò che è fuori posto, poi rimetti ogni cosa dove deve stare.',
    'gesti_tong_shu|Shou|Generale|giorno': 'Oggi è il giorno di Shou, l\'ufficiale che raccoglie: l\'almanacco antico dice che dopo il compimento viene il raccolto. Fermati a mettere in fila ciò che hai ottenuto in questo tempo e scrivilo in un elenco. Leggilo con calma e riconosci il cammino fatto.',
    'gesti_tong_shu|Shou|Generale|mese': 'Il mese che comincia oggi prende il segno da Shou, l\'ufficiale che mette al riparo. Prepara nei trenta giorni una piccola conserva fatta in casa: una marmellata, un barattolo di erbe essiccate, un vasetto di frutta sciroppata. Comincia adesso scegliendo che cosa mettere da parte.',
    'gesti_tong_shu|Shou|Generale|settimana': 'Shou, che riunisce i frutti, governa oggi la settimana che hai davanti. Raduna ciò che è sparso, foto, appunti, idee annotate in tanti posti diversi, in un unico luogo. Fallo adesso e scegli quale idea coltivare nei sette giorni: il raccolto precede ogni semina.',
    'gesti_tong_shu|Wei|Amore|anno': 'Nella vita sentimentale, l\'anno cinese nato a Capodanno sotto Wei chiede di procedere con tatto. Prima di ogni parola difficile, con chi ami, in famiglia o con chi frequenti, fai adesso tre respiri lenti: lascia che la fretta passi prima di parlare.',
    'gesti_tong_shu|Wei|Amore|giorno': 'Oggi governa Wei, il giorno che chiede attenzione. Negli affetti non affrontare di fretta le questioni delicate: se una parola difficile preme, rimandala a un momento calmo. Intanto ascolta, con chi ami o con chi stai conoscendo, più di quanto parli.',
    'gesti_tong_shu|Wei|Amore|mese': 'Il mese degli affetti che nasce oggi sotto Wei, che vuole cautela e voti sinceri, chiede delicatezza più che slancio. Ogni settimana scrivi a mano un augurio breve, per chi ami o per chi speri di incontrare: raccoglilo in un quaderno dedicato. Scrivi il primo adesso.',
    'gesti_tong_shu|Wei|Amore|settimana': 'La prudenza di Wei accompagna la settimana degli affetti che comincia oggi: ciò che è fragile va protetto, non messo alla prova. Se hai un legame, prepara a chi ami qualcosa di caldo dopo una giornata pesante; se sei senza legame, fai lo stesso per un\'amicizia.',
    'gesti_tong_shu|Wei|Carriera|anno': 'Il tuo anno cinese porta da Capodanno il segno di Wei e chiede al lavoro passi controllati. Metti adesso al sicuro i dati del progetto più fragile: una copia su un secondo supporto, una password cambiata, una scadenza resa più realistica. Prevedere il guasto è il gesto dell\'ufficiale della cautela.',
    'gesti_tong_shu|Wei|Carriera|giorno': 'Oggi l\'almanacco indica Wei, il giorno del rischio, poco adatto ai salti nel vuoto. Al lavoro controlla due volte prima di inviare: rileggi una comunicazione importante, verifica i dati, i nomi e gli allegati. La cautela di oggi risparmia correzioni in seguito.',
    'gesti_tong_shu|Wei|Carriera|mese': 'Wei, che chiede occhi aperti, governa il primo dei tuoi trenta giorni di lavoro e di studio. Prima di ogni decisione importante del mese chiedi il parere di una persona esperta e ascoltalo fino in fondo. Scegli adesso a chi rivolgerti e fissa il primo colloquio.',
    'gesti_tong_shu|Wei|Carriera|settimana': 'Sotto Wei, che invita a guardarsi intorno, la settimana di lavoro comincia senza cambi bruschi. Annota i punti deboli dei progetti in corso e scegli quale mettere in sicurezza per primo: fallo adesso, con calma, prima di aggiungere altro nei sette giorni.',
    'gesti_tong_shu|Wei|Fortuna|anno': 'Wei ha dato a Capodanno il suo segno all\'anno cinese che stai vivendo, ufficiale vigile che diffida delle partenze. Per le occasioni rinuncia adesso a uno spostamento che non serve, un viaggio fatto per abitudine, una salita rischiosa: le buone occasioni si trovano anche vicino.',
    'gesti_tong_shu|Wei|Fortuna|giorno': 'Oggi è Wei, il giorno in cui la tradizione sconsiglia viaggi rischiosi e salite in alto. Per le occasioni resta con i piedi per terra: davanti a una proposta appena arrivata, chiedi tempo prima di rispondere e valutala con lucidità. Una pausa ponderata è un gesto saggio.',
    'gesti_tong_shu|Wei|Fortuna|mese': 'Per trenta giorni, a partire da oggi, Wei invita le occasioni alla prudenza. Metti in tasca un piccolo sasso liscio e tienilo con te per tutto il mese: prima di ogni sì importante, stringilo e conta fino a dieci. Comincia adesso a portarlo.',
    'gesti_tong_shu|Wei|Fortuna|settimana': 'Wei, l\'ufficiale del discernimento, segna oggi una settimana in cui le occasioni vanno pesate. Scrivi adesso, accanto a ogni possibilità che vedi, un rischio e una precauzione. Dedica poi qualche minuto di raccoglimento a ciò che speri nei sette giorni.',
    'gesti_tong_shu|Wei|Generale|anno': 'Wei, l\'ufficiale che veglia dopo la rottura, ha visto nascere a Capodanno il tuo anno cinese. Il suo gesto è la prudenza, buona in ogni giorno: fai adesso il giro della casa e controlla serrature, rubinetti, prese e fornelli. Ciò che è in ordine lascia riposare la mente.',
    'gesti_tong_shu|Wei|Generale|giorno': 'Oggi è il giorno di Wei, l\'ufficiale del pericolo: l\'almanacco lo consiglia per il raccoglimento e sconsiglia di salire in alto o di cambiare casa. Prenditi cinque minuti di silenzio in un luogo tranquillo e dedica un pensiero a chi vuoi proteggere.',
    'gesti_tong_shu|Wei|Generale|mese': 'Trenta giorni sotto Wei, che chiede passi misurati, cominciano oggi. Ogni sera accendi una candela per qualche minuto e, guardando la fiamma, ripensa alla giornata: dove hai corso troppo, dove è servita attenzione. Comincia stasera. Rimanda i traslochi e le salite rischiose.',
    'gesti_tong_shu|Wei|Generale|settimana': 'Wei, il giorno della vigilanza, governa oggi la tua settimana: la tradizione lo affida ai voti, non agli spostamenti. Rileggi adesso con calma i piani dei sette giorni e accanto a ogni uscita segna un margine di tempo in più. Chi ha tempo non corre rischi.',
    'gesti_tong_shu|Zhi|Amore|anno': 'Gli affetti del tuo anno cinese, nato a Capodanno sotto Zhi, chiedono di tenere caro ciò che c\'è. Rinnova adesso un gesto che avevate perso, con chi ami o con chi ti vuole bene da sempre: un caffè insieme al mattino, una canzone, un luogo dove tornare.',
    'gesti_tong_shu|Zhi|Amore|giorno': 'Oggi governa Zhi, il giorno della fedeltà. In amore mantieni oggi stesso una piccola promessa: a chi ami, se hai un legame; a te, se sei senza legame, come accettare un invito per incontrare persone nuove. Una parola tenuta vale più di dieci dette.',
    'gesti_tong_shu|Zhi|Amore|mese': 'Zhi, l\'ufficiale che non lascia cadere, apre oggi trenta giorni in cui gli affetti si rafforzano con la costanza. Scegli un legame che conta, un amore, un\'amicizia, un familiare: chiama quella persona ogni settimana nello stesso momento, anche solo per pochi minuti. Fai adesso la prima chiamata.',
    'gesti_tong_shu|Zhi|Amore|settimana': 'Affidata a Zhi, che difende ciò che esiste già, la settimana degli affetti non chiede novità. Se hai un legame, scegli con chi ami un\'abitudine che vi fa bene e proteggetela da ogni impegno; se sei senza legame, tieni ferma un\'ora per ciò che ti appassiona. Decidila adesso.',
    'gesti_tong_shu|Zhi|Carriera|anno': 'L\'anno cinese, che Zhi ha accolto a Capodanno, chiede al lavoro di non lasciar sfumare ciò che hai costruito. Scegli adesso un risultato ottenuto e insegnalo a chi lavora con te: mostra il percorso che lo ha reso possibile. Ciò che si trasmette non va perduto.',
    'gesti_tong_shu|Zhi|Carriera|giorno': 'Oggi l\'almanacco indica Zhi, il giorno che trattiene. Al lavoro metti al sicuro un risultato già ottenuto: salva le versioni definitive, fai una copia dei file importanti, conserva in un luogo protetto ciò che ti è costato fatica. Ciò che è al sicuro resta a disposizione.',
    'gesti_tong_shu|Zhi|Carriera|mese': 'Trenta giorni di cura cominciano oggi con Zhi, che non disperde il lavoro fatto. Nel lavoro e nello studio scrivi una guida di come svolgi il compito più importante, una pagina alla settimana. Comincia adesso dalla prima, con parole semplici che altri possano seguire.',
    'gesti_tong_shu|Zhi|Carriera|settimana': 'Sotto Zhi, che regge ciò che è avviato, la settimana di lavoro chiede costanza più che novità. Scegli il progetto principale dei sette giorni e dedicagli adesso la prima ora, senza aprire altri fronti. Ripeti quell\'ora ogni mattina fino al settimo giorno.',
    'gesti_tong_shu|Zhi|Fortuna|anno': 'Le buone occasioni dell\'anno cinese, nato sotto Zhi a Capodanno, si fermano dove trovano cura. Proponi adesso di rivedere di persona un contatto prezioso che rischi di perdere: fissa un caffè, una passeggiata, una visita. Mantenere i legami è il gesto di Zhi.',
    'gesti_tong_shu|Zhi|Fortuna|giorno': 'Oggi è Zhi, il giorno della presa salda. Per le occasioni non lasciar cadere un contatto prezioso: rispondi adesso a un messaggio rimasto aperto oppure ringrazia chi ti ha dato una mano. Le occasioni restano volentieri vicine a chi sa tenerle.',
    'gesti_tong_shu|Zhi|Fortuna|mese': 'Per le occasioni, il mese che si apre oggi sotto Zhi, che serba ciò che è buono, chiede di ricambiare. Ogni settimana dei trenta giorni ricambia un favore ricevuto: un aiuto, un\'indicazione, un passaggio. Fallo adesso per la prima volta, scegliendo il favore più vecchio.',
    'gesti_tong_shu|Zhi|Fortuna|settimana': 'Zhi, l\'ufficiale che tiene vicino ciò che vale, segna oggi una settimana in cui le occasioni vengono da ciò che hai già. Scorri la rubrica e scegli tre persone con cui riallacciare un filo nei sette giorni. Comincia adesso con la prima: un saluto semplice, senza richieste.',
    'gesti_tong_shu|Zhi|Generale|anno': 'Sotto Zhi, che mantiene ciò che c\'è, il tuo anno cinese è nato a Capodanno. Il suo gesto è la manutenzione, buona in qualunque giorno: prendi adesso una cosa che usi da tempo e rimettila in forma, come lucidare le scarpe, cucire una fodera, oliare la catena della bicicletta.',
    'gesti_tong_shu|Zhi|Generale|giorno': 'Oggi è il giorno di Zhi, l\'ufficiale che tiene: l\'almanacco antico dice che conserva ciò che è stato compiuto. Scegli una buona abitudine che hai già e ripetila adesso con più attenzione del solito. Mantenere vale quanto cominciare, ricorda questo giorno.',
    'gesti_tong_shu|Zhi|Generale|mese': 'Il mese che parte oggi porta il segno di Zhi, che protegge il compiuto ed è propizio a edificare. Costruisci qualcosa di piccolo un poco ogni settimana: una mensola, un modellino, un orto sul balcone. Comincia adesso con il primo pezzo e lascialo dove si vede.',
    'gesti_tong_shu|Zhi|Generale|settimana': 'Zhi, che tiene saldo il raggiunto, governa la settimana che nasce oggi: la tradizione lo dà buono anche per costruire e piantare. Metti a dimora un seme in un vaso e annaffialo ogni giorno dei sette. Mentre lo fai, pensa a ciò che vuoi far durare.',
    'inni_orfici|Giove|Amore|anno': 'Sotto Giove, dal compleanno, il tuo anno chiede agli affetti un cuore largo. Adesso scrivi su un foglio tre qualità che offri a chi ami o a chi desideri incontrare. Sussurra «Zeus molto onorato, Zeus immortale» due volte e conserva il foglio in un luogo caro.',
    'inni_orfici|Giove|Amore|giorno': 'Giove, generoso con chi sa dare senza misurare, regge questa giornata. Pensa a un gesto buono ricevuto da chi ami o, se sei senza legame, da un\'amicizia. Sussurra «Zeus molto onorato, Zeus immortale» e ringrazia oggi a voce, con una parola sincera.',
    'inni_orfici|Giove|Amore|mese': 'Con Giove nasce oggi un mese in cui gli affetti chiedono spazio e calore. Accendi una candela azzurra o viola, pensa alla persona amata o a chi desideri accogliere nella tua vita e sussurra due volte «Zeus molto onorato, Zeus immortale». Ogni giovedì riaccendila per qualche istante.',
    'inni_orfici|Giove|Amore|settimana': 'Questa settimana comincia oggi, giovedì di Giove, protettore degli ospiti: chiede agli affetti accoglienza. Prepara la tavola con un posto in più, anche solo come simbolo. A mente ripeti due volte «Zeus molto onorato, Zeus immortale» pensando a chi ami o a chi vorresti accanto.',
    'inni_orfici|Giove|Carriera|anno': 'Nel segno di Giove, padre saggio, è nato il tuo anno, dal compleanno: nel lavoro conta il buon consiglio. Adesso chiedi un parere a una persona più esperta, oppure offri il tuo a chi ne sa meno. Pronuncia «Zeus molto onorato, Zeus immortale» tre volte prima di parlare.',
    'inni_orfici|Giove|Carriera|giorno': 'Nel giorno di Giove, che aveva per albero la quercia, il lavoro chiede radici e visione. Prima di cominciare posa la mano su un tavolo o su un oggetto di legno. Pronuncia sottovoce «Zeus molto onorato, Zeus immortale», poi dedica qualche minuto al progetto più ampio che hai.',
    'inni_orfici|Giove|Carriera|mese': 'Con il giovedì di Giove, che allarga gli orizzonti, nasce oggi un mese di lavoro e di studio. Disegna su un foglio tre cerchi concentrici e scrivi al centro l\'obiettivo principale. Pronuncia sottovoce «Zeus molto onorato, Zeus immortale» tre volte, poi appendi il foglio dove lavori.',
    'inni_orfici|Giove|Carriera|settimana': 'Comincia oggi, giovedì, una settimana di Giove in cui il lavoro invita a pensare in grande con giustizia. Scrivi l\'obiettivo dei sette giorni in cima a una pagina nuova. Recita tre volte «Zeus molto onorato, Zeus immortale» e sottolinea la parola che lo riassume meglio.',
    'inni_orfici|Giove|Fortuna|anno': 'Giove accompagna dal compleanno il tuo anno e premia chi sa accogliere. Adesso spalanca per un istante porta e finestra e lascia entrare l\'aria. Ripeti a voce bassa «Zeus molto onorato, Zeus immortale», poi dai spazio a una possibilità rimasta in sospeso.',
    'inni_orfici|Giove|Fortuna|giorno': 'Sotto Giove, oggi, la buona sorte cerca chi tiene la porta socchiusa. Esci all\'aperto e fai qualche passo largo, senza fretta, guardando lontano. Ripeti a voce bassa «Zeus molto onorato, Zeus immortale» e nota le possibilità che si allargano davanti a te.',
    'inni_orfici|Giove|Fortuna|mese': 'Oggi, giovedì di Giove, dio dell\'abbondanza, prende slancio un mese di occasioni ampie. Ogni giovedì, per trenta giorni, accetta un invito o proponi tu un incontro a qualcuno. Ripeti a voce bassa «Zeus molto onorato, Zeus immortale» due volte prima di uscire di casa.',
    'inni_orfici|Giove|Fortuna|settimana': 'Da oggi, giovedì, Giove, che nutre ogni crescita, guida sette giorni di occasioni. Annaffia una pianta di casa e scegli una foglia nuova da guardare ogni giorno. Sussurra «Zeus molto onorato, Zeus immortale» due volte e accogli le occasioni che spuntano piano.',
    'inni_orfici|Giove|Generale|anno': 'Giove regge il tuo anno, nato di giovedì dal compleanno: il re degli dèi chiede uno sguardo alto. Adesso cerca dalla finestra o all\'aperto il punto più alto che vedi, una cima, un tetto, una nuvola. Recita «Zeus molto onorato, Zeus immortale» e lascia che i pensieri salgano fin lì.',
    'inni_orfici|Giove|Generale|giorno': 'Oggi è il giorno di Giove, il pianeta della larghezza e della fiducia. Apri le braccia, inspira a fondo e lascia entrare spazio nel petto. Recita tre volte, con voce calma, «Zeus molto onorato, Zeus immortale», poi concediti un\'ora senza fretta e senza misura.',
    'inni_orfici|Giove|Generale|mese': 'Il mese che nasce oggi, giovedì, porta la generosità di Giove, che dà a piene mani. Scegli in casa un libro o un oggetto in buono stato che non usi più e regalalo a chi può goderne. Recita tre volte «Zeus molto onorato, Zeus immortale» mentre lo prepari.',
    'inni_orfici|Giove|Generale|settimana': 'Sotto Giove, signore del cielo aperto, si apre oggi, giovedì, una settimana dal respiro ampio. Metti su un davanzale un ramo verde come offerta. Ripeti a voce bassa «Zeus molto onorato, Zeus immortale» per tre volte, guardando il cielo sopra le case, poi lascia lì il ramo per sette giorni.',
    'inni_orfici|Luna|Amore|anno': 'La Luna regge il tuo anno, nato di lunedì dal compleanno: negli affetti chiede ascolto e tenerezza. Adesso scrivi su un foglietto una parola dolce per chi ami o per chi desideri incontrare. Mettilo sotto il cuscino e sussurra una volta «Ascolta, dea regina, portatrice di luce, divina Selene».',
    'inni_orfici|Luna|Amore|giorno': 'La Luna, custode di ciò che si sente prima di dirlo, governa questa giornata. Prima di dormire accendi per qualche minuto una candela bianca e pensa a chi ami o a chi speri di incontrare. Sussurra tre volte, piano, «Ascolta, dea regina, portatrice di luce, divina Selene».',
    'inni_orfici|Luna|Amore|mese': 'Sotto la Luna di questo lunedì, che sa ascoltare, nasce un mese per gli affetti. Ogni lunedì, per trenta giorni, metti una canzone che ti fa pensare a chi ami o, se sei senza legame, all\'incontro che speri. Poi sussurra «Ascolta, dea regina, portatrice di luce, divina Selene».',
    'inni_orfici|Luna|Amore|settimana': 'Da oggi, lunedì, la Luna guida una settimana che invita gli affetti alla dolcezza. Metti sul comodino un oggetto color argento. Ogni sera, toccandolo, ripeti a mente «Ascolta, dea regina, portatrice di luce, divina Selene» pensando alla persona amata o, se sei senza legame, a chi desideri accanto.',
    'inni_orfici|Luna|Carriera|anno': 'Il compleanno ha messo il tuo anno nel segno della Luna, che cala per poi crescere. Adesso svuota la borsa o lo zaino del lavoro e rimetti dentro soltanto ciò che serve. Pronuncia sottovoce «Ascolta, dea regina, portatrice di luce, divina Selene», poi riprendi il lavoro con passo leggero.',
    'inni_orfici|Luna|Carriera|giorno': 'Nel giorno della Luna il lavoro va ascoltato più che forzato. Prima di una decisione chiudi gli occhi e conta nove respiri lenti. Recita sottovoce «Ascolta, dea regina, portatrice di luce, divina Selene», poi lascia che l\'intuizione suggerisca il passo seguente.',
    'inni_orfici|Luna|Carriera|mese': 'Un mese di lavoro e di studio parte oggi nel giorno della Luna, che procede per gradi. Dividi su un foglio il progetto principale in quattro parti, una per ogni fase lunare. Recita sottovoce «Ascolta, dea regina, portatrice di luce, divina Selene» e comincia dalla parte più piccola.',
    'inni_orfici|Luna|Carriera|settimana': 'Comincia oggi, lunedì, sotto la Luna, una settimana in cui i progetti chiedono pazienza e ritmo. Sul quaderno degli impegni traccia una piccola falce di luna. Pronuncia due volte, a voce bassa, «Ascolta, dea regina, portatrice di luce, divina Selene» e affida il lavoro al passo di questi giorni.',
    'inni_orfici|Luna|Fortuna|anno': 'Dal compleanno il tuo anno cammina sotto la Luna, che riporta ciò che si era allontanato. Adesso apri un cassetto e ritrova un oggetto dimenticato da tempo. Tienilo e sussurra «Ascolta, dea regina, portatrice di luce, divina Selene», poi lascialo in vista: certe occasioni ritornano, come la luce lunare.',
    'inni_orfici|Luna|Fortuna|giorno': 'Sotto la Luna di oggi, regina della notte, le occasioni arrivano piano. Dopo il tramonto fai due passi all\'aria della sera, senza meta. Ripeti a mente tre volte «Ascolta, dea regina, portatrice di luce, divina Selene» e accogli ciò che si avvicina, senza inseguirlo.',
    'inni_orfici|Luna|Fortuna|mese': 'Oggi, lunedì della Luna, prende il via un mese di occasioni che vanno e vengono. Metti in un vaso un fiore bianco o un ramo chiaro e sussurra «Ascolta, dea regina, portatrice di luce, divina Selene». Per trenta giorni, ogni volta che lo guardi, annota un\'occasione intravista o colta.',
    'inni_orfici|Luna|Fortuna|settimana': 'Questa settimana nasce di lunedì, oggi, nel giorno della Luna, sotto un cielo che cambia di notte in notte. Tieni in tasca un sassolino bianco raccolto da te. Toccalo e sussurra «Ascolta, dea regina, portatrice di luce, divina Selene», ricordando che anche le occasioni hanno le loro maree.',
    'inni_orfici|Luna|Generale|anno': 'Di lunedì, nel giorno della Luna, è nato il tuo anno dal compleanno: un anno che cambia volto come lei. Adesso guarda la luce riflessa su uno specchio o su un vetro. Mormora «Ascolta, dea regina, portatrice di luce, divina Selene» e lascia che l\'anno trovi il suo ritmo.',
    'inni_orfici|Luna|Generale|giorno': 'Oggi è il giorno della Luna, che misura il tempo con le sue fasi. Questa sera, se puoi, guarda il cielo da una finestra, oppure chiudi gli occhi e immaginalo. Mormora due volte «Ascolta, dea regina, portatrice di luce, divina Selene» e lascia andare la giornata.',
    'inni_orfici|Luna|Generale|mese': 'Il mese parte oggi, lunedì, sotto la Luna che cresce e cala senza fretta. Questa sera spegni ogni luce per qualche minuto e lascia che gli occhi si abituino al buio. Sussurra due volte «Ascolta, dea regina, portatrice di luce, divina Selene», poi riaccendi una lampada sola.',
    'inni_orfici|Luna|Generale|settimana': 'La settimana si apre oggi, lunedì, sotto la luce mutevole della Luna. Versa dell\'acqua in una ciotola chiara e guarda per un istante il tuo riflesso. Recita a mezza voce «Ascolta, dea regina, portatrice di luce, divina Selene», poi offri quell\'acqua a una pianta di casa.',
    'inni_orfici|Marte|Amore|anno': 'Il tuo anno porta, dal compleanno, il segno di Marte: un fuoco che chiede gioia più che conflitto. Adesso metti una musica che ti piace e pensa a chi ami o a chi vorresti incontrare. Canta piano il verso dell\'inno, «Volgiti al desiderio di Cipride e alle feste di Lieo».',
    'inni_orfici|Marte|Amore|giorno': 'Marte, che accende il desiderio, governa questa giornata degli affetti. Versa nel bicchiere qualcosa che ti piace e alzalo in un brindisi silenzioso a chi ami o a chi desideri incontrare. Poi sussurra due volte le parole dell\'inno, «Volgiti al desiderio di Cipride e alle feste di Lieo».',
    'inni_orfici|Marte|Amore|mese': 'Sotto Marte nasce oggi un mese per gli affetti, pieno di calore. Proponi una serata di festa a chi ami o, se sei senza legame, agli amici cari: una cena semplice o un ballo. Apri la festa con l\'inno, «Volgiti al desiderio di Cipride e alle feste di Lieo».',
    'inni_orfici|Marte|Amore|settimana': 'Da oggi, martedì, Marte guida una settimana di passione e pazienza corta. Ogni volta che senti salire una parola dura, respira a fondo e ripeti a mente «Volgiti al desiderio di Cipride e alle feste di Lieo», pensando alla persona amata o, se sei senza legame, a chi vorresti accanto.',
    'inni_orfici|Marte|Carriera|anno': 'Nel martedì di Marte è nato il tuo anno, dal compleanno: un vigore per il lavoro e lo studio. Adesso spezza un pezzo di pane e mangialo con calma prima di rimetterti all\'opera. Recita a mente le parole dell\'inno, «mutando la forza delle armi nelle opere di Demetra».',
    'inni_orfici|Marte|Carriera|giorno': 'Nel giorno di Marte conviene affrontare ciò che rimandi. Prima di metterti al lavoro alzati in piedi e raddrizza le spalle, come chi depone lo scudo. Pronuncia le parole dell\'inno, «mutando la forza delle armi nelle opere di Demetra», poi metti la tua energia nel compito più temuto.',
    'inni_orfici|Marte|Carriera|mese': 'Trenta giorni di lavoro partono oggi, nel martedì di Marte, signore della spada. Tempera una matita o affila lo strumento che usi di più, come chi muta un\'arma in un attrezzo. Mormora il verso orfico, «mutando la forza delle armi nelle opere di Demetra»; ogni martedì riprendi quello strumento.',
    'inni_orfici|Marte|Carriera|settimana': 'Comincia oggi, martedì, una settimana di Marte: il lavoro chiede coraggio più che fretta. Scrivi su un foglio il compito più pesante e piegalo in quattro. Leggi tre volte il verso dell\'inno, «mutando la forza delle armi nelle opere di Demetra», poi tienilo in tasca per sette giorni.',
    'inni_orfici|Marte|Fortuna|anno': 'Marte vuole, dal compleanno, che il tuo anno rivolga l\'audacia alle occasioni buone. Adesso togli le foglie secche a una pianta di casa. Ripeti due volte l\'invocazione dell\'inno, «mutando la forza delle armi nelle opere di Demetra», poi muovi un passo verso un\'occasione in attesa.',
    'inni_orfici|Marte|Fortuna|giorno': 'Sotto Marte, oggi, le occasioni chiedono un gesto pronto. Cammina con passo deciso fino a un giardino o a un\'aiuola del quartiere. Lì rivolgi ad Ares le parole dell\'inno, «mutando la forza delle armi nelle opere di Demetra», poi tocca la terra con la mano, come chi semina.',
    'inni_orfici|Marte|Fortuna|mese': 'Oggi, martedì di Marte, prende avvio un mese in cui la buona sorte si coltiva. Riempi un vaso di terra e interra tre semi. Prega piano con le parole dell\'inno, «mutando la forza delle armi nelle opere di Demetra», poi annaffiali e guardali crescere in questi trenta giorni.',
    'inni_orfici|Marte|Fortuna|settimana': 'Questa settimana nasce oggi, nel martedì di Marte, che insegna a cogliere l\'attimo con mano ferma. Tieni adesso nel palmo un chicco di grano o di riso. Sussurra una volta il verso dell\'inno, «mutando la forza delle armi nelle opere di Demetra», poi riponilo in tasca per sette giorni.',
    'inni_orfici|Marte|Generale|anno': 'Dal compleanno Marte, dio delle armi, dà al tuo anno un\'energia che cerca pace. Adesso riponi in un cassetto un oggetto con la lama, un coltello o delle forbici. Pronuncia due volte «Ferma la contesa furiosa, allenta il travaglio che addolora l\'animo» e lascia cadere una contesa, anche piccola.',
    'inni_orfici|Marte|Generale|giorno': 'Oggi è il giorno di Marte, la forza che si mette in moto. Stringi le mani a pugno e poi aprile lentamente, sentendo la tensione che scivola via. Recita a voce bassa «Ferma la contesa furiosa, allenta il travaglio che addolora l\'animo» e scegli una sola battaglia.',
    'inni_orfici|Marte|Generale|mese': 'Il mese che parte oggi, martedì, porta lo slancio di Marte. Prendi un nastro rosso e annodalo al polso o alla maniglia di una porta. Recita tre volte «Ferma la contesa furiosa, allenta il travaglio che addolora l\'animo», poi scegli il conflitto da sciogliere in questi trenta giorni.',
    'inni_orfici|Marte|Generale|settimana': 'La settimana si apre oggi, martedì, nel giorno di Marte, con un ardore che chiede una direzione. Accendi una candela rossa e guarda la fiamma per un istante. Ripeti tre volte «Ferma la contesa furiosa, allenta il travaglio che addolora l\'animo», poi spegnila con un soffio deciso.',
    'inni_orfici|Mercurio|Amore|anno': 'Sotto Mercurio, dal compleanno, cammina il tuo anno: negli affetti conta il dialogo. Adesso ritrova un biglietto ricevuto da chi ami o, se sei senza legame, da un\'amicizia cara. Mettilo dove lo vedi e sussurra una volta «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia».',
    'inni_orfici|Mercurio|Amore|giorno': 'Mercurio, che porta le parole da un cuore all\'altro, governa questa giornata. Scrivi un messaggio gentile per chi ami o per chi desideri conoscere, anche senza inviarlo subito. Sussurra «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia» e rileggilo con calma prima di decidere.',
    'inni_orfici|Mercurio|Amore|mese': 'Sotto Mercurio, interprete degli dèi, nasce oggi un mese di parole per gli affetti. Ogni mercoledì fai una domanda sincera a chi ami o, se sei senza legame, a una persona nuova: poi ascolta davvero la risposta. Sussurra «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia» prima di chiedere.',
    'inni_orfici|Mercurio|Amore|settimana': 'Da oggi, mercoledì, Mercurio guida sette giorni di ascolto negli affetti. Ogni sera rileggi l\'ultima conversazione con la persona amata o, se sei senza legame, con chi vorresti conoscere. Ripeti a mente «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia»; poi cerca la frase che merita più gentilezza.',
    'inni_orfici|Mercurio|Carriera|anno': 'Mercurio, svelto di mente, guida dal compleanno il tuo anno: nel lavoro e nello studio contano parole chiare. Adesso archivia i messaggi di lavoro già chiusi. Pronuncia sottovoce «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia», poi rispondi a quello che aspetta da più tempo.',
    'inni_orfici|Mercurio|Carriera|giorno': 'Il mercoledì di Mercurio, patrono dei mercanti e degli scrivani, favorisce gli accordi. Prima di aprire la posta di lavoro togli dalla scrivania un oggetto inutile. Pronuncia sottovoce «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia» e rispondi prima di tutto al messaggio più chiaro.',
    'inni_orfici|Mercurio|Carriera|mese': 'Questo mercoledì di Mercurio, maestro di chi impara, dà avvio a un mese per studiare e scrivere. Scegli una cosa da imparare in questi trenta giorni e scrivila sulla prima pagina di un quaderno. Pronuncia due volte sottovoce «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia» prima di chiuderlo.',
    'inni_orfici|Mercurio|Carriera|settimana': 'Comincia oggi, mercoledì, la settimana di Mercurio: il lavoro passa attraverso parole, viaggi e incontri. Sul tuo calendario segna con un piccolo cerchio il primo appuntamento. Recita due volte «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia» e prepara con cura ciò che vuoi dire.',
    'inni_orfici|Mercurio|Fortuna|anno': 'Dal compleanno il tuo anno viaggia con Mercurio, protettore dei viandanti. Adesso allaccia bene le scarpe, come prima di un cammino, anche se non devi uscire. Ripeti a mente «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia» e tieni la porta di casa più aperta agli incontri imprevisti.',
    'inni_orfici|Mercurio|Fortuna|giorno': 'Mercurio, signore dei crocevia e degli incontri casuali, regge la giornata di oggi. Scegli una strada diversa dal solito per un breve tratto. Mentre cammini, ripeti a mente «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia» e fai caso alle occasioni che ti chiamano da vicino.',
    'inni_orfici|Mercurio|Fortuna|mese': 'Oggi, mercoledì di Mercurio, amico dei passanti, prende forma un mese di incontri. Ogni mercoledì, per trenta giorni, scambia qualche parola con una persona che saluti soltanto. Ripeti a mente «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia» prima di avvicinarti: spesso la buona sorte passa dagli altri.',
    'inni_orfici|Mercurio|Fortuna|settimana': 'Questa settimana nasce oggi nel mercoledì di Mercurio, quando le occasioni viaggiano veloci come i messaggi. Lascia sul tavolo d\'ingresso un foglietto con una domanda aperta. Sussurra tre volte «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia», poi lascia che questi giorni suggeriscano la risposta.',
    'inni_orfici|Mercurio|Generale|anno': 'Il tuo anno è nato di mercoledì, dal compleanno, sotto Mercurio che fa da ponte fra le cose. Adesso prendi un libro dallo scaffale senza scegliere, aprilo a caso e leggi la prima riga. Mormora «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia» e tieni quella riga come compagna.',
    'inni_orfici|Mercurio|Generale|giorno': 'Oggi è il giorno di Mercurio, il messaggero che collega le cose. Apri una finestra per far passare l\'aria e resta lì qualche respiro. Recita a voce bassa «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia» due volte, poi lascia che i pensieri circolino come l\'aria.',
    'inni_orfici|Mercurio|Generale|mese': 'Trenta giorni di scambi partono oggi, mercoledì, sotto Mercurio dai piedi alati. Pensa a tre persone a cui devi una parola da tempo. Recita a mezza voce «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia», poi fai subito la prima telefonata e le altre due entro il mercoledì seguente.',
    'inni_orfici|Mercurio|Generale|settimana': 'La settimana si apre oggi, mercoledì, nel giorno di Mercurio, dio delle strade e degli scambi. Tocca con la mano la soglia di casa, dove passano tutte le partenze. Ripeti tre volte «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia», poi scegli tre cose da dire in questi sette giorni.',
    'inni_orfici|Saturno|Amore|anno': 'Saturno custodisce il tuo anno dal compleanno: negli affetti conta ciò che resiste. Adesso tieni un oggetto che ti ricorda chi ami o, se sei senza legame, una persona fedele. Sussurra «Sempre fiorente, padre degli dèi beati e degli uomini» e ringrazia per ciò che il tempo ha risparmiato.',
    'inni_orfici|Saturno|Amore|giorno': 'Saturno, che tiene insieme ciò che dura, regge questa giornata. Chiama o scrivi a chi ami o, se sei senza legame, a un\'amicizia antica che ti sostiene. Prima di farlo sussurra «Sempre fiorente, padre degli dèi beati e degli uomini» e ringrazia in silenzio per la fedeltà di quel legame.',
    'inni_orfici|Saturno|Amore|mese': 'Saturno, che fa crescere piano le radici, porta oggi un mese in cui gli affetti si rafforzano. Scegli una pianta e curala ogni sabato per trenta giorni, pensando a chi ami o a chi desideri incontrare. Sussurra «Sempre fiorente, padre degli dèi beati e degli uomini» mentre la annaffi.',
    'inni_orfici|Saturno|Amore|settimana': 'Da oggi, sabato, Saturno guida sette giorni che invitano gli affetti alla pazienza. Guarda una fotografia di chi ami o di una persona cara, se sei senza legame. A mente ripeti due volte «Sempre fiorente, padre degli dèi beati e degli uomini» e lascia che il ricordo diventi gratitudine.',
    'inni_orfici|Saturno|Carriera|anno': 'Il compleanno ha consegnato il tuo anno a Saturno, costruttore paziente: nel lavoro conta la solidità. Adesso impila con cura tre libri, il più grande sotto. Pronuncia «Sempre fiorente, padre degli dèi beati e degli uomini» guardando la pila, poi compi un\'azione semplice che regge il resto.',
    'inni_orfici|Saturno|Carriera|giorno': 'Nel giorno di Saturno, maestro della misura, il lavoro chiede lentezza e precisione. Prima di cominciare metti in ordine un cassetto o una cartella. Pronuncia sottovoce «Sempre fiorente, padre degli dèi beati e degli uomini», poi porta a termine un compito lasciato a metà.',
    'inni_orfici|Saturno|Carriera|mese': 'Con il sabato di Saturno, pianeta delle opere che durano, nasce oggi un mese di lavoro paziente. Scegli il compito più lungo che hai e dividilo in quattro tappe, una per ogni sabato. Pronuncia sottovoce «Sempre fiorente, padre degli dèi beati e degli uomini», poi completa subito la prima tappa.',
    'inni_orfici|Saturno|Carriera|settimana': 'Comincia oggi, sabato, una settimana di Saturno in cui il lavoro chiede fondamenta solide. Su un foglio traccia una linea retta e scrivi sopra il traguardo dei sette giorni. Recita tre volte «Sempre fiorente, padre degli dèi beati e degli uomini» e procedi un passo alla volta.',
    'inni_orfici|Saturno|Fortuna|anno': 'Dal compleanno Saturno, antico dio del raccolto, accompagna il tuo anno: le occasioni vengono a chi sa attendere. Adesso pianta un seme o un nocciolo in un vaso di terra. Ripeti a voce bassa «Sempre fiorente, padre degli dèi beati e degli uomini», poi lascia andare una fretta inutile.',
    'inni_orfici|Saturno|Fortuna|giorno': 'Sotto Saturno, oggi, le occasioni maturano con lentezza. Tocca il tronco di un albero o un muro antico, se ne trovi uno vicino. Ripeti a voce bassa «Sempre fiorente, padre degli dèi beati e degli uomini» e accogli ciò che arriva al momento giusto.',
    'inni_orfici|Saturno|Fortuna|mese': 'Oggi, sabato di Saturno, si avvia un mese in cui la buona sorte prende tempo. Prendi un sasso liscio e tienilo sul comodino. Ripeti a voce bassa «Sempre fiorente, padre degli dèi beati e degli uomini» e ogni sabato, per trenta giorni, ricorda un\'occasione arrivata col tempo.',
    'inni_orfici|Saturno|Fortuna|settimana': 'Questa settimana nasce oggi, nel sabato di Saturno, guardiano delle soglie. Fai tre nodi lenti su un filo scuro e tienilo con te. Sussurra «Sempre fiorente, padre degli dèi beati e degli uomini» e ricorda che le occasioni migliori spesso chiedono attesa.',
    'inni_orfici|Saturno|Generale|anno': 'Il tempo di Saturno guida il tuo anno, nato al compleanno in un sabato: chiede di non correre. Adesso osserva un orologio, seguendo la lancetta in silenzio. Recita con calma «Sempre fiorente, padre degli dèi beati e degli uomini», poi scegli una cosa da costruire con pazienza lungo l\'anno.',
    'inni_orfici|Saturno|Generale|giorno': 'Oggi è il giorno di Saturno, signore del tempo lento. Spegni il telefono per qualche minuto e ascolta il silenzio della stanza. Recita lentamente «Sempre fiorente, padre degli dèi beati e degli uomini» e lascia che le ore rallentino il passo.',
    'inni_orfici|Saturno|Generale|mese': 'Il mese che si avvia oggi, sabato, porta la perseveranza di Saturno. Scegli un piccolo impegno da mantenere ogni giorno per trenta giorni e scrivilo su un foglio. Recita lentamente «Sempre fiorente, padre degli dèi beati e degli uomini», poi chiudi il foglio in una scatola e riaprila ogni sabato.',
    'inni_orfici|Saturno|Generale|settimana': 'La settimana si apre oggi, sabato, nel giorno di Saturno, che chiede costanza. Accendi una candela scura e guardala per un minuto intero. Ripeti tre volte «Sempre fiorente, padre degli dèi beati e degli uomini» e scegli una sola abitudine da custodire per sette giorni.',
    'inni_orfici|Sole|Amore|anno': 'Sotto il Sole è nato il tuo anno, dal compleanno: negli affetti chiede limpidezza e generosità. Adesso scrivi un messaggio di gratitudine a chi ami o, se sei senza legame, a una persona che ti ha aiutato. Sussurra due volte «Occhio della giustizia, luce della vita» prima di inviarlo.',
    'inni_orfici|Sole|Amore|giorno': 'Il Sole, che scalda senza chiedere niente in cambio, governa questa giornata. Porta una mano sul petto e pensa a chi ami o a chi desideri incontrare. Sussurra una volta «Occhio della giustizia, luce della vita» e lascia che quel pensiero si riscaldi in silenzio.',
    'inni_orfici|Sole|Amore|mese': 'Un mese per gli affetti nasce oggi, domenica, sotto il Sole che fa maturare i frutti. Dividi un\'arancia in spicchi e offrine metà a chi ami o, se sei senza legame, a un\'amicizia cara. Sussurra tre volte «Occhio della giustizia, luce della vita» mentre la porgi.',
    'inni_orfici|Sole|Amore|settimana': 'Da questa domenica il Sole accompagna sette giorni di affetti più caldi. Prepara una bevanda calda e tieni la tazza fra le mani, pensando alla persona del tuo cuore o, se sei senza legame, a chi vorresti accanto. Pronuncia piano «Occhio della giustizia, luce della vita» due volte.',
    'inni_orfici|Sole|Carriera|anno': 'Dal compleanno il tuo anno porta il segno del Sole, che dà nitidezza al lavoro e allo studio. Adesso accendi la lampada della scrivania anche se c\'è luce. Recita sottovoce «Occhio della giustizia, luce della vita» tre volte, poi svolgi una parte del compito che merita più attenzione.',
    'inni_orfici|Sole|Carriera|giorno': 'Nel giorno del Sole, che mette ogni cosa in piena vista, il lavoro chiede chiarezza. Prima di cominciare sgombra la scrivania e lascia sopra soltanto ciò che serve oggi. Ripeti a mente tre volte «Occhio della giustizia, luce della vita», poi affronta per primo il compito più limpido.',
    'inni_orfici|Sole|Carriera|mese': 'Da questa domenica del Sole, che porta in luce il lavoro ben fatto, partono trenta giorni di impegno e di studio. Scrivi in cima a un quaderno il risultato che vuoi rendere visibile e ripeti a mente «Occhio della giustizia, luce della vita». Ogni domenica rileggi quella riga.',
    'inni_orfici|Sole|Carriera|settimana': 'Una settimana di lavoro trasparente parte oggi, domenica, con il Sole che mostra ogni impegno per quello che è. Sul tavolo sistema un oggetto dorato o giallo, poi recita sottovoce «Occhio della giustizia, luce della vita» tre volte. Lascia l\'oggetto lì per sette giorni, come un segno.',
    'inni_orfici|Sole|Fortuna|anno': 'Il compleanno ha dato al tuo anno la luce del Sole, che svela le occasioni nascoste. Adesso cerca un\'ombra netta sul pavimento o sul muro e voltati verso il punto da cui arriva la luce. Pronuncia una volta «Occhio della giustizia, luce della vita» e guarda in quella direzione.',
    'inni_orfici|Sole|Fortuna|giorno': 'Sotto il Sole di oggi la luce rende visibili le porte aperte. Cammina qualche passo all\'aperto, guardandoti intorno con calma. Pronuncia a voce bassa «Occhio della giustizia, luce della vita» una volta sola, poi nota la prima occasione che ti viene incontro, anche minima.',
    'inni_orfici|Sole|Fortuna|mese': 'Oggi, sotto il segno del Sole, si apre un mese di occasioni da riconoscere. Metti sul davanzale un sasso chiaro raccolto da te, dove la luce lo tocchi. Pronuncia una volta «Occhio della giustizia, luce della vita»; per trenta giorni, ogni volta che lo guardi, cerca un\'occasione nuova.',
    'inni_orfici|Sole|Fortuna|settimana': 'Questa settimana nasce di domenica, oggi, nel giorno del Sole, occhio che riconosce le occasioni. Bevi adesso un bicchiere d\'acqua alla luce del giorno, poi ripeti tre volte «Occhio della giustizia, luce della vita». Per sette giorni tieni gli occhi aperti sulle opportunità che si affacciano.',
    'inni_orfici|Sole|Generale|anno': 'Il tuo anno, dal compleanno, è nato nel giorno del Sole, che dà misura e vigore. Adesso metti in un bicchiere un fiore giallo, anche di campo, dove il giorno entra più chiaro. Pronuncia tre volte «Occhio della giustizia, luce della vita» e nomina una cosa che vuoi vedere meglio.',
    'inni_orfici|Sole|Generale|giorno': 'Oggi è il giorno del Sole, l\'astro che vede ogni cosa: mettiti vicino a una finestra, con il viso verso la luce. Respira piano e recita a voce bassa, per tre volte, «Occhio della giustizia, luce della vita». Poi lascia che la giornata prenda il suo passo.',
    'inni_orfici|Sole|Generale|mese': 'Trenta giorni prendono luce da questa domenica, sotto il Sole che porta allo scoperto ciò che stava in ombra. Pulisci un vetro di casa, finché la luce passa senza macchie. Recita due volte «Occhio della giustizia, luce della vita» guardando attraverso quel vetro: lascia che lo sguardo si schiarisca.',
    'inni_orfici|Sole|Generale|settimana': 'Comincia oggi, domenica, una settimana che porta il calore del Sole. Accendi una candela gialla e guarda la fiamma finché il respiro rallenta. Ripeti a mezza voce «Occhio della giustizia, luce della vita» tre volte, poi spegnila con un soffio e scegli una cosa da tenere limpida per sette giorni.',
    'inni_orfici|Venere|Amore|anno': 'Di venerdì, nel giorno di Venere, è nato il tuo anno dal compleanno: gli affetti chiedono tenerezza. Adesso scrivi su un foglio una parola d\'amore pensando a chi ami o a chi desideri incontrare. Sussurra tre volte «Celeste, molto cantata, Afrodite amante del sorriso» e piega il foglio.',
    'inni_orfici|Venere|Amore|giorno': 'Venere, signora degli affetti, regge questa giornata. Guardati allo specchio con gentilezza, poi pensa a chi ami o a chi desideri incontrare. Sussurra «Celeste, molto cantata, Afrodite amante del sorriso» tre volte e regala un sorriso vero alla prima persona che vedi.',
    'inni_orfici|Venere|Amore|mese': 'Venere porta oggi un mese in cui gli affetti cercano dolcezza. Metti un fiore rosa in un bicchiere accanto al letto e pensa a chi ami o, se sei senza legame, all\'incontro che desideri. Sussurra «Celeste, molto cantata, Afrodite amante del sorriso» tre volte e cambia l\'acqua ogni venerdì.',
    'inni_orfici|Venere|Amore|settimana': 'Sette giorni di Venere cominciano oggi, venerdì: mettono gli affetti al centro. Scegli un nastro rosa e fai un nodo leggero. A mente ripeti «Celeste, molto cantata, Afrodite amante del sorriso» pensando alla persona amata, o a chi speri di incontrare, poi tieni il nodo con te.',
    'inni_orfici|Venere|Carriera|anno': 'Venere accompagna il tuo anno dal compleanno e chiede garbo nel lavoro e nello studio. Adesso manda un messaggio di ringraziamento a chi ti ha dato una mano, anche tempo fa. Pronuncia sottovoce «Celeste, molto cantata, Afrodite amante del sorriso», poi riprendi il lavoro con gesti più lenti.',
    'inni_orfici|Venere|Carriera|giorno': 'Nel giorno di Venere, amica di ciò che è ben fatto, anche il lavoro riesce meglio nell\'armonia. Riordina lo spazio dove lavori e aggiungi qualcosa di bello. Pronuncia sottovoce «Celeste, molto cantata, Afrodite amante del sorriso», poi rivolgi una parola cortese a un collega o a chi studia con te.',
    'inni_orfici|Venere|Carriera|mese': 'Trenta giorni di lavoro in accordo nascono oggi nel venerdì di Venere. Offri oggi un caffè o una pausa a chi lavora o studia con te: ripeti il gesto ogni venerdì. Recita sottovoce «Celeste, molto cantata, Afrodite amante del sorriso» due volte, prima di quell\'invito.',
    'inni_orfici|Venere|Carriera|settimana': 'Comincia oggi, venerdì, sotto Venere, una settimana in cui il lavoro chiede collaborazione e buon gusto. Porta sul tavolo di lavoro la tua tazza più bella e usala per ogni pausa. Recita due volte «Celeste, molto cantata, Afrodite amante del sorriso» e scegli con chi collaborare in modo più sereno.',
    'inni_orfici|Venere|Fortuna|anno': 'Il compleanno ha posto il tuo anno nel segno di Venere: le occasioni passano dalla cortesia. Adesso fai un complimento sincero a qualcuno che lo merita. Ripeti a voce bassa «Celeste, molto cantata, Afrodite amante del sorriso», poi tieni con te un piccolo oggetto rosa come promemoria.',
    'inni_orfici|Venere|Fortuna|giorno': 'Sotto Venere, oggi, le porte si aprono con la gentilezza. Indossa un colore che ti piace, anche solo in un dettaglio. Ripeti a voce bassa «Celeste, molto cantata, Afrodite amante del sorriso» e accogli con un sorriso le occasioni che arrivano dagli altri.',
    'inni_orfici|Venere|Fortuna|mese': 'Sotto Venere, che rende dolce ciò che tocca, nasce oggi un mese di occasioni gentili. Regala un piccolo dono a qualcuno, senza motivo. Ripeti a voce bassa «Celeste, molto cantata, Afrodite amante del sorriso» e per trenta giorni nota le gentilezze che tornano verso di te.',
    'inni_orfici|Venere|Fortuna|settimana': 'Questa settimana nasce oggi, nel venerdì di Venere, dea dell\'incanto. Raccogli un petalo o una foglia e mettila tra le pagine di un libro. Sussurra tre volte «Celeste, molto cantata, Afrodite amante del sorriso»; poi lascia che la grazia accompagni il tuo sguardo sulle occasioni.',
    'inni_orfici|Venere|Generale|anno': 'Venere, nata dalla spuma del mare, ha dato al tuo anno dal compleanno il segno della bellezza. Adesso cerca con lo sguardo la cosa più bella intorno a te e resta a guardarla. Recita a mezza voce «Celeste, molto cantata, Afrodite amante del sorriso» due volte, poi ringrazia in silenzio.',
    'inni_orfici|Venere|Generale|giorno': 'Oggi è il giorno di Venere, stella del mattino e della sera. Metti una musica dolce e lasciala suonare mentre fai una cosa qualunque. Recita a mezza voce «Celeste, molto cantata, Afrodite amante del sorriso» due volte e concediti un momento di bellezza senza scopo.',
    'inni_orfici|Venere|Generale|mese': 'Il mese che comincia oggi, venerdì, porta la grazia di Venere. Scegli un angolo di casa e rendilo bello con una stoffa colorata o una luce calda. Recita due volte «Celeste, molto cantata, Afrodite amante del sorriso», poi torna in quell\'angolo ogni venerdì per trenta giorni.',
    'inni_orfici|Venere|Generale|settimana': 'Oggi, venerdì, si apre nel giorno di Venere una settimana sotto il segno dell\'armonia. Profuma una stanza con un\'erba, una scorza d\'agrume o un po\' d\'incenso. Ripeti tre volte, piano, «Celeste, molto cantata, Afrodite amante del sorriso»; poi lascia aperta la porta perché il profumo circoli.',
    'mantra_navagraha|Budha|Amore|anno': 'Nato di mercoledì, il tuo anno porta dal compleanno il dono di Budha, la parola che avvicina. Rileggi adesso un messaggio affettuoso ricevuto da chi ami o, se sei senza legame, da una persona cara. Sussurra sette volte «Om Budhaya namah» e rispondi con la stessa gentilezza.',
    'mantra_navagraha|Budha|Amore|giorno': 'Budha, signore dei discorsi, governa questo mercoledì: negli affetti contano le parole scelte con cura. Pensa a una cosa non detta alla persona amata, o a chi desideri conoscere meglio. Sussurra sette volte «Om Budhaya namah», poi cerca il modo più semplice e gentile per dirla.',
    'mantra_navagraha|Budha|Amore|mese': 'Il mese che si apre oggi, di mercoledì, porta negli affetti l\'arte di Budha, che sa ascoltare oltre che parlare. Ascolta fino in fondo, senza interrompere, chi ami o, se sei senza legame, una persona cara che ha bisogno di dire qualcosa. Poi sussurra sette volte «Om Budhaya namah».',
    'mantra_navagraha|Budha|Amore|settimana': 'La settimana degli affetti, nata oggi nel giorno di Budha, invita al dialogo. Scrivi su un biglietto una domanda che vorresti fare a chi ami o a chi vorresti conoscere. A mente, ripeti nove volte «Om Budhaya namah», poi tieni il biglietto con te finché arriva il momento giusto.',
    'mantra_navagraha|Budha|Carriera|anno': 'Sotto Budha è nato il tuo anno, nel mercoledì del compleanno: un anno che nel lavoro premia la curiosità. Scegli adesso un argomento del tuo mestiere che vuoi capire meglio e scrivi a chi può spiegartelo. Pronuncia sottovoce nove volte «Om Budhaya namah» prima di mandare la domanda.',
    'mantra_navagraha|Budha|Carriera|giorno': 'Il mercoledì di Budha è adatto ai messaggi, allo studio e all\'organizzazione. Prima di lavorare, metti in ordine la scrivania e togli ciò che distrae. Pronuncia sottovoce undici volte «Om Budhaya namah» e dedica la prima ora al compito che richiede più attenzione.',
    'mantra_navagraha|Budha|Carriera|mese': 'Nel mese di lavoro che nasce oggi, mercoledì, Budha, maestro dei conti e del discernimento, chiede precisione. Rifai con calma un conto o un controllo che di solito fai di fretta. Pronuncia undici volte «Om Budhaya namah» e correggi ciò che trovi, senza giudicarti.',
    'mantra_navagraha|Budha|Carriera|settimana': 'Budha guida da oggi una settimana di lavoro fatta di idee, confronti e apprendimento. Sul calendario evidenzia in verde l\'impegno che richiede più studio. Recita nove volte «Om Budhaya namah» a voce bassa e dedica a quell\'impegno il primo momento libero.',
    'mantra_navagraha|Budha|Fortuna|anno': 'In qualunque punto dell\'anno ti trovi, Budha ne custodisce il segno: il compleanno da cui è nato cadeva di mercoledì. Innaffia adesso sul davanzale una piantina verde, il colore di Budha. Ripeti a mente sette volte «Om Budhaya namah» e lascia che le occasioni crescano con lei.',
    'mantra_navagraha|Budha|Fortuna|giorno': 'Con Budha, signore del giorno, le occasioni passano spesso per vie impreviste. Prendi un percorso diverso dal solito e guardati intorno, anche solo per un tratto. Ripeti a mente sette volte «Om Budhaya namah» e osserva con attenzione ciò che incontri e ciò che senti dire.',
    'mantra_navagraha|Budha|Fortuna|mese': 'Le occasioni del mese che nasce oggi, nel giorno di Budha, passano di mano in mano come le parole. Regala una penna o un quaderno a qualcuno a cui possono servire. Ripeti a mente nove volte «Om Budhaya namah» e annota le idee che ti arrivano.',
    'mantra_navagraha|Budha|Fortuna|settimana': 'In questi sette giorni, nati di mercoledì sotto Budha, conta la curiosità. Tieni in tasca un piccolo oggetto verde, una pietra o un bottone. Sussurra undici volte «Om Budhaya namah» toccandolo; poi fai caso alle opportunità che arrivano dalle parole degli altri.',
    'mantra_navagraha|Budha|Generale|anno': 'Budha, che rende pronta la mente, governa il mercoledì in cui è nato il tuo anno, quello del compleanno. Spiega adesso a qualcuno, con parole semplici, una cosa che hai capito di recente. Recita nove volte «Om Budhaya namah» e ascolta la domanda che ti viene fatta.',
    'mantra_navagraha|Budha|Generale|giorno': 'Oggi è il giorno di Budha, il graha dell\'intelligenza e della parola. Siediti con un quaderno aperto e una penna in mano. Recita a voce bassa nove volte «Om Budhaya namah», poi scrivi tre pensieri chiari che vuoi tenere presenti nella giornata.',
    'mantra_navagraha|Budha|Generale|mese': 'Budha, figlio della Luna e signore di questo mercoledì, dà al mese che nasce il passo della mente curiosa. Leggi ad alta voce una pagina che ti incuriosisce, scandendo bene ogni parola. Recita nove volte «Om Budhaya namah» e lascia che la voce trovi il suo ritmo.',
    'mantra_navagraha|Budha|Generale|settimana': 'Mercoledì di Budha: la settimana che nasce oggi sta sotto il segno dello studio e degli scambi. Metti una foglia verde tra le pagine di un libro che stai leggendo. Ripeti undici volte «Om Budhaya namah» e lascia la foglia lì come segnalibro della settimana.',
    'mantra_navagraha|Chandra|Amore|anno': 'Chandra custodisce l\'anno nato dal tuo compleanno, che cadde di lunedì. Metti in casa un fiore bianco, il colore della Luna, pensando a chi ami o, se sei senza legame, all\'amore che cerchi. Sussurra sette volte «Om Chandraya namah» e rinnova l\'acqua del vaso quando serve.',
    'mantra_navagraha|Chandra|Amore|giorno': 'Chandra, la Luna di questo lunedì, scioglie le parole trattenute. Prima di dormire, scrivi un messaggio di buonanotte gentile a chi ami o, se sei senza legame, a una persona cara. Sussurra sette volte «Om Chandraya namah» con dolcezza, poi mandalo.',
    'mantra_navagraha|Chandra|Amore|mese': 'Chandra, la Luna che nutre, governa il lunedì da cui nasce questo mese di affetti. La sera scalda una tazza di latte o di una bevanda chiara e bevila lentamente. Sussurra sette volte «Om Chandraya namah» per chi ami o per chi desideri incontrare, con la stessa calma.',
    'mantra_navagraha|Chandra|Amore|settimana': 'Questa settimana, nata oggi nel giorno di Chandra, chiede agli affetti tenerezza. Accendi una candela bianca e lascia che la stanza si faccia quieta. A mente, ripeti nove volte «Om Chandraya namah» pensando a chi ami o a chi vorresti accanto, poi spegni la candela con un gesto lento.',
    'mantra_navagraha|Chandra|Carriera|anno': 'Il tuo anno, nato di lunedì, porta dal compleanno il segno di Chandra. Nel lavoro di adesso, prima di una decisione, chiudi gli occhi e conta nove respiri. Pronuncia cinque volte «Om Chandraya namah» e dai spazio all\'intuizione che la Luna custodisce.',
    'mantra_navagraha|Chandra|Carriera|giorno': 'Il giorno di Chandra è adatto ad ascoltare prima di decidere. In una riunione o davanti a una scelta di lavoro, lascia parlare gli altri fino in fondo prima di rispondere. Pronuncia sottovoce cinque volte «Om Chandraya namah» e dai voce all\'intuizione prima del ragionamento.',
    'mantra_navagraha|Chandra|Carriera|mese': 'Trenta giorni di lavoro e di studio nascono oggi nel segno di Chandra, che quieta la mente. Spegni per mezz\'ora gli avvisi del telefono e lavora in silenzio a un solo compito. Pronuncia undici volte «Om Chandraya namah» e scegli un impegno da seguire con costanza paziente.',
    'mantra_navagraha|Chandra|Carriera|settimana': 'Chandra governa questo lunedì e la settimana di lavoro che nasce oggi: servono flessibilità e attenzione agli altri. Accanto al primo impegno dell\'agenda disegna una piccola luna crescente. Recita undici volte «Om Chandraya namah» a voce bassa e affronta quell\'impegno con animo quieto.',
    'mantra_navagraha|Chandra|Fortuna|anno': 'Nato nel giorno di Chandra, il tuo anno dal compleanno ha il passo della Luna. Fai adesso una breve passeggiata lenta, guardando il cielo. Ripeti a mente undici volte «Om Chandraya namah» a ogni sosta e lascia che le occasioni dell\'anno trovino la loro marea.',
    'mantra_navagraha|Chandra|Fortuna|giorno': 'Sotto Chandra le occasioni si accolgono come la marea, senza forzare. Indossa qualcosa di bianco o una perla, la gemma della Luna. Ripeti a mente nove volte «Om Chandraya namah» e lascia che ciò che deve venire trovi la sua strada.',
    'mantra_navagraha|Chandra|Fortuna|mese': 'Questo lunedì di Chandra dà vita a un mese di occasioni che vanno e vengono come le maree. Lascia un chicco di riso bianco in un piattino vicino alla finestra. Ripeti a mente nove volte «Om Chandraya namah» e accogli senza fretta ciò che arriva.',
    'mantra_navagraha|Chandra|Fortuna|settimana': 'Per sette giorni da oggi, lunedì di Chandra, la luce cresce e cala come la Luna. Tieni in tasca una conchiglia, dono del mare che la Luna muove. Sussurra sette volte «Om Chandraya namah» toccandola; ricorda che ogni fase della Luna porta con sé le sue occasioni.',
    'mantra_navagraha|Chandra|Generale|anno': 'Il tuo anno è nato, dal compleanno, nel giorno di Chandra: un anno attento all\'animo e ai suoi moti. Guarda adesso la Luna, se è in cielo, o la sua luce riflessa nell\'acqua. Recita nove volte «Om Chandraya namah» e lascia che i pensieri si posino come acqua ferma.',
    'mantra_navagraha|Chandra|Generale|giorno': 'Oggi è il giorno di Chandra, la Luna, custode della mente e dei sentimenti. La sera versa dell\'acqua fresca in una ciotola bianca. Recita a voce bassa nove volte «Om Chandraya namah», guardando la superficie che riflette la luce, poi offri l\'acqua a una pianta.',
    'mantra_navagraha|Chandra|Generale|mese': 'Il mese nasce oggi di lunedì, sotto Chandra: segue come lei un ritmo che cresce e cala. Tieni a portata di mano un quaderno e la sera annota in una riga come ti senti. Recita nove volte «Om Chandraya namah», poi rileggi quelle righe fra trenta giorni.',
    'mantra_navagraha|Chandra|Generale|settimana': 'Lunedì, giorno di Chandra: la settimana parte oggi col ritmo delle fasi lunari. Metti accanto al letto un piccolo oggetto d\'argento, il metallo della Luna. Questa sera ripeti undici volte «Om Chandraya namah» a mezza voce, poi toccalo prima di dormire, ogni sera fino alla fine della settimana.',
    'mantra_navagraha|Guru|Amore|anno': 'L\'anno nato dal tuo compleanno, di giovedì, sta sotto Guru, che dà fiducia ai legami. Annoda al polso un filo giallo pensando a chi ami o a chi desideri incontrare. Sussurra sette volte «Om Gurave namah» e porta il filo finché regge, come un pensiero buono.',
    'mantra_navagraha|Guru|Amore|giorno': 'Guru, che allarga il cuore e la pazienza, governa questo giovedì. Pensa alla persona amata o a chi desideri incontrare e ricorda una qualità che ammiri, o che cerchi. Sussurra sette volte «Om Gurave namah» e trova parole semplici per nominare quella qualità, a voce o per iscritto.',
    'mantra_navagraha|Guru|Amore|mese': 'Guru, che nutre ciò che cresce, veglia sugli affetti del mese che nasce oggi. Ogni sera, per trenta giorni, annota una gentilezza ricevuta o data. Sussurra sette volte «Om Gurave namah» pensando a chi ami o a chi desideri incontrare, poi scrivi la prima riga.',
    'mantra_navagraha|Guru|Amore|settimana': 'Generosità negli affetti: la chiede Guru alla settimana che nasce oggi, giovedì. Prepara una tazza di tè o un dolce da condividere con chi ami, o con chi vorresti conoscere meglio. A mente, ripeti nove volte «Om Gurave namah» mentre lo prepari, poi offrilo senza aspettare niente in cambio.',
    'mantra_navagraha|Guru|Carriera|anno': 'Il segno di Guru accompagna il tuo anno, nato da un compleanno di giovedì: un anno per crescere nel lavoro e nello studio. Ringrazia adesso per iscritto un insegnante o un collega che ti ha fatto crescere. Pronuncia undici volte «Om Gurave namah» prima di mandare quelle righe.',
    'mantra_navagraha|Guru|Carriera|giorno': 'Guardare lontano e chiedere consiglio: è il dono di Guru in questo giorno. Prima di lavorare, scrivi una domanda sul tuo percorso. Pronuncia sottovoce undici volte «Om Gurave namah» e porta quella domanda a una persona esperta di cui ti fidi.',
    'mantra_navagraha|Guru|Carriera|mese': 'Per il mese di lavoro e di studio che nasce oggi, Guru, maestro per eccellenza, chiede di dare ciò che si sa. Insegna a un collega o a un compagno di studio una cosa che sai fare bene. Pronuncia undici volte «Om Gurave namah» e offri quel sapere con pazienza.',
    'mantra_navagraha|Guru|Carriera|settimana': 'Questa settimana di lavoro, nata nel giorno di Guru, invita a crescere con onestà. Segna sull\'agenda un\'ora fissa per lo studio, come un appuntamento da non spostare. Recita nove volte «Om Gurave namah» a voce bassa e rispetta quell\'ora in questi sette giorni.',
    'mantra_navagraha|Guru|Fortuna|anno': 'Il tuo anno è nato di giovedì, dal compleanno, sotto Guru, il graha della fiducia. Apri adesso la porta di casa e lascia entrare per qualche momento aria e luce. Ripeti a mente sette volte «Om Gurave namah» e accogli l\'invito buono che arriva, da qualunque parte venga.',
    'mantra_navagraha|Guru|Fortuna|giorno': 'Con lo sguardo largo di Guru, signore del giorno, le occasioni si riconoscono. Esci all\'aperto e osserva per un momento il cielo più ampio che vedi. Ripeti a mente sette volte «Om Gurave namah» e accetta con fiducia un invito che ti sembra buono.',
    'mantra_navagraha|Guru|Fortuna|mese': 'Oggi è giovedì: Guru, il più grande dei graha, porta abbondanza al mese che nasce. Metti un pugno di ceci o di altri legumi gialli in una ciotola gialla, il colore di Guru. Ripeti a mente nove volte «Om Gurave namah» e aggiungine uno per ogni occasione buona che riconosci.',
    'mantra_navagraha|Guru|Fortuna|settimana': 'Il giovedì di Guru dà alla settimana che nasce il segno della crescita. Semina qualcosa in un vaso, un legume o un seme di fiore. Sussurra undici volte «Om Gurave namah» mentre lo copri di terra, poi osserva nei sette giorni le occasioni che crescono lentamente come quel seme.',
    'mantra_navagraha|Guru|Generale|anno': 'Guru governa il tuo anno: il compleanno da cui è nato era un giovedì, il giorno del graha che dona con larghezza. Fai adesso un dono, anche piccolo, a chi ne ha bisogno. Recita nove volte «Om Gurave namah» e lascia che resti un gesto discreto.',
    'mantra_navagraha|Guru|Generale|giorno': 'Oggi è il giorno di Guru, il maestro degli dèi, segno di saggezza e di larghezza. Offri un fiore giallo, il suo colore, in un punto luminoso della casa. Recita a voce bassa nove volte «Om Gurave namah» e ricorda con gratitudine chi ti ha insegnato qualcosa.',
    'mantra_navagraha|Guru|Generale|mese': 'Un mese di studio paziente nasce oggi nel giorno di Guru, che i testi chiamano anche Brihaspati, signore della preghiera. Scegli un libro che parla di ciò che vuoi capire e mettilo in vista. Recita nove volte «Om Gurave namah», poi leggine qualche pagina ogni giovedì.',
    'mantra_navagraha|Guru|Generale|settimana': 'Sotto Guru, che allarga lo sguardo, nasce oggi, giovedì, la settimana. Indossa un dettaglio giallo, una sciarpa o un fazzoletto. Ripeti undici volte «Om Gurave namah», con le mani giunte davanti al petto, poi scegli una cosa nuova da imparare in questi sette giorni.',
    'mantra_navagraha|Mangala|Amore|anno': 'Nato da un compleanno di martedì, il tuo anno sta sotto Mangala, che nell\'amore chiede ardore senza urti. Cuoci dei legumi rossi, cibo di questo graha: dividili con chi ami o, se sei senza legame, con una persona cara. Sussurra sette volte «Om Mangalaya namah» mentre li servi.',
    'mantra_navagraha|Mangala|Amore|giorno': 'Mangala governa questo martedì: la passione chiede di essere guidata con cura. Se c\'è stata tensione con la persona amata, o se sei senza legame e un desiderio ti agita, fermati un momento. Sussurra nove volte «Om Mangalaya namah» e scegli una parola che ripara, non una che ferisce.',
    'mantra_navagraha|Mangala|Amore|mese': 'Il mese degli affetti che nasce oggi porta l\'ardore di Mangala, nel suo martedì. Lega un nastro rosso alla maniglia della tua stanza. Sussurra sette volte «Om Mangalaya namah» per chi ami o per chi vorresti incontrare, poi cerca un modo coraggioso e gentile di mostrare ciò che senti.',
    'mantra_navagraha|Mangala|Amore|settimana': 'Nella settimana che nasce oggi, martedì di Mangala, il desiderio è vivo e impaziente. Offri un fiore rosso in un bicchiere d\'acqua sul davanzale. A mente, ripeti sette volte «Om Mangalaya namah» pensando a chi ami o a chi desideri incontrare; poi cambia l\'acqua finché il fiore resta fresco.',
    'mantra_navagraha|Mangala|Carriera|anno': 'Il compleanno ha fatto nascere il tuo anno nel giorno di Mangala, che nel lavoro vuole risposte nette. Scrivi o telefona adesso a chi aspetta da te una risposta che rimandi. Pronuncia undici volte «Om Mangalaya namah», poi rispondi con chiarezza e rispetto.',
    'mantra_navagraha|Mangala|Carriera|giorno': 'Mangala, signore del martedì, sostiene l\'iniziativa e il lavoro che chiede energia. Prima di cominciare, togli dalla scrivania ogni cosa che non serve e lascia solo il compito che rimandi da tempo. Pronuncia sottovoce undici volte «Om Mangalaya namah» e affrontalo senza esitare.',
    'mantra_navagraha|Mangala|Carriera|mese': 'Oggi, martedì di Mangala, il mese di lavoro nasce sotto il segno della prontezza. Tempera una matita fino a farle una punta netta, come si affila un attrezzo prima dell\'opera. Pronuncia undici volte «Om Mangalaya namah» e usala per segnare la prima azione da compiere oggi.',
    'mantra_navagraha|Mangala|Carriera|settimana': 'Mangala apre oggi la settimana di lavoro, che chiede fermezza senza durezza. Scrivi in cima all\'agenda l\'obiettivo più impegnativo di questi sette giorni. Recita nove volte «Om Mangalaya namah» a voce bassa e sottolinea il primo passo concreto che porta verso quell\'obiettivo.',
    'mantra_navagraha|Mangala|Fortuna|anno': 'Da un martedì, quello del compleanno, il tuo anno porta il vigore di Mangala. Spalanca adesso una finestra e lascia entrare l\'aria con forza. Ripeti a mente sette volte «Om Mangalaya namah» e va\' incontro alle occasioni che arrivano con lo stesso slancio dell\'aria che entra.',
    'mantra_navagraha|Mangala|Fortuna|giorno': 'Nel giorno di Mangala le occasioni chiedono un passo deciso. Esci e cammina con passo svelto per qualche minuto, respirando a fondo. Ripeti a mente sette volte «Om Mangalaya namah» e accogli senza esitare ciò che incontri lungo la strada.',
    'mantra_navagraha|Mangala|Fortuna|mese': 'Mangala, che i testi chiamano anche Angaraka, il carbone ardente, dà ardimento al mese che nasce oggi, nel suo martedì. Tieni in tasca un sassolino rosso o un pezzetto di mattone. Ripeti a mente nove volte «Om Mangalaya namah» toccandolo e rispondi con prontezza alle occasioni dei trenta giorni.',
    'mantra_navagraha|Mangala|Fortuna|settimana': 'Oggi, martedì, Mangala dà alla settimana un segno di slancio. Pianta un seme in un vaso di terra e premi bene il terriccio con le dita. Sussurra undici volte «Om Mangalaya namah» e lascia che il coraggio accompagni i tuoi passi verso le occasioni di questa settimana.',
    'mantra_navagraha|Mangala|Generale|anno': 'Il tuo anno, nato dal compleanno nel giorno di Mangala, chiede coraggio guidato. Adesso stringi forte i pugni per tre respiri, poi apri le mani. Recita nove volte «Om Mangalaya namah» a voce ferma e scegli una prova da affrontare con calma, senza rimandarla.',
    'mantra_navagraha|Mangala|Generale|giorno': 'Oggi è il giorno di Mangala, il graha del coraggio e dell\'energia. Accendi una lampada e guardane la fiamma per qualche istante. Recita a voce ferma nove volte «Om Mangalaya namah», poi scegli una cosa difficile e affrontala prima delle altre.',
    'mantra_navagraha|Mangala|Generale|mese': 'Con Mangala, figlio della Terra, signore del martedì, nasce un mese di energia da guidare. Sali una rampa di scale di buon passo e senti il cuore battere. Recita nove volte «Om Mangalaya namah» con voce ferma, poi scegli una sola battaglia che valga la pena.',
    'mantra_navagraha|Mangala|Generale|settimana': 'Martedì, giorno di Mangala: oggi parte una settimana con una forza che cerca direzione. Indossa un capo o un dettaglio rosso, il colore di questo graha guerriero. Ripeti sette volte «Om Mangalaya namah» e scegli dove spendere bene la tua energia in questi sette giorni.',
    'mantra_navagraha|Shani|Amore|anno': 'L\'anno che il compleanno ti ha dato è nato sotto Shani, che mette alla prova e consolida. Ripara adesso un oggetto caro che si è rotto, pensando a chi ami o a chi desideri incontrare. Sussurra sette volte «Om Shanaishcharaya namah»: i legami durano se qualcuno li cura.',
    'mantra_navagraha|Shani|Amore|giorno': 'Shani, che custodisce i legami capaci di durare, governa questo sabato. Ascolta con pazienza, senza interrompere, chi ami o, se sei senza legame, una persona che ti vuole bene. Sussurra sette volte «Om Shanaishcharaya namah» e rendi grazie per il tempo che ogni legame vero richiede.',
    'mantra_navagraha|Shani|Amore|mese': 'Nasce oggi, sabato, sotto Shani il lento, un mese di affetti da coltivare piano. Cucina con calma un piatto semplice e condividilo con chi ami o, se sei senza legame, con una persona cara. Sussurra sette volte «Om Shanaishcharaya namah» mentre lo prepari, senza fretta.',
    'mantra_navagraha|Shani|Amore|settimana': 'Fedeltà e calma negli affetti: le chiede Shani alla settimana nata oggi, sabato. Riguarda una fotografia di chi ami, o di un affetto se sei senza legame: nota i segni del tempo condiviso. Ripeti nove volte «Om Shanaishcharaya namah», poi scegli un gesto paziente da offrire in questi giorni.',
    'mantra_navagraha|Shani|Carriera|anno': 'Sotto Shani, nel sabato del compleanno, è nato il tuo anno di lavoro paziente. Pulisci adesso con cura uno strumento che usi ogni giorno, la tastiera, la penna o un attrezzo. Pronuncia undici volte «Om Shanaishcharaya namah» e porta avanti con costanza il compito più lungo che hai davanti.',
    'mantra_navagraha|Shani|Carriera|giorno': 'Il sabato di Shani è adatto al lavoro serio, lento e ben fatto. Prima di cominciare, riordina un cassetto o un archivio trascurato. Pronuncia sottovoce undici volte «Om Shanaishcharaya namah» e porta a termine un compito che aspetta da tempo.',
    'mantra_navagraha|Shani|Carriera|mese': 'Shani governa il sabato da cui nasce questo mese di lavoro lento e solido. Scegli un progetto lungo e dividilo in quattro passi, uno per settimana. Pronuncia undici volte «Om Shanaishcharaya namah» e compi oggi il primo, con cura e senza fretta.',
    'mantra_navagraha|Shani|Carriera|settimana': 'Per la settimana di lavoro che nasce oggi Shani chiede fondamenta e perseveranza. Fissa un orario per metterti al lavoro e rispettalo ogni giorno, per sette giorni. Recita nove volte «Om Shanaishcharaya namah» a voce bassa, ogni volta che arriva l\'orario scelto.',
    'mantra_navagraha|Shani|Fortuna|anno': 'Da un sabato, quello del tuo compleanno, l\'anno porta il segno di Shani, che ricompensa chi serve. Offri adesso un aiuto concreto a una persona anziana o a chi ne ha bisogno. Ripeti a mente sette volte «Om Shanaishcharaya namah» e lascia crescere le occasioni con il loro passo.',
    'mantra_navagraha|Shani|Fortuna|giorno': 'Shani, signore del sabato, insegna che le occasioni chiedono attesa e attenzione. Offri qualche seme di sesamo nero agli uccelli, come vuole l\'usanza. Ripeti a mente sette volte «Om Shanaishcharaya namah» e lascia maturare ciò che ha bisogno di tempo.',
    'mantra_navagraha|Shani|Fortuna|mese': 'Nel mese che nasce oggi, sabato, Shani chiede di saper aspettare. Metti un sasso scuro sul davanzale e lascialo lì per i trenta giorni. Ripeti a mente nove volte «Om Shanaishcharaya namah» toccandolo e accogli con pazienza le occasioni che chiedono tempo.',
    'mantra_navagraha|Shani|Fortuna|settimana': 'Sette giorni sotto Shani, da questo sabato: le occasioni crescono piano. Tieni in tasca un piccolo oggetto di ferro, una chiave o un chiodo: il ferro è il metallo di Shani. Sussurra undici volte «Om Shanaishcharaya namah» stringendolo nel palmo; le occasioni più solide hanno bisogno di pazienza.',
    'mantra_navagraha|Shani|Generale|anno': 'Il tuo anno, nato da un compleanno di sabato, porta il segno di Shani, figlio del Sole e signore del tempo. Rinuncia adesso, per un giorno, a un piccolo piacere superfluo, come nei digiuni del sabato. Recita lentamente nove volte «Om Shanaishcharaya namah» e procedi senza fretta.',
    'mantra_navagraha|Shani|Generale|giorno': 'Oggi è il giorno di Shani, il graha del tempo, della disciplina e della pazienza. Accendi una lampada a olio o una candela scura al calare del sole. Recita lentamente nove volte «Om Shanaishcharaya namah» e lascia andare una fretta che non ti serve.',
    'mantra_navagraha|Shani|Generale|mese': 'Un mese di lavoro su di te nasce oggi, sabato, nel giorno di Shani, che premia la perseveranza. Scegli un\'abitudine piccola e utile da tenere per trenta giorni e scrivila su un foglio. Recita nove volte «Om Shanaishcharaya namah», poi fai oggi la prima croce accanto al suo nome.',
    'mantra_navagraha|Shani|Generale|settimana': 'Sabato, giorno di Shani: la settimana che nasce oggi chiede costanza più che slancio. Cammina per qualche minuto senza meta, col passo di Shanaishchara, colui che avanza piano. Ripeti undici volte «Om Shanaishcharaya namah» a voce bassa, una volta ogni pochi passi.',
    'mantra_navagraha|Shukra|Amore|anno': 'Shukra, che fa fiorire i legami, governa l\'anno nato dal tuo compleanno di venerdì. Scrivi su un biglietto rosa il nome di chi ami, o il desiderio di un incontro se sei senza legame. Sussurra sette volte «Om Shukraya namah» e conserva il biglietto in una scatolina cara.',
    'mantra_navagraha|Shukra|Amore|giorno': 'Shukra, signore degli affetti e del piacere di stare insieme, governa questo venerdì. Pensa con un sorriso alla persona amata o a chi desideri accanto, poi concediti un bagno caldo o un momento tutto per te. Sussurra sette volte «Om Shukraya namah»: chi si tratta con cura sa offrirne.',
    'mantra_navagraha|Shukra|Amore|mese': 'Shukra, che governa questo venerdì, porta tenerezza al mese degli affetti. Prepara un dolce bianco come il riso cotto nel latte, offerta cara a Shukra: condividilo con chi ami o, se sei senza legame, con una persona cara. Sussurra sette volte «Om Shukraya namah» mentre lo servi.',
    'mantra_navagraha|Shukra|Amore|settimana': 'Venerdì di Shukra: per sette giorni gli affetti stanno nella luce della dolcezza. Annoda un filo bianco o rosa intorno al polso, senza stringere. A mente, ripeti nove volte «Om Shukraya namah» pensando a chi ami o a chi vorresti incontrare; poi porta il filo con te.',
    'mantra_navagraha|Shukra|Carriera|anno': 'Dal venerdì del compleanno il tuo anno porta, anche nel lavoro, il gusto del bello che viene da Shukra. Metti sulla scrivania un oggetto bello, scelto con cura. Pronuncia undici volte «Om Shukraya namah» e rendi più gentile una collaborazione difficile, con una parola o un gesto.',
    'mantra_navagraha|Shukra|Carriera|giorno': 'Nel lavoro, il venerdì di Shukra insegna che la gentilezza apre più porte della fretta. Fai a un collega o a un compagno di studio un complimento sincero sul suo lavoro. Pronuncia sottovoce undici volte «Om Shukraya namah» prima di parlare, poi scegli parole cortesi.',
    'mantra_navagraha|Shukra|Carriera|mese': 'Collaborare con grazia: è il compito che Shukra dà al mese di lavoro nato oggi. Scegli chi lavora o studia accanto a te e offrigli un aiuto concreto. Pronuncia undici volte «Om Shukraya namah» e coltiva quella collaborazione nei trenta giorni da oggi.',
    'mantra_navagraha|Shukra|Carriera|settimana': 'La settimana di lavoro nata oggi nel giorno di Shukra chiede armonia, creatività e buone relazioni. Dedica dieci minuti a disegnare o a scrivere liberamente un\'idea rimasta in disparte. Recita nove volte «Om Shukraya namah» a voce bassa prima di prendere in mano la matita.',
    'mantra_navagraha|Shukra|Fortuna|anno': 'Nel segno di Shukra, il graha degli incontri, è nato il tuo anno, dal compleanno di venerdì. Saluta adesso con un sorriso la prima persona che incontri. Ripeti a mente sette volte «Om Shukraya namah» e accogli gli incontri che arrivano: spesso portano con sé le occasioni.',
    'mantra_navagraha|Shukra|Fortuna|giorno': 'Gli incontri, nel giorno di Shukra, portano spesso le occasioni. Indossa qualcosa che ti fa sentire a tuo agio, anche un solo dettaglio. Ripeti a mente sette volte «Om Shukraya namah» e accogli con gentilezza chi oggi ti viene incontro per strada.',
    'mantra_navagraha|Shukra|Fortuna|mese': 'Oggi nasce un mese di incontri, nel giorno di Shukra. Pulisci la soglia di casa e rendila accogliente, con un tappeto o una pianta. Ripeti a mente nove volte «Om Shukraya namah» e accogli con cortesia le persone che bussano nei trenta giorni da oggi.',
    'mantra_navagraha|Shukra|Fortuna|settimana': 'Armonia per sette giorni: è il segno di Shukra su questo venerdì. Lucida un piccolo gioiello o un oggetto che brilla e portalo con te. Sussurra undici volte «Om Shukraya namah» mentre lo strofini, poi lascia spazio alle occasioni che arrivano con grazia.',
    'mantra_navagraha|Shukra|Generale|anno': 'Il tuo anno ha il volto di Shukra, il luminoso: è nato, dal compleanno, di venerdì. Ascolta adesso un brano che ami, dalla prima all\'ultima nota, senza fare nient\'altro. Recita nove volte «Om Shukraya namah» e lascia che quell\'armonia ti accompagni fino a sera.',
    'mantra_navagraha|Shukra|Generale|giorno': 'Oggi è il giorno di Shukra, il graha della bellezza e dell\'armonia. Profuma la stanza con un po\' d\'incenso o con un\'essenza delicata. Recita a voce bassa nove volte «Om Shukraya namah» e concediti un momento di quiete dentro quel profumo, senza fare altro.',
    'mantra_navagraha|Shukra|Generale|mese': 'Trenta giorni di bellezza da coltivare: oggi è venerdì, giorno di Shukra. Scegli un angolo della casa e rendilo più bello con un oggetto o un colore. Recita nove volte «Om Shukraya namah» e tieni curato quell\'angolo per tutto il mese, come un piccolo altare della bellezza.',
    'mantra_navagraha|Shukra|Generale|settimana': 'Shukra, con la sua grazia, governa questo venerdì e la settimana che nasce oggi. Metti un fiore bianco in un vaso nel punto più luminoso della casa. Ripeti undici volte «Om Shukraya namah» guardandolo; poi cambia l\'acqua ogni mattina finché resta fresco.',
    'mantra_navagraha|Surya|Amore|anno': 'Il compleanno ha dato al tuo anno il calore di Surya, che scalda chiunque gli stia accanto. Indossa adesso qualcosa di rosso o color oro e porta alla mente chi ami o chi desideri incontrare. Sussurra sette volte «Om Suryaya namah» per gli affetti che l\'anno custodisce.',
    'mantra_navagraha|Surya|Amore|giorno': 'Surya, che illumina senza distinzione, governa questo giorno. Siediti alla luce e porta alla mente la persona amata o chi desideri incontrare. Sussurra sette volte «Om Suryaya namah» e immagina quella luce posarsi anche su quel volto, vicino o ancora sconosciuto, con lo stesso calore.',
    'mantra_navagraha|Surya|Amore|mese': 'Per i trenta giorni che si aprono oggi, domenica di Surya, gli affetti cercano calore e sincerità. Sbuccia un\'arancia e dividila con chi ami o, se sei senza legame, con una persona cara. Recita sette volte «Om Suryaya namah» mentre la offri: la luce, come il frutto, si condivide.',
    'mantra_navagraha|Surya|Amore|settimana': 'Gli affetti della settimana che nasce oggi, domenica, ricevono da Surya il calore della luce. Offri un fiore rosso o arancione, i colori del Sole, su un tavolo illuminato. A mente, ripeti nove volte «Om Suryaya namah» pensando a chi ami o a chi vorresti accanto.',
    'mantra_navagraha|Surya|Carriera|anno': 'Nel giorno di Surya è nato il tuo anno, dal compleanno: un anno che nel lavoro vuole lealtà e luce. Scrivi adesso a chi lavora o studia con te un riconoscimento sincero per un suo merito. Pronuncia sottovoce undici volte «Om Suryaya namah» e mandalo con semplicità.',
    'mantra_navagraha|Surya|Carriera|giorno': 'Nel giorno di Surya ogni compito trova il suo posto nella luce. Prima di lavorare, siediti con la schiena dritta e fai tre respiri lenti e profondi. Pronuncia sottovoce undici volte «Om Suryaya namah», poi affronta il compito che richiede più chiarezza.',
    'mantra_navagraha|Surya|Carriera|mese': 'Surya, che governa questa domenica, dà il tono al mese di lavoro e di studio che nasce oggi. Scrivi su un foglio l\'obiettivo dei trenta giorni e appendilo in un punto luminoso. Pronuncia nove volte «Om Suryaya namah», poi rileggilo ogni mattina prima di cominciare.',
    'mantra_navagraha|Surya|Carriera|settimana': 'Da oggi, domenica, la settimana di lavoro sta sotto Surya, che chiede dignità e decoro. Riordina la scrivania e lascia sgombro il punto dove batte la luce. Recita nove volte «Om Suryaya namah» a voce bassa, poi posa lì soltanto il lavoro di questi sette giorni.',
    'mantra_navagraha|Surya|Fortuna|anno': 'Il compleanno da cui è nato il tuo anno cadeva di domenica, giorno di Surya, la luce che svela. Pulisci adesso un vetro o uno specchio finché riflette bene il giorno. Ripeti a mente nove volte «Om Suryaya namah» e tieni gli occhi aperti alle occasioni che la luce scopre.',
    'mantra_navagraha|Surya|Fortuna|giorno': 'La luce di Surya, signore di questo giorno, mostra ciò che era in ombra. Esci all\'aperto e fai qualche passo verso oriente. Ripeti a mente sette volte «Om Suryaya namah» e accogli con occhi limpidi le occasioni che si mostrano lungo la strada.',
    'mantra_navagraha|Surya|Fortuna|mese': 'Oggi è domenica e il mese che nasce sta sotto la luce di Surya. Prendi un piccolo oggetto dorato, un anello o un bottone: tienilo con te. Ripeti a mente dodici volte «Om Suryaya namah» toccandolo, poi lascia che ti ricordi di guardare le occasioni in piena luce.',
    'mantra_navagraha|Surya|Fortuna|settimana': 'Surya, il Sole che sorge, governa questa domenica e i sette giorni che nascono con lei. Metti qualche chicco di grano in una ciotola alla luce, come nelle offerte al Sole. Sussurra undici volte «Om Suryaya namah» e in questi giorni tieni lo sguardo aperto alle opportunità.',
    'mantra_navagraha|Surya|Generale|anno': 'Il tuo anno, dal compleanno, è nato di domenica, sotto Surya, sorgente del calore e della vita. Rivolgiti adesso verso il sole e inchinati a mani giunte, come nel saluto tradizionale. Recita nove volte «Om Suryaya namah» e ringrazia per un giorno luminoso già vissuto.',
    'mantra_navagraha|Surya|Generale|giorno': 'Oggi è il giorno di Surya, il Sole che rischiara ogni cosa. Versa un filo d\'acqua da un bicchiere guardando la luce: è l\'arghya, l\'offerta d\'acqua al sole della tradizione. Recita a voce bassa nove volte «Om Suryaya namah» e porta quella luce nel resto della giornata.',
    'mantra_navagraha|Surya|Generale|mese': 'Il mese che nasce oggi porta il segno di Surya, il re dei nove graha: è domenica, il giorno del Sole. Apri le finestre di una stanza rimasta in ombra e lascia entrare il giorno. Recita undici volte «Om Suryaya namah» mentre la luce riempie lo spazio.',
    'mantra_navagraha|Surya|Generale|settimana': 'La settimana nasce oggi, domenica, nel giorno di Surya, che la mette sotto la sua luce. Accendi una piccola lampada o una candela verso oriente. Ripeti dodici volte «Om Suryaya namah», con calma, a voce bassa, poi lascia la fiamma accesa per qualche minuto e guardala.',
    'salmi_martini|10|Aladiah': 'Quando un vecchio errore torna a pesare, leggi a voce «Sia sopra di noi, o Signore, la tua misericordia, conforme noi in te abbiamo sperato». Fallo tre volte ricordando quello che è successo senza cancellarlo. Lascia che smetta di dire chi sei. Ricominciare è un gesto piccolo.',
    'salmi_martini|11|Lauviah': 'Pensa a un progetto lungo che stai portando avanti. Leggi in piedi «Viva il Signore, e diasi benedizione al mio Dio, e sia glorificato il Dio di mia salute». Due letture bastano, con voce piena. Chiediti che cosa ti fa continuare quando l\'entusiasmo dei primi giorni è passato.',
    'salmi_martini|12|Hahaiah': 'La sera, prima di dormire, leggi sottovoce «E perchè, o Signore, ti se\' ritirato in lontananza, ci hai negletti nel maggior uopo, nella tribolazione?». Ripetilo due volte e poi resta in silenzio al buio. Se nella notte arriva un sogno o un\'intuizione, accoglilo senza pretendere spiegazioni.',
    'salmi_martini|13|Iezalel': 'Pensa alle persone che tieni insieme. Leggi con voce piena «Canti con giubbilo laude a Dio tutta quanta la terra: cantate ed esultate al suono de\' musicali strumenti». Tre volte, anche cantando se ti viene. Ricorda un nome che altri dimenticano. Fedeltà qui vuol dire memoria viva.',
    'salmi_martini|14|Mebahel': 'Quando devi dire una cosa scomoda, leggi prima «E il Signore è stato rifugio al povero, aiutatore al tempo opportuno, nella tribolazione». Pronuncialo due volte senza alzare il tono. Chiediti se la verità che porti protegge qualcuno senza diventare un\'arma. Applica la stessa misura prima di tutto a te.',
    'salmi_martini|15|Hariel': 'Riordina il tavolo o la stanza dove lavori. Poi leggi a voce «Ma il Signore è stato mio rifugio, e il mio Dio il sostegno di mia speranza». Ripetilo tre volte mentre guardi lo spazio che hai sistemato. Lascia che le idee prendano ordine come le cose intorno a te.',
    'salmi_martini|16|Hakamiah': 'Nel momento in cui vorresti sparire da una situazione difficile, leggi «Signore Dio di mia salute, di giorno e di notte alzai le mie grida dinanzi a te». Dillo due volte restando al tuo posto per tutto il tempo della lettura. Poi parla chiaro, anche se la franchezza costa qualcosa.',
    'salmi_martini|17|Lauviah II': 'Quando un\'intuizione arriva di notte, leggi «Signore, Signor nostro, quanto ammirabile è il nome tuo per tutta quanta la terra! Perocchè la tua maestà è elevata fin sopra dei cieli». Una volta sola basta. Poi annota l\'intuizione su un foglio e trattala come un dato da verificare.',
    'salmi_martini|18|Caliel': 'Prima di prendere posizione su una questione, leggi «Il Signore fa giudizio dei popoli. Fammi ragione, o Signore, secondo la mia giustizia, e secondo l\'innocenza che è in me». Ripetilo due volte con la voce bassa. Separa il fatto dall\'opinione. Poi decidi senza bisogno di alzare il tono.',
    'salmi_martini|19|Leuviah': 'Ripensa a una questione rimasta aperta nel tuo passato. Leggi con calma «Aspettai ansiosamente il Signore, ed egli a me si rivolse». Ripetilo tre volte lasciando fra una lettura e l\'altra il tempo di un respiro. Ricorda per capire. Non serve rinfacciare niente a nessuno.',
    'salmi_martini|1|Vehuiah': 'Al mattino, prima di cominciare, leggi a voce «Tu però, o Signore, tu se\' mio scudo, mia gloria, e tu rinnalzi il mio capo». Ripetilo tre volte pensando a una cosa che rimandi da tempo. Il versetto non sceglie al posto tuo: accompagna il primo passo.',
    'salmi_martini|20|Pahaliah': 'Pensa a un\'abitudine che ti blocca da tempo. Leggi con voce chiara «Signore, libera l\'anima mia dalle labbra inique e dalla lingua ingannatrice». Ripeti il versetto tre volte. Decidi una sola cosa che consideri non negoziabile. Cambiare direzione è una scelta da rinnovare ogni giorno.',
    'salmi_martini|21|Nelchael': 'Apri il libro o il quaderno che stai studiando. Prima di leggere, pronuncia «Io però in te sperai, o Signore; io dissi: Tu se\' il mio Dio». Dillo due volte e accetta di non capire subito. Il sapere serve a costruire qualcosa, non ad avere ragione.',
    'salmi_martini|22|Ieiaiel': 'Prima di presentare un lavoro agli altri, fermati e leggi «Il Signore ti custodisce: il Signore è tua difesa al tuo destro fianco». Tre letture, lente. Chiediti se ciò che consegni regge nel tempo. L\'applauso conta meno della solidità di quello che fai.',
    'salmi_martini|23|Melahel': 'Mentre annaffi una pianta o versi un bicchiere d\'acqua, leggi «Il Signore ti custodisca all\'entrare e all\'uscire, da questo punto, e per sempre». Ripetilo ogni sera per una settimana. La costanza di questo gesto piccolo vale più di un gesto grande fatto una volta.',
    'salmi_martini|24|Haheuiah': 'Pensa a chi oggi si sente fuori posto, anche a te. Leggi «Ecco gli occhi del Signore sopra coloro che lo temono, e sopra coloro, che confidano nella sua misericordia». Ripetilo due volte tenendo in mente quella persona. Stai accanto a quella condizione con fermezza più che con pietà.',
    'salmi_martini|25|Nithhaiah': 'Concediti qualche minuto di silenzio prima di parlare. Poi leggi «Te io loderò o Signore, con tutto il mio cuore: racconterò tutte le tue meraviglie». Ripetilo tre volte e torna al silenzio. Le intuizioni arrivano spesso quando smetti di cercarle. Lascia che la parola venga dopo.',
    'salmi_martini|26|Haaiah': 'Prima di un confronto in cui le posizioni si irrigidiscono, leggi «Gridai con tutto il mio cuore: esaudiscimi, o Signore: fa\' ch\'io cerchi le tue giustificazioni». Ripetilo due volte cercando dentro di te il punto di incontro. Pensa alla cosa giusta da dire senza alzare la voce.',
    'salmi_martini|27|Ierathel': 'Quando senti una pressione ingiusta su di te o su qualcuno che stimi, leggi a voce ferma «Liberami, o Signore, dall\'uomo cattivo: liberami dall\'uomo iniquo». Ripetilo tre volte. Chiediti dove puoi portare chiarezza. Usa la fermezza per difendere chi ne ha bisogno. Mai per colpire.',
    'salmi_martini|28|Seheiah': 'Prima di una decisione presa di corsa, rallenta e leggi «Non ti dilungare, o Dio, da me; Dio mio, volgiti ad aiutarmi». Dillo tre volte con un respiro lungo fra le letture. Guarda la strada davanti a te. Scegli un passo che puoi sostenere.',
    'salmi_martini|29|Reiiel': 'Pensa a una credenza ricevuta che ormai ti sta stretta. Leggi piano «Ecco però, che Dio mi aiuta, e il Signore ha presa a difendere la mia vita». Ripetilo due volte, poi lascia andare un legame che trattiene, senza rancore verso chi te l\'ha dato.',
    'salmi_martini|2|Ieliel': 'Trova un momento di quiete e pronuncia «Signore, non allontanar da me il tuo soccorso; accorri in mia difesa». Dillo due volte pensando a un legame che ti sta a cuore. Chiediti che cosa lo tiene insieme dopo un disaccordo. Lascia un silenzio prima di tornare alle tue cose.',
    'salmi_martini|30|Omael': 'Nei giorni in cui nulla sembra muoversi, leggi piano «Imperocchè tu se\', o Signore, la mia aspettazione: Signore, tu mia speranza fin dalla mia gioventù». Ripetilo tre volte senza forzare il raccolto. Pensa a come preparare il terreno per ciò che matura lentamente.',
    'salmi_martini|31|Lecabel': 'Prima di un lavoro di precisione, leggi «Perchè io non ho cognizione di lettere m\'internerò nella possanza del Signore; della sola giustizia tua, o Signore, io mi ricorderò». Basta una lettura lenta. Poi guarda il dettaglio senza perdere l\'insieme del progetto.',
    'salmi_martini|32|Vasariah': 'Quando stai per giudicare qualcuno, leggi «Perocchè diritta ell\'è la parola del Signore, e tutte le opere di lui sono nella fedeltà». Dillo due volte prima di aprire bocca. Separa l\'errore dalla persona che l\'ha commesso. Misura con calma prima di pronunciarti.',
    'salmi_martini|33|Iehuiah': 'Prima di entrare al lavoro o in una riunione, leggi in silenzio e poi a voce «Il Signore conosce i pensieri degli uomini, e come son vani». Due letture bastano. Distingui il ruolo dalla persona che lo occupa. Tieni la promessa che hai fatto anche quando costa.',
    'salmi_martini|34|Lehahiah': 'Quando senti salire la collera, fermati. Respira tre volte e leggi «Nel Signore speri Israele da questo punto, e pei secoli». Ripetilo finché la voce torna piana. La calma che cerchi non è debolezza: è una forza che sceglie di non esplodere. Riprendi poi la conversazione.',
    'salmi_martini|35|Chavakhiah': 'Pensa a una persona di famiglia con cui il filo si è spezzato. Leggi a mezza voce «Ho amato, perchè esaudirà il Signore la voce della mia orazione». Ripetilo tre volte e chiediti quale primo passo è possibile. Scegliere il legame non significa dare ragione all\'altro.',
    'salmi_martini|36|Menadel': 'All\'inizio della giornata di lavoro, leggi «Signore, io ho amato lo splendore della tua casa, e il luogo dove abita la tua gloria». Ripetilo due volte guardando il luogo dove ti trovi. Chiediti che cosa ha ancora da insegnarti il posto che occupi oggi.',
    'salmi_martini|37|Aniel': 'Quando ti accorgi di girare intorno alla stessa cosa, leggi «Dio degli eserciti, convertici, e mostraci la tua faccia, e sarem salvi». Ripetilo tre volte e dai un nome al cerchio che si ripete. Poi decidi con lucidità il primo gesto per uscirne.',
    'salmi_martini|38|Haamiah': 'Scegli un\'ora fissa del giorno per questo gesto. Leggi «(E dirai): Tu se\', o Signore, la mia speranza: e che per tuo rifugio hai scelto l\'Altissimo». Ripetilo tre volte alla stessa ora per alcuni giorni. Il rito non serve a ottenere: ricorda chi sei mentre lo compi.',
    'salmi_martini|39|Rehael': 'Pensa a un genitore o a un figlio. Leggi a voce «Il Signore mi udì, ed ebbe pietà di me: il Signore si fe\' mio aiuto». Ripetilo due volte con quel volto davanti agli occhi. Prova a guardare quella persona senza il conto aperto degli anni passati.',
    'salmi_martini|3|Sitael': 'Richiama alla mente una promessa che hai fatto. Leggi a voce «Egli dirà al Signore: Mio difensore sei tu, e mio asilo: egli è il mio Dio, in lui spererò». Fallo tre volte. Guarda quanto tempo vuoi ancora dare a quella parola, anche ora che costa di più.',
    'salmi_martini|40|Ieiazel': 'Quando qualcuno accanto a te attraversa la tristezza, leggi per te «E perchè, o Signore, rigetti tu la mia orazione, e rivolgi da me la tua faccia?». Una lettura sola, a bassa voce. Poi resta accanto senza spiegare. Il dolore chiede presenza, non fretta.',
    'salmi_martini|41|Hahahel': 'Prima di parlare in pubblico o di insegnare, leggi «Signore, libera l\'anima mia dalle labbra inique e dalla lingua ingannatrice». Ripetilo due volte con lentezza. Chiediti se quello che dici corrisponde a quello che fai quando nessuno guarda. La fiducia degli altri resta nelle tue mani.',
    'salmi_martini|42|Mikael': 'Prima di una trattativa o di un viaggio, leggi con voce tranquilla «Il Signore ti custodisce da ogni male: custodisca il Signore l\'anima tua». Ripetilo tre volte mettendo ordine nei pensieri. Guarda le cose come stanno prima di prendere posizione. La responsabilità resta tua.',
    'salmi_martini|43|Veualiah': 'Al mattino, davanti a un compito da portare a termine, leggi «Ma io alzai a te le grida, o Signore, e la mia orazione al mattino ti preverrà». Due volte, poi scrivi il prossimo passo verificabile. La disciplina conta più dell\'entusiasmo.',
    'salmi_martini|44|Ielahiah': 'Quando mantenere la parola data costa, leggi «Sien graditi a te, o Signore, i volontari sacrifizi della mia bocca: e insegnami i tuoi giudizi». Ripetilo due volte ricordando che cosa hai promesso e a chi. Chiediti come restare coerente anche sotto pressione.',
    'salmi_martini|45|Sealiah': 'Dopo una caduta, anche piccola, leggi «Se io diceva a te: il mio piede vacilla; la tua misericordia, o Signore, veniva in mio soccorso». Ripetilo tre volte con calma. Rimetti in moto una sola cosa che si era fermata. Non pretendere che accada tutto subito.',
    'salmi_martini|46|Ariel': 'Prima di indagare su un dettaglio che ti incuriosisce, leggi «Il Signore con tutti è benefico, e in tutte le opere di lui han luogo le sue misericordie». Due letture, poi verifica con pazienza quello che hai notato invece di innamorartene.',
    'salmi_martini|47|Asaliah': 'Prima di dire una parola che pesa sulla vita di altri, leggi «Quanto grandiose son le opere tue, o Signore! ogni cosa hai tu fatto con sapienza: la terra è piena di tue ricchezze». Una lettura lenta basta. Cerca il vero prima del comodo.',
    'salmi_martini|48|Mihael': 'Pensa al legame che ti è più vicino. Leggi, anche insieme all\'altra persona, «Il Signore ha manifestata la sua salute: ha rivelata la sua giustizia agli occhi delle nazioni». Ripetilo due volte. Resta presente anche nei giorni in cui il legame restituisce poco.',
    'salmi_martini|49|Vehuel': 'Prima di valutare il lavoro di qualcuno, leggi «Grande il Signore, e laudabile oltre modo: e la grandezza di lui non ha termine». Ripetilo tre volte con voce piana. Usa il tuo metro alto per riconoscere il valore di chi hai davanti. Non per pesarti addosso.',
    'salmi_martini|4|Elemiah': 'Quando una strada sembra inceppata, fermati un istante e leggi «Volgiti, o Signore, e libera l\'anima mia: per tua misericordia dammi salute». Ripeti il versetto due volte prima di muoverti. Prova a distinguere l\'ostacolo vero dal tumulto che senti dentro. Non cercare subito una soluzione: per ora basta vedere meglio.',
    'salmi_martini|50|Daniel': 'Davanti a una scelta rimandata troppo a lungo, siediti e leggi «Il Signore misericordioso e benigno: paziente e misericordioso grandemente». Ripetilo tre volte senza correre. Ascolta le ragioni di chi la pensa diversamente. Poi passa dal dubbio alla scelta, sapendo che una decisione può costare qualcosa.',
    'salmi_martini|51|Hahasiah': 'Prima di metterti al lavoro su una cosa nuova, leggi «Sia celebrata pei secoli la gloria del Signore: si allegrerà il Signore nelle opere sue». Ripetilo due volte e chiediti come funziona davvero quello che hai davanti. Tieni il metodo, lascia la pretesa di sapere tutto.',
    'salmi_martini|52|Imamiah': 'Quando riconosci un tuo errore, leggi a voce «Glorificherò il Signore per la sua giustizia, e al nome del Signore altissimo canterò inni di laude». Due volte, senza trasformarlo in condanna. Scegli un fatto concreto con cui cominciare a riparare.',
    'salmi_martini|53|Nanael': 'Nel silenzio di un momento di studio, leggi «Ho conosciuto, o Signore, che i giudizi tuoi sono equità; e che secondo la tua verità tu mi hai umiliato». Ripetilo una volta. Pensa a come trasmettere ciò che sai senza umiliare chi ascolta.',
    'salmi_martini|54|Nithael': 'Davanti a una cosa bella che altri non notano, leggi «Il Signore ha preparato in cielo il suo trono, e al regno di lui tutti saranno soggetti». Ripetilo due volte mentre la guardi. Chiediti che cosa di quello che fai può durare oltre te.',
    'salmi_martini|55|Mebahiah': 'Pensa a un principio in cui credi. Leggi «Ma tu, o Signore, duri in eterno, e di generazione in generazione va la ricordanza di te». Dillo due volte e poi scegli un gesto di oggi che lo renda visibile. Le parole dichiarate contano meno dei fatti.',
    'salmi_martini|56|Poyel': 'Quando qualcosa cede, la fiducia o un progetto, leggi «Il Signore sostenta tutti que\', che stan per cadere, e rialza tutti que\' che si sono infranti». Ripetilo tre volte e chiedi soltanto quello che serve davvero. Rialzarsi viene prima di salire.',
    'salmi_martini|57|Nemamiah': 'Prima di una decisione rapida, leggi «Nel Signore hanno sperato quelli, che temono: egli è loro aiuto e lor protettore». Ripetilo due volte separando la sostanza dall\'apparenza. Decidi in fretta solo dopo aver nominato a voce alta ciò che hai capito davvero.',
    'salmi_martini|58|Ieialel': 'Quando la fatica di un lavoro lungo si fa sentire, leggi «E l\'anima mia è grandemente turbata: ma tu, o Signore, fino a quando?». Ripetilo due volte e poi torna sulla cosa che stai facendo. Guardala finché non ne vedi la causa.',
    'salmi_martini|59|Harahel': 'Prima di riordinare carte, appunti o archivi, leggi a voce «Dall\'oriente fino all\'occaso ha da lodarsi il nome del Signore». Ripetilo tre volte, all\'inizio e alla fine del lavoro. Chiediti che cosa di quello che conservi merita di passare a qualcun altro. Giudica con misura.',
    'salmi_martini|5|Mahasiah': 'Prima di studiare o di parlare con una persona che si è allontanata, leggi piano «Cercai il Signore, e mi esaudì: e mi trasse fuori di tutte le mie tribolazioni». Ripetilo tre volte respirando con calma. Osserva il clima che porti nella stanza ancora prima di dire una parola.',
    'salmi_martini|60|Mitzrael': 'Pensa a qualcosa che si è rotto dentro di te o fra te e un\'altra persona. Leggi «Giusto il Signore in tutte le sue vie, e santo in tutte le opere sue». Tre letture, una dopo l\'altra. Scegli la pazienza al posto della rivincita.',
    'salmi_martini|61|Umabel': 'Pensa a un\'amicizia che ti è cara. Leggi a voce, con calma, «Sia benedetto il nome del Signore, da questo punto fino ne\' secoli». Ripetilo due volte sentendo la vicinanza dell\'altra persona. Ricorda però dove finisci tu e dove comincia lei.',
    'salmi_martini|62|Iahhel': 'Prima di rispondere a una domanda difficile, ritirati per un momento e leggi «Mira, o Signore, com\'io ho amati i tuoi precetti: per tua misericordia dammi la vita». Basta una volta. Il silenzio scelto prepara una parola misurata, che arriva al momento giusto.',
    'salmi_martini|63|Anauel': 'Quando due interessi sembrano opposti, leggi «Canti con giubbilo le lodi di Dio tutta quanta la terra: servite il Signore con allegrezza». Ripetilo tre volte cercando il punto in cui le due parti possono incontrarsi. Comincia da lì, con un passo piccolo.',
    'salmi_martini|64|Mehiel': 'Prima di scrivere o di parlare in pubblico, leggi «Ecco gli occhi del Signore sopra coloro che lo temono, e sopra coloro, che confidano nella sua misericordia». Una sola lettura, con tutta l\'attenzione. Unisci quello che senti a quello che ragioni, senza sacrificare nessuno dei due.',
    'salmi_martini|65|Damabiah': 'Vicino a un\'acqua che scorre, anche quella di un rubinetto, leggi «Volgiti a noi, o Signore: e fino a quando (sarai sdegnato)? placati coi servi tuoi». Ripetilo due volte ascoltando il suono dell\'acqua. Ascolta prima di parlare. Attingi alla sorgente che hai dentro.',
    'salmi_martini|66|Manakel': 'La sera, quando la giornata si chiude, leggi sottovoce «Non abbandonarmi, Signore Dio mio, non ti allontanare da me». Ripetilo tre volte prima di dormire. Pensa a ciò che hai lasciato indietro. Lascia che le cose vive crescano col loro ritmo, senza forzarle.',
    'salmi_martini|67|Eiael': 'In un momento di solitudine scelta, in un angolo quieto, leggi «Metti la tua consolazione nel Signore, ed ei ti darà quello, che il tuo cuore domanda». Ripetilo due volte lentamente. Allena lo sguardo: cerca una cosa bella dove di solito passi oltre.',
    'salmi_martini|68|Habuhiah': 'Prima di un gesto generoso, piccolo e concreto, leggi «Date lode al Signore, perchè egli è buono, perchè eterna ell\'è la sua misericordia». Ripetilo tre volte, poi dai senza contare e senza aspettarti un ritorno. Lascia che il gesto parli prima delle parole.',
    'salmi_martini|69|Rochel': 'Quando cerchi chiarezza su qualcosa che è andato perso, leggi «Il Signore è la porzione di mio retaggio e del mio calice: tu se\' quegli, che a me restituirai la mia eredità». Una lettura, poi un respiro lungo. Non avere fretta di giudicare.',
    'salmi_martini|6|Lelahel': 'Tieni in mente una tua capacità. Recita a voce chiara «Cantate inni al Signore, che abita in Sion, annunziate i consigli di lui tralle nazioni». Ripetilo due volte guardando le tue mani. Domandati per chi altro puoi usare quel talento questa settimana. La risposta può arrivare piano: lasciale spazio.',
    'salmi_martini|70|Iabamiah': 'In un passaggio della vita, quando qualcosa finisce e altro comincia, leggi a voce «Al principio creò Dio il cielo e la terra». Tre volte, con pause lunghe. Guarda la forma che cambia. Resta al tuo lavoro mentre accade: la trasformazione si costruisce giorno per giorno.',
    'salmi_martini|71|Haiaiel': 'Quando devi dire no per difendere qualcuno, leggi «Celebrerò altamente colla mia bocca il Signore: e nella numerosa adunanza a lui darò lode». Ripetilo due volte con la mente fredda. Prendi la decisione senza impulso. Non cercare applausi in cambio.',
    'salmi_martini|72|Mumiah': 'Alla fine di un lavoro, prima di passare al successivo, leggi «Torna, o anima mia, nella tua requie: perocchè il Signore ti ha fatto del bene». Ripetilo tre volte e chiudi davvero ciò che è finito. Così ricominci senza trascinarti dietro il vecchio.',
    'salmi_martini|7|Achaiah': 'Scegli una domanda che ti accompagna da tempo e che hai smesso di guardare. Leggi a voce bassa «Il Signore misericordioso e benigno: paziente e misericordioso grandemente». Ripetilo sette volte senza fretta. Ogni ripetizione è un ritorno alla stessa cosa: così la pazienza continua a osservare anche quando l\'interesse cala.',
    'salmi_martini|8|Cahethel': 'Prima di un pasto o a fine lavoro, leggi «Venite, adoriamolo e prostriamoci, e spargiamo lacrime dinanzi al Signore, di cui siamo fattura». Dillo due volte con le mani aperte. Nomina in silenzio una cosa che hai ricevuto e da dove viene. Lascia che quel ricordo guidi il gesto successivo.',
    'salmi_martini|9|Haziel': 'Pensa a un torto che porti ancora con te. Leggi lentamente «Ricordati di tue misericordie, o Signore, delle tue misericordie, che furono nei secoli addietro». A ognuna delle tre letture chiediti se quel peso ti serve ancora. Perdonare resta una scelta tua, da fare senza fretta.',
  };

